// ═══════════════════════════════════════════
//  PIXEL PARTIES — GAME BOARD
//  BoardCard, BoardZone, animations, effects,
//  prompts, and the main GameBoard component
// ═══════════════════════════════════════════
const { useState, useEffect, useRef, useCallback, useMemo, useContext, useLayoutEffect } = React;
const { api, emitSocket, socket, AppContext, CardMini, CardFoil,
        cardImageUrl, skinImageUrl, typeColor, typeClass, CARDS_BY_NAME, SKINS_DB,
        useStickyHoverFlag } = window;

// ═══════════════════════════════════════════
//  TYPEWRITER TEXT (win/loss speech bubbles)
//  Reveals a message letter-by-letter (fast) and renders lightweight
//  markup: *italic* and **bold**. Used for both players' end-game lines.
// ═══════════════════════════════════════════
// Split a string into formatted runs. `**` toggles bold, a lone `*` toggles
// italic; the markers themselves are consumed, not shown.
function parseBubbleMarkup(str) {
  const segs = [];
  let bold = false, italic = false, buf = '';
  const flush = () => { if (buf) { segs.push({ text: buf, bold, italic }); buf = ''; } };
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '*' && str[i + 1] === '*') { flush(); bold = !bold; i++; continue; }
    if (str[i] === '*') { flush(); italic = !italic; continue; }
    buf += str[i];
  }
  flush();
  return segs;
}

// Per-character "is this letter part of a SHOUTED (all-caps) word?" flags.
// A word = a maximal letter-run; it shouts if it's 2+ letters and entirely
// uppercase (so "BOOM"/"HA" bob, but a lone "I"/"A" or "Ha" don't). Shouted
// letters get a slight up/down wobble (.cpu-shout-letter) to read as yelling.
function shoutFlags(text) {
  const flags = new Array(text.length).fill(false);
  const re = /[A-Za-z]+/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const w = m[0];
    if (w.length >= 2 && w === w.toUpperCase()) {
      for (let i = 0; i < w.length; i++) flags[m.index + i] = true;
    }
  }
  return flags;
}

// v1289: auch das Spielerprofil-Popup (app-player-profile.jsx) tippt
// das Motto so ab — Export ueber window, siehe Konvention in build.js.
window.TypewriterText = TypewriterText;
function TypewriterText({ text, speed = 26, bounce = false }) {
  const segs = useMemo(() => parseBubbleMarkup(text || ''), [text]);
  const total = useMemo(() => segs.reduce((n, s) => n + s.text.length, 0), [segs]);
  const [shown, setShown] = useState(0);
  useEffect(() => {
    setShown(0);
    if (!total) return;
    const id = setInterval(() => {
      setShown(prev => {
        if (prev >= total) { clearInterval(id); return prev; }
        return prev + 1;
      });
    }, speed);
    return () => clearInterval(id);
  }, [text, total, speed]);
  // Slice the formatted runs to the number of revealed characters. Within
  // each run, all-caps-word letters become individually-wobbling spans
  // (phase-staggered by absolute position for a trembling "scream" wave);
  // everything else stays plain text.
  let left = shown;
  let offset = 0; // absolute char position across the whole message
  return (
    <>
      {segs.map((s, i) => {
        if (left <= 0) { offset += s.text.length; return null; }
        const piece = s.text.slice(0, left);
        left -= piece.length;
        const flags = shoutFlags(s.text);
        const children = [];
        let buf = '';
        // ALL-CAPS-Fix: die Wobble-Buchstaben sind einzelne
        // inline-block-Spans — für den Zeilenumbruch ist damit JEDER
        // Buchstabe eine eigene Umbruch-Einheit, Caps-Wörter brachen
        // mitten im Wort. Zusammenhängende Shout-Buchstaben werden
        // deshalb in einen whiteSpace:nowrap-Wrapper gruppiert, dann
        // wandert das Wort wie normale Wörter komplett in die nächste
        // Zeile (shoutFlags markiert nur [A-Za-z]-Runs, Leerzeichen
        // trennen die Gruppen also von selbst).
        let word = null;
        const flushWord = (idx) => {
          if (word) {
            children.push(<span key={'w' + idx} style={{ whiteSpace: 'nowrap' }}>{word}</span>);
            word = null;
          }
        };
        for (let c = 0; c < piece.length; c++) {
          // `bounce`: bei Gegnern wie Waflav wackelt JEDER Buchstabe leicht,
          // nicht nur die geschrienen Caps. Geschriene bleiben auf der
          // staerkeren Shout-Animation — sonst ginge der Unterschied
          // zwischen normalem Sprechen und Bruellen verloren.
          if (bounce && !flags[c] && piece[c].trim()) {
            if (buf) { children.push(buf); buf = ''; }
            flushWord(c);
            children.push(
              <span key={'b' + c} className="cpu-bounce-letter" style={{ animationDelay: ((offset + c) * -0.09) + 's' }}>{piece[c]}</span>
            );
            continue;
          }
          if (flags[c]) {
            if (buf) { children.push(buf); buf = ''; }
            (word = word || []).push(
              <span key={'s' + c} className="cpu-shout-letter" style={{ animationDelay: ((offset + c) * -0.07) + 's' }}>{piece[c]}</span>
            );
          } else {
            flushWord(c);
            buf += piece[c];
          }
        }
        flushWord(piece.length);
        if (buf) children.push(buf);
        offset += s.text.length;
        return (
          <span key={i} style={{ fontWeight: s.bold ? 800 : undefined, fontStyle: s.italic ? 'italic' : undefined }}>{children}</span>
        );
      })}
    </>
  );
}

// ═══════════════════════════════════════════
//  SHARED BOARD TOOLTIP SYSTEM
//  Single tooltip rendered in GameBoard, driven
//  by mouse events from BoardCard / CardRevealEntry.
//  Eliminates orphan portal tooltips.
// ═══════════════════════════════════════════
let _activeLuckTooltipTarget = null;
let _boardTooltipLocked = false;
// While a card is being dragged, suppress all card-hover tooltips — the
// preview gets in the way of seeing the drop target. Flipped from the
// drag-state effect below and consulted on every setBoardTooltip(...)
// call, so any hover that tries to open a preview mid-drag is ignored.
let _isDraggingCard = false;
// v880 (Als Befund): Der zuletzt gezeigte REICHE Tooltip. Die
// Status-Abzeichen sitzen am Rand der Karte; beim Hinuebergleiten
// feuert deren `mouseLeave`, und `StatusBadges` setzte den Tooltip
// danach aus der STATISCHEN Kartenliste neu — ohne aktuelle HP, ohne
// die wirklich angelegten Abilities. Sah aus wie eine alte Fassung des
// Tooltips. Hier wird der zuletzt gesetzte Stand gemerkt, damit die
// Abzeichen genau denselben wieder aufrufen koennen.
// v881 (Als Befund): Die Status-Abzeichen liegen AUF der Karte. Beim
// Wechsel Karte ↔ Abzeichen feuern `mouseLeave` und `mouseEnter` in
// wechselnder Reihenfolge; kam das Leave der Karte NACH dem Enter des
// Abzeichens, loeschte es den gerade neu gesetzten Tooltip und nichts
// holte ihn zurueck. Statt die Reihenfolge zu erraten, sperren die
// Abzeichen das Loeschen fuer die Dauer ihres Hovers — dieselbe
// Klammer, die die Prompt-Kartenbilder schon benutzen.
window._boardTooltipLock = (an) => { _boardTooltipLocked = !!an; };

// Hinweis (v885): Hier stand ein aufgeschobenes Ausblenden, das die
// Naht zwischen Karte und Status-Abzeichen ueberbruecken sollte. Es hat
// den Fehler nicht behoben und den Tooltip spuerbar klebrig gemacht —
// auf Als Wunsch zurueckgebaut. Siehe die Notiz bei `StatusBadges` in
// app-shared.jsx.
function setBoardTooltip(card) {
  if (card && card.name) window._boardTooltipLast = card;
  // When locked (prompt card hovered), ignore external clears
  if (!card && _boardTooltipLocked) return;
  if (card && _isDraggingCard) return;
  window._boardTooltipSetter?.(card);
}


// ── Rusting Crystal / BGG cost helpers ───────────────────────
// Mirror of `applyRustingCrystalCostMultiplier` in server.js so the
// hand-card cost UI matches what the server actually charges. While
// a copy of "Rusting Crystal" sits in `me`'s hand, the base cost of
// every OTHER Artifact is doubled — unless "Big Gwen Guard" is in
// one of `me`'s Support Zones (its passive aura suppresses all self-
// reveal Crystal effects). Idempotent / non-stacking: multiple
// Rusting Crystals still produce a single ×2.
function _meControlsBigGwenGuard(me) {
  if (!me?.supportZones) return false;
  for (const heroZones of me.supportZones) {
    if (!Array.isArray(heroZones)) continue;
    for (const slot of heroZones) {
      if (Array.isArray(slot) && slot.includes('Big Gwen Guard')) return true;
    }
  }
  return false;
}

function applyCrystalCostMods(me, cardName, baseCost) {
  if (!me || cardName === 'Rusting Crystal') return baseCost;
  if (!(me.hand || []).includes('Rusting Crystal')) return baseCost;
  if (_meControlsBigGwenGuard(me)) return baseCost;
  return baseCost * 2;
}

function BoardCard({ cardName, faceDown, flipped, label, hp, maxHp, atk, hpPosition, style, noTooltip, skins, tooltipCardOverride, inheritedEffects, copiedHeroes, revealTooltipWhenFaceDown, abilities, effectiveLevel, stampBonus, showLevelBadge }) {
  const card = faceDown ? null : CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name, skins) : null;
  // A caller (e.g. Biomancy Token in the puzzle builder) can override what
  // the hover tooltip renders without changing the card image / name by
  // passing `tooltipCardOverride`. Falls back to the canonical card.
  // When the BoardCard renders with live stats (hero / creature on the
  // battle board), pass them through to the tooltip via `_liveHp` /
  // `_liveMaxHp` / `_liveAtk` so the hover preview shows
  // `currentHp / maxHp` and current ATK instead of the base card-DB
  // values. CardTooltipContent prefers `_live*` over `card.*`.
  // `inheritedEffects` (an array of `{label, text}`) is mirrored from
  // the engine's per-instance `_inheritedEffects` counter for cards that
  // pick up rules text from another card (Sparkfly Queen carrying the
  // gift of a sacrificed Sparkfly via Hive's Crown today; any future
  // card that populates the same counter benefits for free).
  //
  // `revealTooltipWhenFaceDown` is an explicit puzzle-creator opt-in:
  // the card stays visually a cardback but its identity is exposed via
  // the hover tooltip. Live battle never sets this (would leak hidden
  // info). Used today by the Puzzle Creator's opp-side Surprise zones
  // so the author can inspect what they've placed without flipping it.
  const tooltipCardData = (faceDown && revealTooltipWhenFaceDown)
    ? CARDS_BY_NAME[cardName]
    : card;
  const tooltipBase = tooltipCardOverride || tooltipCardData;
  const tooltipTarget = (() => {
    if (!tooltipBase) return null;
    const hasLiveAbilities = Array.isArray(abilities) && abilities.length > 0;
    if (hp == null && maxHp == null && atk == null && effectiveLevel == null && (!inheritedEffects || inheritedEffects.length === 0) && (!copiedHeroes || copiedHeroes.length === 0) && !hasLiveAbilities) return tooltipBase;
    return {
      ...tooltipBase,
      _liveHp:    hp    != null ? hp    : tooltipBase._liveHp,
      _liveMaxHp: maxHp != null ? maxHp : tooltipBase._liveMaxHp,
      _liveAtk:   atk   != null ? atk   : tooltipBase._liveAtk,
      // Lethe pile-stamp aware level — feeds CardTooltipContent's
      // stats line so the hover preview shows the effective Lv (with
      // a "(+N)" suffix when the bonus is non-zero).
      _liveLevel: effectiveLevel != null ? effectiveLevel : tooltipBase._liveLevel,
      _stampBonus: stampBonus != null ? stampBonus : tooltipBase._stampBonus,
      _inheritedEffects: (inheritedEffects && inheritedEffects.length > 0)
        ? inheritedEffects
        : tooltipBase._inheritedEffects,
      // v981 (Als Vorgabe 12.9.): Namen der Helden, deren Effekte dieser
      // Held gerade mittraegt (Dangerous Knowledge, Initiation Ritual).
      // Stehen GANZ OBEN im Tooltip, direkt unter dem Namen.
      _copiedHeroes: (copiedHeroes && copiedHeroes.length > 0)
        ? copiedHeroes
        : tooltipBase._copiedHeroes,
      // `_liveAbilities` is the per-Hero `abilityZones[heroIdx]`
      // shape — an array of slot arrays, each slot a stack of names
      // (`['Fighting','Fighting']`, `['Toughness']`, `[]`). The
      // tooltip dedupes by base name and renders `Fighting 2`
      // instead of `Fighting, Fighting`. Falls back to the static
      // cards.json `startingAbility1/2` only for off-board card
      // previews where the live stack isn't available.
      _liveAbilities: hasLiveAbilities ? abilities : tooltipBase._liveAbilities,
    };
  })();

  // Foil support — Bänder, Schimmer und Funken kommen komplett aus
  // `CardFoil` (app-shared, v1203). Hier bleibt nur die Randklasse, die
  // am Kartenrahmen selbst haengt.
  const foilType = card?.foil || null;
  const foilClass = foilType === 'diamond_rare' ? 'foil-diamond-rare' : foilType === 'secret_rare' ? 'foil-secret-rare' : '';

  return (
    <div className={'board-card' + (faceDown ? ' face-down' : '') + (flipped ? ' flipped' : '') + (foilClass ? ' ' + foilClass : '')}
      style={style}
      onMouseEnter={() => !noTooltip && (revealTooltipWhenFaceDown || !faceDown) && tooltipTarget && setBoardTooltip(tooltipTarget)}
      onMouseLeave={() => setBoardTooltip(null)}
      onTouchStart={() => {
        if (noTooltip || (faceDown && !revealTooltipWhenFaceDown) || !tooltipTarget) return;
        window._longPressFired = false;
        window._longPressTimer = setTimeout(() => {
          window._longPressFired = true;
          setTapTooltip(tooltipTarget.name);
          setBoardTooltip(tooltipTarget);
        }, window.LONG_PRESS_MS || 400);
      }}>
      <CardFoil card={card} />
      {faceDown ? (
        <img src="/cardback.png" style={{ width: '100%', height: '100%', objectFit: 'cover' }} draggable={false} />
      ) : imgUrl ? (
        <img src={imgUrl} style={{ width: '100%', height: '100%', objectFit: 'cover' }} draggable={false} />
      ) : (
        <div className="board-card-text">{cardName || '?'}</div>
      )}
      {label && <div className="board-card-label">{label}</div>}
      {/* Pile-level badge — only shown when the caller opts in via
          `showLevelBadge` (BoardZone for discard / deleted does so).
          Support-zone Creatures suppress this and use the existing
          `.creature-level` badge below the board grid, which already
          accounts for `actionChangeLevel` deltas and Lethe bonuses.
          Purple-tinted + glow when `stampBonus > 0`. */}
      {showLevelBadge && effectiveLevel != null && !faceDown && (
        <div style={{
          position: 'absolute', top: 3, left: 3,
          background: 'rgba(0,0,0,.85)',
          color: stampBonus > 0 ? '#c4a8ff' : '#fff',
          padding: '2px 6px', borderRadius: 4,
          fontSize: 11, fontWeight: 700,
          border: '1px solid ' + (stampBonus > 0 ? '#a288ff' : 'rgba(255,255,255,0.3)'),
          pointerEvents: 'none', zIndex: 4,
          boxShadow: stampBonus > 0 ? '0 0 6px rgba(162,136,255,.6)' : 'none',
        }}>Lv {effectiveLevel}{stampBonus > 0 ? ` (+${stampBonus})` : ''}</div>
      )}
      {hp != null && maxHp != null && hp > maxHp && (
        <div className="board-card-overheal-barrier" />
      )}
      {/* Hero cards: HP + ATK go through the responsive flex strip so
          they auto-stack vertically on cards too narrow to fit both
          numbers on one row. Other positions (creature) keep the
          single-stat absolute layout. */}
      {hpPosition === 'hero' ? (
        (hp != null || atk != null) && (
          <div className="board-card-stats-hero">
            {hp != null && (
              <div className="board-card-hp-num"
                style={maxHp != null && hp > maxHp ? { color: '#44ff88' } : undefined}>
                {hp}
              </div>
            )}
            {atk != null && (
              <div className="board-card-atk-num">{atk}</div>
            )}
          </div>
        )
      ) : (
        hp != null && hpPosition && (
          <div className={'board-card-hp board-card-hp-' + hpPosition}
            style={maxHp != null && hp > maxHp ? { color: '#44ff88' } : undefined}>
            {hp}
          </div>
        )
      )}
    </div>
  );
}

function BoardZone({ type, cards, label, faceDown, flipped, stackLabel, children, onClick, onHoverCard, style, className, dataAttrs, ownerLetheStamps, badge, pileIdentities, renderStack }) {
  const cls = 'board-zone board-zone-' + type + (className ? ' ' + className : '') + ((cards?.length > 0) ? ' zone-has-card' : '');
  const topCardName = cards && cards.length > 0 && !faceDown ? cards[cards.length - 1] : null;
  const suppressChildTooltip = !!onClick && !!onHoverCard;
  // For discard/deleted zones, the top card's effective level is the
  // base printed level plus the max Lethe stamp on any copy of that
  // name in the owner's combined piles. The same value `effectiveCardLevel`
  // uses, so the player sees exactly what the revival gates will see.
  const topLevelInfo = (() => {
    if (!topCardName || (type !== 'discard' && type !== 'deleted')) return null;
    const cd = CARDS_BY_NAME[topCardName];
    if (!cd || cd.cardType !== 'Creature' || cd.level == null) return null;
    const arr = ownerLetheStamps?.[topCardName];
    let stamp = 0;
    if (Array.isArray(arr)) for (const v of arr) if (v > stamp) stamp = v;
    return { effectiveLevel: (cd.level || 0) + stamp, stampBonus: stamp };
  })();
  // BoardZone-level hover dispatch. The shared pile-hover tooltip
  // (rendered at the page root) accepts EITHER a bare card-name string
  // OR an enriched `{ name, effectiveLevel, stampBonus }` object so it
  // can render the Lethe-stamped level without re-reading the player
  // state. Pile/stack hovers without stamp info fall through to the
  // string form — the tooltip handles both shapes.
  // Geliehene Identitaet (Future Tech Copy Device): liegt die oberste
  // Karte der Ablage gerade als etwas anderes dort, zeigt der Hover
  // DIESE Karte — dieselbe Auskunft, die eine als Equip liegende Kopie
  // ueber ihr Kartenbild gibt (Als Vorgabe 22.8.).
  // ★ Der Stapel zeigt nur die OBERSTE Karte, und welche physische
  //   Kopie das ist, weiss der Client nicht. Deshalb wird hier nur
  //   umgeschaltet, wenn JEDE Kopie dieses Namens umbenannt ist —
  //   sonst waere die Anzeige geraten. Im Ablage-Dialog steht es
  //   ohnehin genau.
  // ★ Die oberste Karte ist der LETZTE Stapelplatz — mit den
  //   Eintraegen je Platz laesst sich ihre Identitaet exakt ablesen.
  //   (Vorher musste geraten werden, weil nur Namen vorlagen.)
  const topIdentity = (() => {
    if (!topCardName || !Array.isArray(pileIdentities)) return null;
    const e = pileIdentities[(cards || []).length - 1];
    return (e && e.name === topCardName && e.identity) ? e.identity : null;
  })();
  const hoverPayload = topCardName == null ? null : ((topLevelInfo || topIdentity)
    ? {
      name: topCardName,
      effectiveLevel: topLevelInfo?.effectiveLevel,
      stampBonus: topLevelInfo?.stampBonus,
      identity: topIdentity || undefined,
    }
    : topCardName);
  return (
    <div className={cls + (onClick && cards?.length > 0 ? ' board-zone-clickable' : '')}
      style={style}
      {...(dataAttrs || {})}
      onClick={onClick && cards?.length > 0 ? onClick : undefined}
      onMouseEnter={() => hoverPayload && onHoverCard && !window.activeDragData && !window.deckDragState && onHoverCard(hoverPayload)}
      onMouseLeave={() => onHoverCard && onHoverCard(null)}>
      {/* Zonen-Badge (Doom Clock: Zaehlerstand). Rein informativ,
          faengt keine Klicks ab. */}
      {badge ? (
        <span className="board-zone-badge">{badge}</span>
      ) : null}
      {/* ── Opt-in-Renderer (v1050) ────────────────────────────────
          Die Standard-Darstellung eines Stapels zeigt NUR die oberste
          Karte samt Stueckzahl — richtig fuer Ablage und Deck, falsch
          fuer die Area-Zone, seit dort mehrere Areas GLEICHZEITIG
          liegen und jede einzeln anklickbar sein muss. `renderStack`
          laesst die Aufrufstelle die Darstellung uebernehmen, ohne dass
          BoardZone Area-Wissen bekommt. Ohne die Prop aendert sich
          nichts. */}
      {cards && cards.length > 0 ? (
        renderStack ? renderStack(cards) : (
        cards.length === 1 ? (
          <BoardCard cardName={cards[0]} faceDown={faceDown} flipped={flipped} label={stackLabel} noTooltip={suppressChildTooltip}
            effectiveLevel={topLevelInfo?.effectiveLevel} stampBonus={topLevelInfo?.stampBonus} showLevelBadge={topLevelInfo != null} />
        ) : (
          <div className="board-stack">
            <BoardCard cardName={cards[cards.length - 1]} faceDown={faceDown} flipped={flipped} label={stackLabel || (cards.length + '')} noTooltip={suppressChildTooltip}
              effectiveLevel={topLevelInfo?.effectiveLevel} stampBonus={topLevelInfo?.stampBonus} showLevelBadge={topLevelInfo != null} />
          </div>
        ))
      ) : children || (
        <div className="board-zone-empty">{label || ''}</div>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
//  ★ v1206 — WELCHE KARTE IST NEU IN EINER ZONE?
//
//  Der Einschlagseffekt soll bei JEDER Platzierung laufen — aus der
//  Hand gespielt, per Effekt beschworen, wiederbelebt, gestohlen,
//  umgezogen, im Puzzle geladen. Einen Kanal je Weg abzuhorchen waere
//  ein Fass ohne Boden (allein die Kartenskripte platzieren an Dutzenden
//  Stellen). Also wird nicht der WEG beobachtet, sondern das ERGEBNIS:
//  jede Zustandsaenderung liefert eine Belegungstabelle
//  `Platzschluessel -> Stapelhoehe|oberste Karte`, und was sich darin
//  aendert, ist eine Platzierung.
//
//  Der Schluessel traegt die Art mit (`h` Held, `a` Ability, `s`
//  Support, `x` Surprise, `r` Area, `p` Permanent), damit die
//  Gegenstelle daraus den DOM-Selektor bauen kann.
// ═══════════════════════════════════════════════════════════════
function zonenBelegung(gs) {
  const m = new Map();
  if (!gs) return m;
  const oben = (arr) => (arr && arr.length) ? (arr.length + '|' + arr[arr.length - 1]) : null;
  for (const pi of [0, 1]) {
    const p = gs.players?.[pi];
    if (!p) continue;
    (p.heroes || []).forEach((h, hi) => { if (h?.name) m.set(`h:${pi}:${hi}`, h.name); });
    (p.abilityZones || []).forEach((zonen, hi) => (zonen || []).forEach((slot, si) => {
      const v = oben(slot); if (v) m.set(`a:${pi}:${hi}:${si}`, v);
    }));
    (p.supportZones || []).forEach((zonen, hi) => (zonen || []).forEach((slot, si) => {
      const v = oben(slot); if (v) m.set(`s:${pi}:${hi}:${si}`, v);
    }));
    (p.surpriseZones || []).forEach((slot, hi) => {
      const v = oben(slot); if (v) m.set(`x:${pi}:${hi}`, v);
    });
    (p.permanents || []).forEach((perm) => {
      if (perm?.name) m.set(`p:${pi}:${perm.id != null ? perm.id : perm.name}`, perm.name);
    });
  }
  (gs.areaZones || []).forEach((arr, pi) => (arr || []).forEach((n, i) => {
    if (n) m.set(`r:${pi}:${i}`, n);
  }));
  return m;
}

/** Platzschluessel -> DOM-Selektor der zugehoerigen Zone. */
function zonenSelektor(schluessel, myIdx) {
  const t = schluessel.split(':');
  const art = t[0];
  const seite = Number(t[1]) === myIdx ? 'me' : 'opp';
  if (art === 'h') return `[data-hero-zone][data-hero-owner="${seite}"][data-hero-idx="${t[2]}"]`;
  if (art === 'a') return `[data-ability-zone][data-ability-owner="${seite}"][data-ability-hero="${t[2]}"][data-ability-slot="${t[3]}"]`;
  if (art === 's') return `[data-support-zone][data-support-owner="${seite}"][data-support-hero="${t[2]}"][data-support-slot="${t[3]}"]`;
  if (art === 'x') return `[data-surprise-zone][data-surprise-owner="${seite}"][data-surprise-hero="${t[2]}"]`;
  if (art === 'r') return `[data-area-zone][data-area-owner="${seite}"]`;
  if (art === 'p') return seite === 'me' ? '.board-permanents-me' : '.board-permanents-opp';
  return null;
}

// Briefly tints a board-zone red to signal that the hero/creature in
// that slot just took damage. Restarts the animation if the same slot
// is hit twice in quick succession (e.g. multi-hit attacks).
function flashDamageOnZone(selector) {
  const el = document.querySelector(selector);
  if (!el) return;
  el.classList.remove('damage-flashing');
  // Force reflow so the animation restarts when the class is re-added.
  void el.offsetWidth;
  el.classList.add('damage-flashing');
  setTimeout(() => el.classList.remove('damage-flashing'), 500);
}

// Floating damage number that finds its target hero and animates above it
function DamageNumber({ amount, ownerLabel, heroIdx }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const el = document.querySelector(`[data-hero-zone][data-hero-owner="${ownerLabel}"][data-hero-idx="${heroIdx}"]`);
    if (el) {
      // ★ v1257: Mobile-Kamera auf die getroffene Zone (no-op am Desktop
      // und im eigenen Zug — siehe ppBattleCamFocus).
      if (window.ppBattleCamFocus) window.ppBattleCamFocus(el);
      const r = el.getBoundingClientRect();
      const _wo = window.ppFxWeltAnker ? window.ppFxWeltAnker(el) : { dx: 0, dy: 0 };  // ★ v1258 Weltverankerung
      setPos({ x: r.left + r.width / 2 + _wo.dx, y: r.top + r.height * 0.3 + _wo.dy });
    }
  }, [ownerLabel, heroIdx]);

  if (!pos) return null;
  // Damage absorbed to 0 → render the bare "0" (no minus sign), so
  // the player sees that the hit was absorbed rather than blocked
  // entirely. Matches the CreatureDamageNumber and HealNumber forms.
  const label = amount > 0 ? `-${amount}` : '0';
  return (
    <div className="damage-number" style={{ left: pos.x, top: pos.y }}>
      {label}
    </div>
  );
}

