// Floating card that animates from deck position to hand slot position
function DrawAnimCard({ cardName, origIdx, startX, startY, dimmed }) {
  const [endPos, setEndPos] = useState(null);

  useEffect(() => {
    // Wait one frame for the invisible hand slot to be laid out
    requestAnimationFrame(() => {
      const targetSlot = document.querySelector(`.game-hand-me .hand-slot[data-hand-idx="${origIdx}"]`);
      if (targetSlot) {
        const r = targetSlot.getBoundingClientRect();
        // ★ v1233: Der Platz traegt den Faecher-Bogen, ist aber nie
        // gedreht — `r` ist also weiterhin der echte Landepunkt. Den
        // WINKEL holt die fliegende Karte sich hier ab und dreht sich
        // waehrend des Flugs hinein, sonst sprang sie beim Ankommen.
        setEndPos({
          x: r.left, y: r.top,
          rot: targetSlot.style.getPropertyValue('--fan-rot') || '0deg',
        });
      }
    });
  }, [origIdx]);

  // Before we know the end position, render at deck position (hidden)
  if (!endPos) return null;

  // ★ v1260 (Als Befund 20.9.: „draw (either deck) → Hand hat dasselbe
  // Problem wie Hand → Deck — die Karte beginnt beim Deck nicht
  // mittig"). Gleiche Ursache wie bei DiscardAnimCard (v1259): der
  // Startpunkt ist „Stapelmitte − 32/45", also die Ecke einer 64×90-
  // Karte, die Huelle hat aber Handmass und schrumpft am Start um ihre
  // eigene Mitte — die lag um (Breite/2 − 32, Hoehe/2 − 45) neben dem
  // Stapel. Jetzt: Huelle MITTIG auf den Stapel setzen, der Weg zum
  // Handplatz rechnet die halbe Handkarte wieder heraus.
  const cx = startX + 32, cy = startY + 45;
  const left = `calc(${cx}px - var(--hand-card-w) / 2)`;
  const top = `calc(${cy}px - var(--hand-card-h) / 2)`;
  const dx = `calc(${endPos.x - cx}px + var(--hand-card-w) / 2)`;
  const dy = `calc(${endPos.y - cy}px + var(--hand-card-h) / 2)`;

  return (
    <div className={'draw-anim-card' + (dimmed ? ' hand-card-dimmed' : '')}
      style={{ left, top, '--dx': dx, '--dy': dy, '--fan-rot': endPos.rot || '0deg' }}>
      <BoardCard cardName={cardName} />
    </div>
  );
}

// Colored Snow's two-phase Potion reveal. Phase 1 (`exiting === false`)
// runs the in-and-flip keyframes via the base `colored-snow-reveal-card`
// class — the card flies from `startX/Y` to `centerX/Y`, flips face-up,
// and HOLDS at center until the script signals phase 2. Phase 2 toggles
// the `exiting` class on, swapping the animation to the fly-to-
// destination keyframes that target `endX/Y`.
function ColoredSnowRevealCard({ startX, startY, centerX, centerY, endX, endY, exiting, handoff, cardName, cardbackUrl }) {
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  const exitClass = handoff ? ' handoff' : (exiting ? ' exiting' : '');
  return (
    <div className={'colored-snow-reveal-card' + exitClass}
      style={{
        '--sx': startX + 'px', '--sy': startY + 'px',
        '--cx': centerX + 'px', '--cy': centerY + 'px',
        '--ex': (endX ?? centerX) + 'px', '--ey': (endY ?? centerY) + 'px',
      }}>
      <div className="colored-snow-reveal-inner">
        <div className="colored-snow-reveal-back">
          <img src={cardbackUrl || '/cardback.png'} draggable={false} />
        </div>
        <div className="colored-snow-reveal-front">
          {imgUrl ? <img src={imgUrl} draggable={false} />
            : <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg3)', fontSize: 10, color: 'var(--text)', textAlign: 'center', padding: 4 }}>{cardName}</div>}
        </div>
      </div>
    </div>
  );
}

// Opponent draw animation — face-down card flies from opp deck to opp hand
// Kassaran reveal flip — top card flies from deck pile to screen center,
// flips face-up there, then continues to the destination (hand on match
// or back to deck top on miss). All timing is CSS-driven; this component
// just sets the start / center / end CSS vars and the cardback / face-up
// images. Auto-removed by the scheduler that mounted it after the
// keyframes complete.
function KassaranFlipCard({ startX, startY, centerX, centerY, endX, endY, cardName, cardbackUrl, durationMs }) {
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  // ★ v1259 (Als Befund 20.9.): die Deck-oben-Umdreh-Animation (Chaos
  // Magic, Kassaran, Muehlen-Aufdeckung) war STUMM. Drei Klaenge, an den
  // Keyframes von `kassaran-flight`/`kassaran-flip` festgemacht:
  //   0 %   Karte loest sich vom Deck        → 'draw'
  //   25 %  Karte dreht sich in der Mitte    → 'reveal'
  //   75 %  Karte fliegt weiter zum Ziel     → 'discard'
  // Prozentwerte skalieren mit `durationMs`, damit auch die schnelle
  // Muehlen-Variante auf ihren Bildern sitzt.
  useEffect(() => {
    const dur = durationMs || 2000;
    const sfx = (name) => { if (window.playSFX) window.playSFX(name, { dedupe: 60, category: 'effect' }); };
    sfx('draw');
    const t1 = setTimeout(() => sfx('reveal'), dur * 0.25);
    const t2 = setTimeout(() => sfx('discard'), dur * 0.75);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);
  return (
    <div className="kassaran-flip-card"
      style={{
        '--sx': startX + 'px', '--sy': startY + 'px',
        '--cx': centerX + 'px', '--cy': centerY + 'px',
        '--ex': endX + 'px', '--ey': endY + 'px',
        // Optional faster reveals (mill_center_reveal) — the CSS
        // animations read `var(--kfDur, 2000ms)`, so existing users
        // (Kassaran, Chaos Magic) keep the 2000ms default untouched.
        ...(durationMs ? { '--kfDur': durationMs + 'ms' } : {}),
      }}>
      <div className="kassaran-flip-inner">
        <div className="kassaran-flip-back">
          <img src={cardbackUrl || '/cardback.png'} draggable={false} />
        </div>
        <div className="kassaran-flip-front">
          {imgUrl ? <img src={imgUrl} draggable={false} />
            : <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg3)', fontSize: 10, color: 'var(--text)', textAlign: 'center', padding: 4 }}>{cardName}</div>}
        </div>
      </div>
    </div>
  );
}

// Birthday Present 3-card reveal & pick UI.
//
//   `state` shape:
//     {
//       cards:        [name0, name1, name2],
//       ownerIdx, oppIdx,
//       cardbackUrl:  string (owner's cardback),
//       chosen:       null | string (set when pick lands),
//       flights:      null | [{ cardName, toX, toY }, ...]
//                              (set 200ms after chosen, triggers fly-out),
//     }
//   `interactive` is true on opp's client while the
//   `birthdayPresentPick` prompt is open — enables click-to-pick on each
//   of the three cards. Activator-side renders the same cards with
//   `pointer-events: none` so they just watch.
// ── Karte erscheint in der Hand (v995) ─────────────────────────────
// Kein Flug — die Karte kommt von ausserhalb des Spiels und hat keinen
// Herkunftsort. Gezeigt wird ein warmes Aufleuchten ueber der Hand mit
// aufsteigenden Funken, dazu ein kurzer Lichtring.
// ★ v998 (Als Befund, dritter Anlauf): GAR NICHT MEHR MESSEN.
// Zwei Anlaeufe ueber `getBoundingClientRect` sassen daneben, weil die
// Handplaetze schrumpfen und die Karten ueberlappen — die gemessene
// Box war mal der Slot, mal die Karte, und die Rechnung stimmte nie
// zuverlaessig. Der Effekt wird jetzt INNERHALB des Handplatzes
// gezeichnet und per CSS auf die Kartenmitte gesetzt: eine Karte ist
// 64×90 px mal `--board-scale`, ihre Mitte liegt also fest bei
// 32/45 px vom linken oberen Eck des Platzes. Kein DOM, keine Messung,
// kein Versatz.
function HandMaterializeFxInline() {
  return (
    <div className="hand-materialize-fx">
      <HandFxParticles />
    </div>
  );
}

/** Die Funken/Leuchten selbst — von beiden Varianten benutzt. */
function HandFxParticles() {
  const funken = useMemo(() => Array.from({ length: ppFxN(16) }, () => ({
    dx: (Math.random() - 0.5) * 150,
    dy: -30 - Math.random() * 80,
    groesse: 3 + Math.random() * 5,
    dur: 620 + Math.random() * 420,
    delay: Math.random() * 260,
    farbe: ['#fff3c0', '#ffd77a', '#ffffff', '#ffe6a8'][Math.floor(Math.random() * 4)],
  })), []);
  return (
    <>
      <div style={{
        position: 'absolute', left: -90, top: -60, width: 180, height: 120, borderRadius: '50%',
        background: 'radial-gradient(ellipse, rgba(255,235,160,.75) 0%, rgba(255,200,80,.35) 45%, transparent 78%)',
        animation: 'handFxGlow 900ms ease-out forwards', opacity: 0,
      }} />
      <div style={{
        position: 'absolute', left: -54, top: -36, width: 108, height: 72, borderRadius: '50%',
        border: '2px solid rgba(255,225,140,.9)', boxShadow: '0 0 18px rgba(255,205,90,.8)',
        animation: 'handFxRing 700ms ease-out forwards', opacity: 0,
      }} />
      {funken.map((f, i) => (
        <div key={'hf' + i} style={{
          position: 'absolute', left: 0, top: 0,
          width: f.groesse, height: f.groesse, borderRadius: '50%',
          background: f.farbe, boxShadow: `0 0 7px ${f.farbe}`,
          '--hfdx': f.dx + 'px', '--hfdy': f.dy + 'px',
          animation: `handFxSpark ${f.dur}ms ease-out ${f.delay}ms forwards`, opacity: 0,
        }} />
      ))}
      <style>{`
        @keyframes handFxGlow {
          0%   { opacity: 0; transform: scale(.5); }
          25%  { opacity: 1; transform: scale(1); }
          100% { opacity: 0; transform: scale(1.25); }
        }
        @keyframes handFxRing {
          0%   { opacity: 0; transform: scale(.4); }
          35%  { opacity: 1; transform: scale(1); }
          100% { opacity: 0; transform: scale(1.6); }
        }
        @keyframes handFxSpark {
          0%   { opacity: 0; transform: translate(0, 0) scale(.6); }
          20%  { opacity: 1; }
          100% { opacity: 0; transform: translate(var(--hfdx), var(--hfdy)) scale(.4); }
        }
      `}</style>
    </>
  );
}

function HandMaterializeFx({ x, y }) {
  // Gegnerseite: dort gibt es keine Handindizes, also weiter der
  // gemessene Weg (Mitte des Gegner-Handbereichs reicht — man sieht
  // seine Karten ohnehin nur als Ruecken).
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10130 }}>
      <HandFxParticles />
    </div>
  );
}

// ── Deck-Peek: aufgedeckte Karten liegen in der Bildmitte ──────────
// (v968, „Spice Mortar", Als Vorgabe 12.9.)
//
// Die Karten fliegen EINZELN vom Deck in ein Raster in der Bildmitte
// und BLEIBEN dort liegen — der Mitten-Auftritt des Mills
// (`mill_center_reveal`) laesst sie weiterfliegen, hier bilden sie
// stattdessen die Galerie, in der gewaehlt wird.
//
//   `state`: { cards: [{ name, selectable, highlight }], src: {x,y},
//              chosen: null|string, done: bool }
//   `interactive`: der Wahlberechtigte hat den `deckPeekPick`-Prompt
//   offen — nur dann sind waehlbare Karten anklickbar.
function DeckPeekReveal({ state, interactive, onPick, onDone, title }) {
  const { cards, src, chosen, leaving, takeTo } = state;
  const PRO_REIHE = 5, BREITE = 92, HOEHE = 129, LUECKE = 10;
  const reihen = Math.ceil(cards.length / PRO_REIHE);
  const gesamtHoehe = reihen * HOEHE + (reihen - 1) * LUECKE;
  const oben = window.innerHeight / 2 - gesamtHoehe / 2 - 24;

  return (
    <>
      {cards.map((eintrag, i) => {
        const reihe = Math.floor(i / PRO_REIHE);
        const inReihe = Math.min(PRO_REIHE, cards.length - reihe * PRO_REIHE);
        const spalte = i - reihe * PRO_REIHE;
        const reihenBreite = inReihe * BREITE + (inReihe - 1) * LUECKE;
        const tx = window.innerWidth / 2 - reihenBreite / 2 + spalte * (BREITE + LUECKE);
        const ty = oben + reihe * (HOEHE + LUECKE);
        const card = CARDS_BY_NAME[eintrag.name];
        const waehlbar = interactive && eintrag.selectable && !chosen && !leaving;
        const cls = ['deck-peek-card'];
        if (waehlbar) cls.push('pickable');
        if (!eintrag.selectable) cls.push('dimmed');
        if (chosen === eintrag.name) cls.push('taken');
        else if (leaving) cls.push('leaving');
        return (
          <div key={eintrag.name + '-' + i}
            className={cls.join(' ')}
            style={{
              '--sx': (src?.x ?? window.innerWidth / 2) + 'px',
              '--sy': (src?.y ?? 0) + 'px',
              '--tx': tx + 'px', '--ty': ty + 'px',
              '--delay': (i * 190) + 'ms',
              ...(chosen === eintrag.name && takeTo
                ? { '--ex': takeTo.x + 'px', '--ey': takeTo.y + 'px' } : {}),
            }}
            onClick={waehlbar ? () => { if (window.playSFX) window.playSFX('ui_click'); onPick(eintrag.name); } : undefined}
            onMouseEnter={() => { if (card && window._boardTooltipSetter && !window.activeDragData) window._boardTooltipSetter(card); }}
            onMouseLeave={() => { if (window._boardTooltipSetter) window._boardTooltipSetter(null); }}>{/* v1259: Tooltip wie bei Zi/Birthday Present */}
            {card ? <img src={cardImageUrl(card.name)} alt={card.name} draggable={false} />
              : <div style={{ width: '100%', height: '100%', background: 'var(--bg3)', color: 'var(--text)', fontSize: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: 4 }}>{eintrag.name}</div>}
          </div>
        );
      })}
      {!chosen && !leaving && (
        <div className="deck-peek-bar" style={{ top: (oben + gesamtHoehe + 14) + 'px' }}>
          <div className="deck-peek-title">{title}</div>
          {interactive && (
            <button className="btn btn-info" style={{ padding: '6px 18px', fontSize: 12 }}
              onClick={() => { if (window.playSFX) window.playSFX('ui_click'); onDone(); }}>✓ DONE</button>
          )}
        </div>
      )}
    </>
  );
}

function BirthdayPresentReveal({ state, interactive, onPick }) {
  const { cards, cardbackUrl, chosen, flights, sourceX, sourceY, castMode } = state;
  return (
    <>
      {cards.map((cardName, i) => {
        const card = CARDS_BY_NAME[cardName];
        const imgUrl = card ? cardImageUrl(card.name) : null;
        const isChosen = chosen === cardName;
        const flight = flights ? flights.find(f => f.cardName === cardName) : null;
        // -1 / 0 / +1 horizontal offset around viewport centre.
        const slotIdx = i - 1;
        const cls = ['bday-present-reveal-card'];
        if (interactive && !chosen) cls.push('clickable');
        // Timeless King Zi: the chosen Spell grows + slow-fades as it's
        // cast (`tk-casting`) instead of Birthday Present's hand-bound
        // highlight (`chosen`). `castMode` is Zi-only — Birthday Present
        // never sets it, so its path is unchanged.
        if (isChosen) cls.push(castMode ? 'tk-casting' : 'chosen');
        if (flight) cls.push('flying-out');
        // v1260: Klang beim Waehlen (Al: „Beim Anklicken einer Karte aus
        // Zis Galerie fehlt noch ein Sound") — gilt fuer Birthday Present mit.
        const handleClick = (interactive && !chosen && onPick)
          ? () => { if (window.playSFX) window.playSFX('ui_click'); onPick(cardName); } : undefined;
        // ★ v1259 (Als Befund 20.9.): „Hovert man ueber einer der Karten,
        // die Zi zur Auswahl gibt, erscheint kein Tooltip." Die drei
        // Aufdeck-Karten (Birthday Present, Zi) sind reine <img>-Kaesten
        // ohne Anbindung an den geteilten Brett-Tooltip — anders als
        // CardMini/BoardCard. Hier dieselbe Anbindung: Zeiger drueber →
        // Tooltip, Zeiger weg → zu. Am Finger uebernimmt der Tap das
        // Anklicken; ein langer Druck ist hier nicht noetig, weil die
        // Karten gross in der Mitte stehen.
        const tooltipRein = () => { if (card && window._boardTooltipSetter && !window.activeDragData) window._boardTooltipSetter(card); };
        const tooltipRaus = () => { if (window._boardTooltipSetter) window._boardTooltipSetter(null); };
        return (
          <div key={`bday-${i}-${cardName}`} className={cls.join(' ')}
            onMouseEnter={tooltipRein} onMouseLeave={tooltipRaus}
            style={{
              '--idx': slotIdx,
              '--delay': (i * 250) + 'ms',
              // Slide-in origin = the activator's deck pile. Captured
              // at event time in the socket handler and threaded
              // through so each card slides FROM that point INTO the
              // centre.
              '--sx': (sourceX != null ? sourceX : 0) + 'px',
              '--sy': (sourceY != null ? sourceY : 0) + 'px',
              ...(flight ? {
                '--ex': flight.toX + 'px',
                '--ey': flight.toY + 'px',
                // Per-flight stagger so user-bound cards land sequentially.
                '--flight-delay': (flight.delay || 0) + 'ms',
              } : {}),
            }}
            onClick={handleClick}>
            <div className="bday-present-reveal-inner">
              <div className="bday-present-reveal-back">
                <img src={cardbackUrl || '/cardback.png'} draggable={false} />
              </div>
              <div className="bday-present-reveal-front">
                {imgUrl ? <img src={imgUrl} draggable={false} />
                  : <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg3)', fontSize: 11, color: 'var(--text)', textAlign: 'center', padding: 4 }}>{cardName}</div>}
              </div>
            </div>
          </div>
        );
      })}
    </>
  );
}

// Brackle catapult — single five-phase flying card. THREE chained CSS
// animations (load → fire → discard-fly) with `forwards` fills cover
// the visible flow. The implicit gaps between animations are the
// HOLD (creature parked on Brackle) and IMPACT (creature parked at
// target while the explosion plays) phases — no extra animations
// needed since `forwards` fill keeps the card visibly pinned in
// place across each gap.
function BrackleCatapultCard({ sx, sy, mx, my, ex, ey, dx, dy, cardName, loadMs, holdMs, fireMs, impactMs, discardMs }) {
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  // Each chained animation's `animation-delay` is the cumulative
  // start-time across previous phases. CSS doesn't compute these
  // for us, so we precompute and pass each as a variable.
  const fireDelay    = (loadMs || 0) + (holdMs || 0);
  const discardDelay = fireDelay + (fireMs || 0) + (impactMs || 0);
  return (
    <div className="brackle-catapult-card" style={{
      '--sx': sx + 'px', '--sy': sy + 'px',
      '--mx': mx + 'px', '--my': my + 'px',
      '--ex': ex + 'px', '--ey': ey + 'px',
      '--dx': dx + 'px', '--dy': dy + 'px',
      '--load-ms':     loadMs    + 'ms',
      '--fire-ms':     fireMs    + 'ms',
      '--discard-ms':  discardMs + 'ms',
      '--fire-delay':    fireDelay    + 'ms',
      '--discard-delay': discardDelay + 'ms',
    }}>
      {imgUrl ? <img src={imgUrl} draggable={false} alt="" />
        : <div style={{ width: '100%', height: '100%', background: 'var(--bg3)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 10, color: 'var(--text)', padding: 4, textAlign: 'center' }}>{cardName}</div>}
    </div>
  );
}

function OppDrawAnimCard({ id, startX, startY, endX, endY, cardName, cardbackUrl, fanRot }) {
  // v1260: Start mittig auf dem Stapel — siehe DrawAnimCard.
  const cx = startX + 32, cy = startY + 45;
  const left = `calc(${cx}px - var(--hand-card-w) / 2)`;
  const top = `calc(${cy}px - var(--hand-card-h) / 2)`;
  const dx = `calc(${endX - cx}px + var(--hand-card-w) / 2)`;
  const dy = `calc(${endY - cy}px + var(--hand-card-h) / 2)`;
  return (
    <div className="draw-anim-card"
      style={{
        left, top, '--dx': dx, '--dy': dy,
        // ★ v1233: Landewinkel des Faechers. Der Drehpunkt liegt hier
        // in der MITTE, weil die Karten dieser Reihen keine Platz-
        // Huelle haben und selbst um ihre Mitte drehen (style.css).
        '--fan-rot': fanRot || '0deg', '--fan-origin': '50% 50%',
      }}>
      {cardName ? (
        <BoardCard cardName={cardName} noTooltip />
      ) : (
        <div className="board-card face-down" style={{ width: '100%', height: '100%' }}>
          <img src={cardbackUrl || "/cardback.png"} style={{ width: '100%', height: '100%', objectFit: 'cover' }} draggable={false} />
        </div>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════
//  DIAGNOSE-SCHALTER IM BROWSER  (v1132)
// ═══════════════════════════════════════════
// ★ Al hat sie 15.9. als SERVER-Variablen gesetzt — `set
// PP_FLIGHT_WATCH=true && node server.js`. Das konnte nicht wirken:
// beide leben im BROWSER. Mein Fehler, ich hatte sie neben die
// Server-Schalter geschrieben, ohne den Unterschied zu nennen.
//
// Deshalb jetzt drei Wege, und der erste braucht keine Konsole:
//
//   ① http://localhost:3000/?watch=zone      (oder ?watch=flug, ?watch=alle)
//   ② window.PP_ZONE_WATCH = true            in der Browser-Konsole
//   ③ window.PP_FLIGHT_WATCH = true          ebenso
//
// Beim Laden meldet sich jeder aktive Schalter — „kein Output" ist
// damit eindeutig und nie mehr ein Bedienfehler.
(function ppDiagnoseSchalter() {
  try {
    const p = new URLSearchParams(window.location.search).get('watch') || '';
    const w = p.toLowerCase();
    if (w === 'zone' || w === 'alle' || w === 'all') window.PP_ZONE_WATCH = true;
    if (w === 'flug' || w === 'flight' || w === 'alle' || w === 'all') window.PP_FLIGHT_WATCH = true;
    const an = [];
    if (window.PP_ZONE_WATCH) an.push('PP_ZONE_WATCH (Zonen-Renderstelle)');
    if (window.PP_FLIGHT_WATCH) an.push('PP_FLIGHT_WATCH (Flug-Neustarts)');
    if (an.length) console.log('%c[Diagnose] AKTIV: ' + an.join(', '), 'color:#e08a5e;font-weight:bold');
    else console.log('[Diagnose] keine Browser-Sonde aktiv — ?watch=alle an die Adresse haengen.');
  } catch (e) { /* egal */ }
})();

/**
 * ★ v1133: Jetzt-Zeitpunkt fuer Fluege.
 *
 * Al 15.9.: der Skull tauchte im Flug-Protokoll GAR NICHT auf, „Hell
 * Fox" schon. Der Grund: `launchFlight` ist nur EINER von acht Wegen,
 * auf denen ein Flug entsteht — die uebrigen reihen direkt in
 * `discardAnims` ein und trugen keine Startzeit. Ohne die greift der
 * Schutz gegen einen Animations-Neustart (v1131) dort nicht.
 */
function ppJetzt() {
  return (typeof performance !== 'undefined' ? performance.now() : Date.now());
}

function DiscardAnimCard({ cardName, startX, startY, endX, endY, dest, delay, t0, ausHand, startW, startH, endW }) {
  // ★ v1331: Brettquellen bringen ihr Bildschirmmass mit (`startW/H`, aus
  // `kartenMassAmBildschirm`) und das des Zielstapels (`endW`). Die Karte
  // startet dann exakt so gross wie auf dem Brett und endet in
  // Stapelgroesse — nie kleiner als das Kleinere von beiden (Als Regel).
  const mitMass = startW > 0 && startH > 0 && endW > 0;
  // ★ v1259 (Als Befund 20.9.: „beim Zurueckmischen von Handkarten ins
  // Potion- UND Main-Deck liegen die Karten zu weit unten/rechts — als
  // wuerde ueber der oberen linken Ecke statt der Mitte zentriert").
  //
  // Alle Zielpunkte im Projekt (getPileCenter, deckTarget, Stack) sind
  // „Stapelmitte minus 32/45" — die OBERE LINKE ECKE einer 64×90-Karte.
  // Die fliegende Karte hat aber Hand- bzw. Stapelmass (mit Massstab),
  // und `scale()` am Ende dreht um ihre eigene Mitte: die landet damit
  // um (Breite/2 − 32, Hoehe/2 − 45) neben der Stapelmitte — am Desktop
  // rund 20/35 px nach rechts unten, aus der Hand am deutlichsten, weil
  // dort die groesste Karte fliegt. Deshalb wird der Weg jetzt von
  // MITTE zu MITTE gerechnet, und weil die eigene Groesse nur das CSS
  // kennt (`--flug-w/--flug-h`, gesetzt in `.discard-anim-card` und
  // `.discard-anim-hand`), zieht `calc()` die halbe Kartengroesse ab.
  const dx = `calc(${endX + 32 - startX}px - var(--flug-w, 64px) / 2)`;
  const dy = `calc(${endY + 45 - startY}px - var(--flug-h, 90px) / 2)`;
  // ★★ v1131 — DER FLUG DARF NICHT VON VORN BEGINNEN (Als Befund 15.9.:
  // „der Skull erscheint noch mal in seiner Support Zone").
  //
  // Die Keyframes starten am BRETTPLATZ der Karte. Wird die Animation
  // neu gestartet — weil React den Knoten neu einhaengt, etwa wenn
  // „Hell Fox" mitten im Flug seine Galerie oeffnet und den Teilbaum
  // austauscht —, springt die Karte sichtbar an ihren Ausgangspunkt
  // zurueck. Genau das sieht man: die Kreatur taucht kurz wieder in
  // ihrer Zone auf.
  //
  // Mit einem NEGATIVEN `animation-delay` in Hoehe der bereits
  // verstrichenen Zeit setzt eine neu gestartete Animation dort fort,
  // wo sie war. Beim ERSTEN Bild ist die verstrichene Zeit ~0, es
  // aendert sich also nichts; nur ein Neustart wird unsichtbar.
  const verstrichen = (typeof t0 === 'number')
    ? Math.max(0, (typeof performance !== 'undefined' ? performance.now() : Date.now()) - t0)
    : 0;
  const versatz = (delay || 0) - verstrichen;
  if (window.PP_FLIGHT_WATCH) {
    // ★ v1133: Im Lauf vom 15.9. kam eine Zeile fuer „Hell Fox", aber
    // KEINE fuer den Skull — der ist also nie geflogen. Das ist selbst
    // ein Befund; deshalb meldet die Sonde weiterhin jeden Start.
    // ★ v1132: JEDEN Durchlauf melden, nicht nur die Neustarts. Sonst
    // ist „keine Meldung" wieder mehrdeutig — Sonde aus, oder Flug ohne
    // Neustart? Jetzt sagt die Zeile es selbst.
    console.log('[FLUG]', cardName, verstrichen > 30 ? 'NEUSTART' : 'Start',
      '— verstrichen', Math.round(verstrichen), 'ms, Versatz', Math.round(versatz), 'ms');
  }
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  const isDeleted = dest === 'deleted';
  const isDeckReturn = dest === 'deck';
  // `delay` (ms) staggers a simultaneous multi-card batch. The flight
  // keyframes have no backwards fill, so during the delay the card
  // simply sits at its board slot (start position) and then flies —
  // exactly the "wait your turn, then go" cascade we want.
  return (
    <div className={'discard-anim-card' + (isDeleted ? ' discard-anim-deleted' : '') + (isDeckReturn ? ' discard-anim-deck-return' : '')
        /* ★ v1235: Kommt die Karte aus der HAND, startet sie im
           Handkartenmass — Hand und Stapel sind seit heute gleich gross,
           die Karte wird auf dem ganzen Weg also nicht mehr skaliert.
           Brettquellen behalten ihr Zonenmass. */
        + (ausHand ? ' discard-anim-hand' : '')}
      style={{ left: startX, top: startY, '--dx': dx, '--dy': dy,
        ...(mitMass ? {
          width: startW + 'px', height: startH + 'px',
          '--flug-w': startW + 'px', '--flug-h': startH + 'px',
          '--dfScale': (endW / startW).toFixed(4),
        } : {}),
        animationDelay: versatz ? versatz + 'ms' : undefined }}>
      <div className="board-card" style={{ width: '100%', height: '100%' }}>
        {imgUrl ? <img src={imgUrl} style={{ width: '100%', height: '100%', objectFit: 'cover' }} draggable={false} />
        : <div className="board-card-text">{cardName || '?'}</div>}
      </div>
      {isDeleted && <div className="delete-energy-overlay" />}
    </div>
  );
}

// ══ MASSE FLIEGENDER KARTEN (v1254) ══════════════════════════
//
// Als Befund 19.9.: „die Karten waehrend ihrer Flug-Animation sind
// immer noch klein — es sind nicht die Handkarten selbst, die sich
// bewegen, sondern dedizierte Animationen mit Ghost-Karten.“ Genau so
// ist es: ein halbes Dutzend Fluege baut seine Geisterkarte per
// `document.createElement` und schreibt `width:64px; height:88px`
// hinein — fest verdrahtet, ohne Brettmassstab und erst recht ohne die
// eigenen Masse von Hand und Stapel.
//
// `flugMass(ort)` liefert das Mass des Ortes, an dem die Karte
// tatsaechlich liegt. Gelesen wird es aus denselben CSS-Variablen, die
// die ruhenden Karten benutzen — eine Quelle, kein zweiter Satz
// Zahlen.
function flugMass(ort) {
  const w = getComputedStyle(document.documentElement);
  const zahl = (name, rueck) => {
    const v = parseFloat(w.getPropertyValue(name));
    return Number.isFinite(v) && v > 0 ? v : rueck;
  };
  // ★★★ v1256 (Als Befund 19.9.: „Hand → Discard und Hand → Deleted
  // haben immer noch zu kleine Karten"). DAS war der Grund, und er
  // gilt fuer JEDE Stelle, die ein Kartenmass aus dem Stylesheet holt:
  //
  //   getComputedStyle(root).getPropertyValue('--hand-card-w')
  //     → "calc(64px * 0.875 * 1.92)"      — ein TEXT, kein Wert
  //     → parseFloat(…) === NaN            — also der Rueckfall 64
  //
  // Eigene Eigenschaften werden nicht ausgerechnet; der berechnete Wert
  // ist der Ausdruck selbst. Jeder Flug, der sein Mass so gelesen hat,
  // ist deshalb in Brettgroesse geflogen — unabhaengig davon, wie oft
  // ich die Variablen korrigiert habe. Gerechnet wird jetzt aus den
  // reinen ZAHLEN (`--board-scale`, `--hand-card-scale`,
  // `--pile-card-scale`), die parseFloat sehr wohl lesen kann, mit
  // denselben Grundmassen wie style.css: 64 × 90.
  const brett = zahl('--board-scale', 1);
  if (ort === 'hand') {
    const m = brett * zahl('--hand-card-scale', 1);
    return { b: 64 * m, h: 90 * m };
  }
  if (ort === 'brett') return { b: 64 * brett, h: 90 * brett };
  // Deck, Potion, Ablage, Geloescht, Area — alle im Stapelmass.
  const m = brett * zahl('--pile-card-scale', 1);
  return { b: 64 * m, h: 90 * m };
}
if (typeof window !== 'undefined') window.flugMass = flugMass;

// ★ v1331 (Als Regel 24.9.): „Karten sollten beim Bewegen von Board zu
// Pile nie kleiner werden als sie auf dem Board waren ODER kleiner als
// der Ziel-Pile (was kleiner ist)."
//
// `flugMass` kennt nur die Stylesheet-Masse. Was der Spieler SIEHT, ist
// groesser: Kamera-Zoom und die Perspektive der geneigten Brettebene
// vergroessern die Brettkarten. Eine Geisterkarte im Stylesheet-Mass
// war deshalb beim Abheben sichtbar kleiner als ihr Vorbild — sie
// „schrumpfte", bevor die Bewegung begann. Hier wird das Mass am
// Bildschirm abgenommen: die Karte IN der Zone (`.board-card`), sonst
// die Zone selbst. Die Hoehe folgt aus der Breite (die Neigung staucht
// nur die Hoehe des Umrisses, die Flugkarte neigt sich selbst).
function kartenMassAmBildschirm(el, ort) {
  const basis = flugMass(ort);
  if (!el || typeof el.getBoundingClientRect !== 'function') return basis;
  const karte = (typeof el.querySelector === 'function' && el.querySelector('.board-card')) || el;
  const r = karte.getBoundingClientRect();
  if (!(r.width > 4)) return basis;
  return { b: r.width, h: r.width * (basis.h / basis.b) };
}
if (typeof window !== 'undefined') window.kartenMassAmBildschirm = kartenMassAmBildschirm;

// ★★ v1355 (Als Befund zu „Lone Survivor": „die Creature ist beim Flug
// Discard → Zone etwas kleiner, als sie am Ende in der Zone angezeigt
// wird"). Ein Flug INS Brett endete im Stylesheet-Mass (`flugMass('brett')`)
// — ohne Kamera-Zoom und Perspektive, also kleiner als die Karte, die dann
// dort liegt. Das Ziel wird jetzt am Bildschirm gemessen, genau wie eine
// Brett-QUELLE seit v1331. Liegt in der Zielzone noch keine Karte (der
// Normalfall: sie kommt ja erst an), misst die Zone selbst — die ist um
// den Rahmen breiter als die Karte in ihr (`--zone-w` 68 zu 64 je
// `--board-scale`), deshalb der Abzug.
const ZONE_ZU_KARTE = 64 / 68;
function kartenMassInZone(el) {
  if (!el || typeof el.getBoundingClientRect !== 'function') return flugMass('brett');
  const karte = typeof el.querySelector === 'function' && el.querySelector('.board-card');
  if (karte && karte.getBoundingClientRect().width > 4) return kartenMassAmBildschirm(el, 'brett');
  const r = el.getBoundingClientRect();
  if (!(r.width > 4)) return flugMass('brett');
  const b = r.width * ZONE_ZU_KARTE;
  return { b, h: b * (90 / 64) };
}
if (typeof window !== 'undefined') window.kartenMassInZone = kartenMassInZone;

// ═══════════════════════════════════════════
//  NEIGUNG FLIEGENDER KARTEN
// ═══════════════════════════════════════════
// Eine fliegende Karte haengt als `position: fixed` an <body> und liegt
// damit AUSSERHALB der geneigten Brettebene (`.board-plane`,
// `rotateX(var(--board-tilt))`). Ohne Zutun klappt eine Kreatur, die
// gerade noch angewinkelt in ihrer Support Zone lag, im ersten Bild
// ihres Fluges flach um — Als Befund 19.8. zu Trial of Dominance.
// Dieselbe Lesart hat der Diff-Flug (`cardDiscardFly`) schon: angewinkelt
// starten, auf dem Weg aufrichten, weil die Ablagestapel flache
// Bedienoberflaeche sind.
//
// Zonen, die AUF der geneigten Ebene liegen. Fliegt eine Karte von hier
// los, startet ihr Flug angewinkelt; landet sie hier, bleibt sie es.
const FLIGHT_PLANE_ZONES = new Set(['support', 'ability', 'surprise', 'permanent', 'area', 'hero']);

// Perspektive der Flugkarte. Bewusst derselbe Wert wie `--board-persp`
// der Brettebene, damit die Verkuerzung gleich stark ausfaellt.
const FLIGHT_TILT_PERSPECTIVE_PX = 900;

// Die Neigung wird NICHT geraten, sondern aus der tatsaechlich
// gerenderten Transformationsmatrix der Ebene gelesen. Das deckt ohne
// Zusatzwissen mit ab: den Mobil- und Engpass-Rueckfall (Ebene flach →
// 0deg, also gar keine Neigung), das Flach-Messfenster des
// Scroll-Detektors, den Puzzle-Creator mit eigenem `--pz-tilt` und jede
// kuenftige Aenderung von `--board-tilt`. Faellt irgendetwas davon aus,
// ist das Ergebnis 0 — also genau das Verhalten von vorher.
//
// `doc` ist Parameter, damit ein Repro die Funktion gegen eine
// DOM-Attrappe fahren kann.
function readBoardTiltDeg(doc) {
  const d = doc || (typeof document !== 'undefined' ? document : null);
  if (!d || typeof d.querySelector !== 'function') return 0;
  // ★ `.pz-plane` GIBT ES NICHT — die Puzzle-Ebene heisst
  // `.pz-board-plane` (`.pz-plane-clip` ist nur ihr Wrapper). Der
  // Rueckfall aus v497 traf deshalb NIE, und im Puzzle-Modus lieferte
  // die Messung 0 → gar keine Neigung. Genau das hat Al am 19.8. als
  // „Trial of Dominance ist immer noch flach" gemeldet: er testet im
  // Puzzle-Modus. Nachgemessen: `.pz-plane` kommt in style.css und
  // app-puzzle.jsx null mal vor.
  const plane = d.querySelector('.board-plane') || d.querySelector('.pz-board-plane');
  if (!plane) return 0;
  const view = d.defaultView || (typeof window !== 'undefined' ? window : null);
  if (!view || typeof view.getComputedStyle !== 'function') return 0;
  const t = view.getComputedStyle(plane).transform;
  // `none` oder eine 2D-`matrix(...)` heissen: die Ebene liegt flach.
  if (!t || t.indexOf('matrix3d(') !== 0) return 0;
  const v = t.slice(9, -1).split(',').map(s => parseFloat(s));
  if (v.length !== 16 || v.some(n => !Number.isFinite(n))) return 0;
  // Spalte 2 der Matrix ist das Bild der y-Achse. Bei
  // `rotateX(θ) scale(s)` steht dort (0, s·cos θ, s·sin θ, 0) — der
  // Massstab kuerzt sich im atan2 also heraus.
  const deg = Math.atan2(v[6], v[5]) * 180 / Math.PI;
  if (!Number.isFinite(deg)) return 0;
  // Riegel gegen Unsinn aus fremden 3D-Transformationen.
  return Math.max(0, Math.min(80, deg));
}

// Entscheidet, mit welcher Neigung ein Flug startet und endet.
// Eigene Funktion, damit ein Repro die Entscheidungstabelle AUSFUEHREN
// kann statt sie nachzubauen (Testlehre 2 aus v496).
//
// Nur QUELLEN auf der Brettebene werden angewinkelt — eine Handkarte
// liegt flach und soll das bleiben, ihr Flug ist damit bildgleich zu
// vorher. Landet die Karte wieder auf der Ebene (Support-/Area-Zone),
// behaelt sie die Neigung; geht sie auf einen Stapel, ins Deck oder auf
// die Hand, richtet sie sich auf dem Weg auf, weil das flache
// Bedienoberflaeche ist.
function flightTiltFor(from, to, planeTiltDeg) {
  const tilt = Number(planeTiltDeg);
  const grad = Number.isFinite(tilt) ? tilt : 0;
  const vonEbene = FLIGHT_PLANE_ZONES.has(from);
  const zuEbene = FLIGHT_PLANE_ZONES.has(to);
  return {
    startDeg: vonEbene ? grad : 0,
    endDeg: (vonEbene && zuEbene) ? grad : 0,
  };
}

// Legt den Karteninhalt in eine eigene Neigungs-Ebene und animiert dort
// NUR die Neigung. Bewusst getrennt von der Flugbahn: `pileTransfer` &
// Co. bleiben unangetastet, die Bahn ist also bildgleich zu vorher — die
// Karte ist auf ihr nur nicht mehr flach.
//
// `perspective` gehoert dabei auf den ELTERN des gedrehten Elements, nie
// auf das Element selbst — die Eigenschaft wirkt ausschliesslich auf
// direkte Kinder. Genau daran ist die Brettebene selbst schon einmal
// gescheitert (v11-Regression: rotateX ohne Perspektive = flache
// affine Stauchung).
//
// Rueckgabe: das Element, in das der Karteninhalt gehoert — ohne Neigung
// die Flugkarte selbst, dann entsteht auch kein zusaetzlicher Knoten.
function makeFlightTiltLayer(card, opts, doc) {
  const d = doc || (typeof document !== 'undefined' ? document : null);
  const o = opts || {};
  const startDeg = Number.isFinite(Number(o.startDeg)) ? Number(o.startDeg) : 0;
  const endDeg = Number.isFinite(Number(o.endDeg)) ? Number(o.endDeg) : 0;
  if (!d || typeof d.createElement !== 'function') return card;
  if (Math.abs(startDeg) < 0.5 && Math.abs(endDeg) < 0.5) return card;
  const durationMs = Number(o.durationMs) > 0 ? Number(o.durationMs) : 700;
  const delayMs = Number(o.delayMs) > 0 ? Number(o.delayMs) : 0;
  const easing = o.easing || 'ease-in-out';
  card.style.perspective = FLIGHT_TILT_PERSPECTIVE_PX + 'px';
  // Die Rundung wandert mit nach innen: `overflow: hidden` auf der
  // Flugkarte wuerde die nahe Kante der geneigten Ebene abschneiden.
  card.style.overflow = 'visible';
  // Das Leuchten gehoert zum Kartenkoerper, muss also mitkippen —
  // bliebe es auf der Flugkarte, umrahmte ein flaches Rechteck eine
  // geneigte Karte.
  const glow = card.style.boxShadow;
  card.style.boxShadow = 'none';
  const layer = d.createElement('div');
  layer.className = 'card-flight-tilt';
  layer.style.cssText = [
    'width:100%', 'height:100%',
    'border-radius:4px', 'overflow:hidden',
    glow ? `box-shadow:${glow}` : '',
    `--ftFrom:${startDeg}deg`, `--ftTo:${endDeg}deg`,
    // `both`: waehrend einer Wartezeit (Brett-Takt) haelt die
    // Rueckwaerts-Fuellung die Startneigung — die Kreatur steht also
    // angewinkelt auf ihrem Platz, bis sie dran ist.
    `animation:cardFlightTilt ${durationMs}ms ${easing} ${delayMs}ms both`,
  ].join(';');
  card.appendChild(layer);
  return layer;
}

// ═══════════════════════════════════════════
//  MODULAR GAME ANIMATION SYSTEM
//  Add new animation types by adding to ANIM_REGISTRY.
//  Usage: playAnimation('explosion', '#target-selector', { duration: 800 })
// ═══════════════════════════════════════════

// Draggable floating panel — used for targeting dialogs, first-choice, etc.
// ═══ MOBILE-KAMERA (v1257, Als Vorgabe 19.9.) ═══════════════════════
// „Wenn der Gegner eine Aktion taetigt, soll die Kamera so scrollen,
// dass man gut sieht, was er tut — Ziel-Zonen moeglichst zentral,
// schnell, aber nicht instantan."
//
// Bauform: EIN Einstiegspunkt `window.ppBattleCamFocus(el)`, den die
// ohnehin vorhandenen Ziel-Aufloeser aufrufen (Schadens-/Heilzahlen,
// Kartenfluege, Zonen-Einschlagfunken in app-shared). Er tut nur auf
// Telefonen etwas, nur waehrend der Gegner handelt (`_ppOppActing`,
// gesetzt vom GameBoard; fuer Zuschauer immer an) und nie gegen einen
// aktiven Finger (`_touchActive` gewinnt IMMER — die Kamera reisst dem
// Spieler nie den Wisch aus der Hand).
//
// Mehrere Ziele derselben Aktion treffen als einzelne Aufrufe ein —
// ein 120-ms-Sammelfenster vereinigt ihre Rechtecke, gescrollt wird
// EINMAL auf die Mitte der Vereinigung. Die Fahrt selbst ist ein
// eigenes rAF (~300 ms, ease-out) statt scroll-behavior:smooth, weil
// die Messschleife (check) den Scrollstand pro Durchlauf sichert und
// zuruecksetzt — ein natives Smooth-Scroll wuerde dabei abgebrochen,
// das rAF schreibt im naechsten Frame einfach weiter.
const _ppCam = { pend: [], timer: 0, raf: 0 };
function _ppCamVarPx(name) {
  const v = getComputedStyle(document.documentElement).getPropertyValue(name);
  const n = parseFloat(v);
  return isNaN(n) ? 0 : n;
}
function _ppCamFahre(sc, zielX, zielY) {
  if (_ppCam.raf) cancelAnimationFrame(_ppCam.raf);
  const vonX = sc.scrollLeft, vonY = sc.scrollTop;
  if (Math.abs(zielX - vonX) < 8 && Math.abs(zielY - vonY) < 8) return;
  const start = performance.now();
  const DAUER = 300;
  const ease = (p) => 1 - Math.pow(1 - p, 3);
  const schritt = (jetzt) => {
    // Finger auf dem Schirm → sofort loslassen, der Spieler scrollt selbst.
    if (window._touchActive) { _ppCam.raf = 0; return; }
    const p = Math.min(1, (jetzt - start) / DAUER);
    const e = ease(p);
    sc.scrollLeft = vonX + (zielX - vonX) * e;
    sc.scrollTop = vonY + (zielY - vonY) * e;
    _ppCam.raf = p < 1 ? requestAnimationFrame(schritt) : 0;
  };
  _ppCam.raf = requestAnimationFrame(schritt);
}
function ppBattleCamFocus(el) {
  try {
    if (!(window.ppIsPhone && window.ppIsPhone())) return;
    if (!window._ppOppActing) return;
    if (window._touchActive) return;
    if (!el || !el.getBoundingClientRect) return;
    const sc = document.querySelector('.board-center');
    if (!sc || !sc.contains(el)) return;
    const r = el.getBoundingClientRect();
    if (!r.width && !r.height) return;
    _ppCam.pend.push(r);
    if (_ppCam.timer) return;
    _ppCam.timer = setTimeout(() => {
      _ppCam.timer = 0;
      const rects = _ppCam.pend.splice(0);
      if (!rects.length) return;
      let l = Infinity, t = Infinity, rr = -Infinity, b = -Infinity;
      for (const x of rects) { l = Math.min(l, x.left); t = Math.min(t, x.top); rr = Math.max(rr, x.right); b = Math.max(b, x.bottom); }
      const scr = sc.getBoundingClientRect();
      // Zielmitte in INHALTS-Koordinaten (Scrollstand herausrechnen).
      const cx = (l + rr) / 2 - scr.left + sc.scrollLeft;
      const cy = (t + b) / 2 - scr.top + sc.scrollTop;
      // Sichtbares Band = Ausschnitt minus Overlay-Leisten: die Zonen
      // sollen zwischen den halbtransparenten Leisten zentriert stehen,
      // nicht in der geometrischen Mitte hinter einer davon.
      const oben = _ppCamVarPx('--mob-opphand-h');
      const unten = _ppCamVarPx('--mob-mehand-h');
      const bandMitteY = oben + Math.max(40, sc.clientHeight - oben - unten) / 2;
      const zielX = Math.max(0, Math.min(sc.scrollWidth - sc.clientWidth, cx - sc.clientWidth / 2));
      const zielY = Math.max(0, Math.min(sc.scrollHeight - sc.clientHeight, cy - bandMitteY));
      _ppCamFahre(sc, zielX, zielY);
    }, 120);
  } catch {}
}
window.ppBattleCamFocus = ppBattleCamFocus;

// ★ v1258 — HAT DIESES PANEL SCROLLBAREN INHALT? (Als Befund 19.9.:
// „Panels ohne Scrolling, z.B. ‚Mulligan? Yes/No', sollten definitiv
// noch dragbar sein, damit man sie aus dem Weg schieben kann.")
//
// v1257 hatte Touch pauschal abgelehnt, weil der Fenster-Drag sonst
// gegen das Scrollen der Galerie gewann. Der Konflikt besteht aber nur
// dort, wo es ueberhaupt etwas zu scrollen GIBT. Die Pruefung laeuft
// deshalb ueber den echten Ueberlauf und nicht ueber eine Liste von
// Klassennamen: ein Kasten zaehlt nur, wenn er mehr Inhalt hat als
// Platz UND sein `overflow` das Scrollen auch zulaesst. `.modal` traegt
// zwar immer `overflow-y: auto`, laeuft bei zwei Knoepfen aber nicht
// ueber — der Mulligan-Kasten ist damit beweglich, die Kartengalerie
// nicht. Die 2px Spielraum fangen Rundungen auf (Zoom, Geraete-DPR).
function _ppPanelHatScrollbaresKind(wurzel) {
  if (!wurzel) return false;
  const pruefe = (el) => {
    if (!el) return false;
    if (el.scrollHeight <= el.clientHeight + 2 && el.scrollWidth <= el.clientWidth + 2) return false;
    const st = getComputedStyle(el);
    return /(auto|scroll)/.test(st.overflowY) || /(auto|scroll)/.test(st.overflowX);
  };
  if (pruefe(wurzel)) return true;
  for (const el of wurzel.querySelectorAll('*')) if (pruefe(el)) return true;
  return false;
}

function DraggablePanel({ children, className, style }) {
  const [pos, setPos] = useState({ x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);
  const offsetRef = useRef({ x: 0, y: 0 });
  const panelRef = useRef(null);
  const cleanupRef = useRef(null);
  const onDown = (e) => {
    // ★ v1258: Auf Touch ist nur noch das Panel unbeweglich, das
    // scrollbaren Inhalt hat (Kartengalerie, lange Listen) — dort gewann
    // der Fenster-Drag sonst gegen das Scrollen, und das Scrollen ist
    // auf dem Handy das Einzige, was dort gebraucht wird. Kleine
    // Entscheidungs-Panels („Mulligan? Yes/No") bleiben verschiebbar,
    // damit man sie vom Spielfeld wegziehen kann. Frueh raus, KEIN
    // preventDefault: der Browser behaelt den Wisch fuers native
    // Scrollen. Maus-Drag am Desktop war nie betroffen.
    if (e.touches && _ppPanelHatScrollbaresKind(panelRef.current)) return;
    // Don't start a drag when the pointer-down lands on an interactive
    // form control. `preventDefault()` below would otherwise swallow the
    // native mousedown that opens a <select> dropdown, focuses an <input>,
    // or toggles a checkbox.
    const tag = e.target.tagName;
    if (tag === 'BUTTON' || tag === 'SELECT' || tag === 'OPTION'
        || tag === 'INPUT' || tag === 'TEXTAREA') return;
    const r = panelRef.current?.getBoundingClientRect();
    if (!r) return;
    const pt = window.getPointerXY(e);
    offsetRef.current = { x: pt.x - r.left, y: pt.y - r.top };
    setDragging(true);
    if (e.cancelable) e.preventDefault();
  };
  useEffect(() => {
    if (!dragging) return;
    const cleanup = window.addDragListeners(
      (mx, my) => {
        setPos({ x: mx - offsetRef.current.x, y: my - offsetRef.current.y });
      },
      () => setDragging(false)
    );
    cleanupRef.current = cleanup;
    return cleanup;
  }, [dragging]);
  const hasCustomPos = pos.x !== 0 || pos.y !== 0;
  const posStyle = hasCustomPos
    ? { position: 'fixed', left: pos.x, top: pos.y, transform: 'none' }
    : {};
  return (
    <div ref={panelRef} className={className} style={{ ...style, ...posStyle, cursor: dragging ? 'grabbing' : 'grab' }}
      onMouseDown={onDown} onTouchStart={onDown} onClick={e => e.stopPropagation()}>
      {children}
    </div>
  );
}

// Frozen overlay with animated snowflake particles
function FrozenOverlay() {
  const particles = useMemo(() => Array.from({ length: ppFxN(14) }, () => ({
    x: 5 + Math.random() * 90,
    y: 5 + Math.random() * 90,
    size: 5 + Math.random() * 7,
    delay: Math.random() * 3,
    dur: 1.5 + Math.random() * 2,
    char: ['❄','❅','❆','✦','✧','·','*'][Math.floor(Math.random() * 7)],
  })), []);
  return (
    <div className="status-frozen-overlay">
      {particles.map((p, i) => (
        <span key={i} className="frozen-particle" style={{
          left: p.x + '%', top: p.y + '%', fontSize: p.size,
          animationDelay: p.delay + 's', animationDuration: p.dur + 's',
        }}>{p.char}</span>
      ))}
    </div>
  );
}

// Immune/Shielded status icon with instant custom tooltip
function ImmuneIcon({ heroName, statusType }) {
  const tooltipKey = statusType === 'shielded' ? 'shielded' : 'immune';
  return (
    <div className={'status-immune-icon' + (statusType === 'shielded' ? ' status-shielded-icon' : '')}
      onMouseEnter={() => { window._immuneTooltip = heroName; window._immuneTooltipType = tooltipKey; window.dispatchEvent(new Event('immuneHover')); }}
      onMouseLeave={() => { window._immuneTooltip = null; window._immuneTooltipType = null; window.dispatchEvent(new Event('immuneHover')); }}>
      🛡️
    </div>
  );
}

// Card reveal — opponent's played card appears centered and expands/fades
function CardRevealOverlay({ reveals, onRemove }) {
  return (
    <div className="card-reveal-stack">
      {reveals.map((rev, idx) => (
        <CardRevealEntry key={rev.id} cardName={rev.cardName} fizzled={rev.fizzled} onDone={() => onRemove(rev.id)} />
      ))}
    </div>
  );
}

// ★ v1359 — `fizzled`: dieselbe Bildsprache wie ein negiertes Kettenglied
// (Glitch, entsaettigt, 🚫) plus das Wort „FIZZLED" — der Effekt wurde
// ausgeloest, konnte aber nichts mehr tun (`engine.zeigeFizzle`).
const FIZZLE_ANZEIGE_MS = 1400;
function CardRevealEntry({ cardName, onDone, fizzled }) {
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  const foilType = card?.foil || null;
  // v1360 (Als Befund: „die gefizzelte Karte bleibt deutlich zu lange
  // sichtbar"): ein Fizzeln ist eine kurze Meldung — 1,4 s statt 3,5 s,
  // die letzten 300 ms blendet es aus (`.card-reveal-fizzled-weg`).
  const lebensdauer = fizzled ? FIZZLE_ANZEIGE_MS : 3500;
  // v1373 (Als Befund): beim Verschwinden nur den EIGENEN Tooltip abraeumen.
  // Vorher loeschte jede ablaufende Aufdeck-Anzeige den Tooltip — auch den
  // einer Karte, die der Spieler gerade ganz woanders las (im PvP kommen
  // Aufdeckungen samt Reaktionsfenster laufend herein).
  const gehovert = useRef(false);
  useEffect(() => {
    const t = setTimeout(onDone, lebensdauer);
    return () => { clearTimeout(t); if (gehovert.current) setBoardTooltip(null); };
  }, []);
  if (!card) return null;
  return (
    <div className={'card-reveal-entry' + (fizzled ? ' card-reveal-fizzled-weg' : '')}
      style={fizzled ? { '--fizzle-ms': FIZZLE_ANZEIGE_MS + 'ms' } : undefined}
      onMouseEnter={() => { gehovert.current = true; setBoardTooltip(card); }}
      onMouseLeave={() => { gehovert.current = false; setBoardTooltip(null); }}>
      <div className={'card-reveal-card' + (fizzled ? ' card-reveal-fizzled' : '')}>
        {fizzled && <div className="chain-negate-symbol">🚫</div>}
        {fizzled && <div className="card-reveal-fizzle-label orbit-font">FIZZLED</div>}
        {imgUrl ? (
          <img src={imgUrl} style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: 6,
            border: foilType === 'diamond_rare' ? '3px solid rgba(120,200,255,.7)' : foilType === 'secret_rare' ? '3px solid rgba(255,215,0,.6)' : '2px solid var(--bg4)' }} draggable={false} />
        ) : (
          <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
            background: 'var(--bg3)', borderRadius: 6, border: '2px solid var(--bg4)', padding: 16, textAlign: 'center' }}>
            <div style={{ fontSize: 20, fontWeight: 700, color: typeColor(card.cardType), marginBottom: 8 }}>{card.name}</div>
            <div style={{ fontSize: 14, color: 'var(--text2)' }}>{card.cardType}</div>
          </div>
        )}
      </div>
    </div>
  );
}

function ExplosionEffect({ x, y, opacity }) {
  const particles = useMemo(() => Array.from({ length: ppFxN(24) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 25 + Math.random() * 55;
    return {
      dx: Math.cos(angle) * speed,
      dy: Math.sin(angle) * speed,
      size: 3 + Math.random() * 8,
      color: ['#ff4400','#ff8800','#ffcc00','#ff2200','#ffaa00','#fff'][Math.floor(Math.random() * 6)],
      delay: Math.random() * 80,
      dur: 350 + Math.random() * 400,
    };
  }), []);
  // Optional `opacity` prop — passed through from playAnimation options
  // so callers can dim the burst (Laser Volley wants its impacts more
  // ghostly than a regular hit explosion). Defaults to 1 / fully
  // opaque, preserving every existing caller's look.
  const wrapperOpacity = (typeof opacity === 'number' && opacity >= 0 && opacity <= 1) ? opacity : 1;
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100, opacity: wrapperOpacity }}>
      <div className="anim-explosion-flash" />
      {particles.map((p, i) => (
        <div key={i} className="anim-explosion-particle" style={{
          '--dx': p.dx + 'px', '--dy': p.dy + 'px', '--size': p.size + 'px',
          '--color': p.color, animationDelay: p.delay + 'ms', animationDuration: p.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

function FreezeEffect({ x, y, w, h }) {
  // Snowballs from right side + ice crystal burst
  const snowballs = useMemo(() => Array.from({ length: ppFxN(8) }, (_, i) => ({
    startX: 120 + Math.random() * 40,
    startY: -40 + Math.random() * 40,
    delay: i * 60 + Math.random() * 40,
    dur: 250 + Math.random() * 150,
    size: 6 + Math.random() * 6,
  })), []);
  const crystals = useMemo(() => Array.from({ length: ppFxN(16) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 15 + Math.random() * 35;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 3 + Math.random() * 7,
      color: ['#aaddff','#88ccff','#cceeFF','#ffffff','#66bbff'][Math.floor(Math.random() * 5)],
      delay: 400 + Math.random() * 200,
      dur: 400 + Math.random() * 300,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {/* Ice flash */}
      <div className="anim-freeze-flash" />
      {/* Snowballs from right */}
      {snowballs.map((s, i) => (
        <div key={'sb'+i} className="anim-snowball" style={{
          '--startX': s.startX + 'px', '--startY': s.startY + 'px',
          '--size': s.size + 'px',
          animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
      {/* Ice crystal particles */}
      {crystals.map((c, i) => (
        <div key={'cr'+i} className="anim-explosion-particle" style={{
          '--dx': c.dx + 'px', '--dy': c.dy + 'px', '--size': c.size + 'px',
          '--color': c.color, animationDelay: c.delay + 'ms', animationDuration: c.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

function ThawEffect({ x, y }) {
  const drips = useMemo(() => Array.from({ length: ppFxN(12) }, () => ({
    xOff: -20 + Math.random() * 40,
    speed: 30 + Math.random() * 50,
    size: 3 + Math.random() * 5,
    delay: Math.random() * 300,
    dur: 500 + Math.random() * 400,
    color: ['#aaddff','#88ccff','#cceeFF','#ddf4ff'][Math.floor(Math.random() * 4)],
  })), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-thaw-flash" />
      {drips.map((d, i) => (
        <div key={i} className="anim-thaw-drip" style={{
          '--xOff': d.xOff + 'px', '--speed': d.speed + 'px', '--size': d.size + 'px',
          '--color': d.color, animationDelay: d.delay + 'ms', animationDuration: d.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Electric strike — small lightning bolts from all directions converging on target
// ─── Monia Bot: Jetpack-Dash (`trailType: 'fire'`) ──────────────────
// Die Anteile beschreiben denselben Flug wie die Keyframe
// `ramJetCharge` in style.css — wer hier etwas verschiebt, muss dort
// mitziehen. `arriveAt` ist zusaetzlich mit dem `_delay(280)` in
// monia-bot-*.js verzahnt: der umgeleitete Treffer soll direkt nach
// dem Aufprall folgen (0.45 × 600 ms = 270 ms).
const JET = { igniteAt: 0.10, arriveAt: 0.45, leaveAt: 0.60, homeAt: 0.92 };
// Nachlauf, den die Ebene ueber die Kartendauer hinaus braucht, damit
// der letzte Puff des Rueckflugs noch ausglueht.
const JET_TAIL_MS = 280;

/**
 * Monia Bots Jetpack-Schweif.
 *
 * Der generische `.ram-flame-trail` klebt AN der Karte und pulst auf der
 * Stelle — er kann per Bauart keinen Schweif ergeben. Hier liegen die
 * Flammen deshalb als eigene Ebene ENTLANG DER FLUGBAHN: jeder Puff hat
 * seine feste Position und zuendet genau dann, wenn die Karte an ihm
 * vorbeikommt (`verzug`). Dadurch bleibt der Schweif hinter ihr stehen
 * und verglueht, statt mitzufliegen. Hin- und Rueckflug bekommen eigene
 * Puffs, der Rueckflug schwaecher.
 */
function MoniaJetTrail({ r }) {
  const dur = r.dur || 600;
  const dx = r.tgtX - r.srcX;
  const dy = r.tgtY - r.srcY;
  const laenge = Math.hypot(dx, dy) || 1;
  const bahnWinkel = Math.atan2(dy, dx) * 180 / Math.PI;
  // Senkrechte zur Flugbahn — Streuung quer zur Richtung, nicht in x/y.
  const qx = -dy / laenge, qy = dx / laenge;
  const punkt = (t, seit) => ({
    left: r.srcX + dx * t + qx * (seit || 0),
    top: r.srcY + dy * t + qy * (seit || 0),
  });

  const puffs = useMemo(() => {
    const liste = [];
    const hin = Math.max(8, Math.min(20, Math.round(laenge / 26)));
    for (let i = 0; i < hin; i++) {
      const t = hin === 1 ? 1 : i / (hin - 1);
      liste.push({
        key: 'h' + i, t, seit: (Math.random() * 2 - 1) * 7,
        verzug: (JET.igniteAt + t * (JET.arriveAt - JET.igniteAt)) * dur,
        dauer: 300 + Math.random() * 110,
        skala: 0.78 + (1 - t) * 0.45,
        drift: (Math.random() * 2 - 1) * 12,
      });
    }
    const zurueck = Math.max(5, Math.round(hin * 0.6));
    for (let i = 0; i < zurueck; i++) {
      const t = zurueck === 1 ? 0 : i / (zurueck - 1);
      liste.push({
        key: 'z' + i, t, seit: (Math.random() * 2 - 1) * 6,
        verzug: (JET.leaveAt + (1 - t) * (JET.homeAt - JET.leaveAt)) * dur,
        dauer: 210 + Math.random() * 80,
        skala: 0.5 + t * 0.28,
        drift: (Math.random() * 2 - 1) * 10,
        schwach: true,
      });
    }
    return liste;
  }, []);

  const glut = useMemo(() => Array.from({ length: ppFxN(14) }, () => {
    const t = 0.08 + Math.random() * 0.9;
    return {
      t, seit: (Math.random() * 2 - 1) * 22,
      dx: (Math.random() * 2 - 1) * 30,
      dy: 24 + Math.random() * 44,
      groesse: 3 + Math.random() * 5,
      dauer: 300 + Math.random() * 200,
      verzug: (JET.igniteAt + t * (JET.arriveAt - JET.igniteAt)) * dur + Math.random() * 55,
      farbe: ['#fff3c4', '#ffd166', '#ff9a1f', '#ff5b00'][Math.floor(Math.random() * 4)],
    };
  }), []);

  return (
    <div className="ram-jet-layer">
      {/* Speed-Streak: zieht sich waehrend des Flugs auf und verglueht */}
      <div className="ram-jet-streak" style={{
        left: r.srcX, top: r.srcY, width: laenge,
        '--jsAngle': bahnWinkel + 'deg',
        animationDelay: Math.round(JET.igniteAt * dur) + 'ms',
        animationDuration: Math.round((JET.arriveAt - JET.igniteAt) * dur + 220) + 'ms',
      }} />
      <div className="ram-jet-streak ram-jet-streak-back" style={{
        left: r.tgtX, top: r.tgtY, width: laenge,
        '--jsAngle': (bahnWinkel + 180) + 'deg',
        animationDelay: Math.round(JET.leaveAt * dur) + 'ms',
        animationDuration: Math.round((JET.homeAt - JET.leaveAt) * dur + 180) + 'ms',
      }} />
      {puffs.map(p => {
        const pos = punkt(p.t, p.seit);
        return (
          <div key={p.key} className={'ram-jet-puff' + (p.schwach ? ' ram-jet-puff-dim' : '')} style={{
            left: pos.left, top: pos.top,
            '--jpScale': p.skala, '--jpDrift': p.drift + 'px',
            animationDelay: Math.round(p.verzug) + 'ms',
            animationDuration: Math.round(p.dauer) + 'ms',
          }} />
        );
      })}
      {glut.map((g, i) => {
        const pos = punkt(g.t, g.seit);
        return (
          <div key={'g' + i} className="ram-jet-ember" style={{
            left: pos.left, top: pos.top,
            width: g.groesse, height: g.groesse, background: g.farbe,
            '--jeDx': g.dx + 'px', '--jeDy': g.dy + 'px',
            animationDelay: Math.round(g.verzug) + 'ms',
            animationDuration: Math.round(g.dauer) + 'ms',
          }} />
        );
      })}
      {/* Aufprall: Hitzering genau beim Ankommen */}
      <div className="ram-jet-impact" style={{
        left: r.tgtX, top: r.tgtY,
        animationDelay: Math.round(JET.arriveAt * dur) + 'ms',
      }} />
    </div>
  );
}

function ElectricStrikeEffect({ x, y }) {
  const bolts = useMemo(() => Array.from({ length: ppFxN(16) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const dist = 55 + Math.random() * 45;
    return {
      startX: Math.cos(angle) * dist,
      startY: Math.sin(angle) * dist,
      size: 8 + Math.random() * 10,
      delay: Math.random() * 200,
      dur: 150 + Math.random() * 150,
      rotation: (angle * 180 / Math.PI) + 180, // Point toward center
    };
  }), []);
  const sparks = useMemo(() => Array.from({ length: ppFxN(14) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 12 + Math.random() * 30;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 2 + Math.random() * 5,
      color: ['#ffe033','#fff','#ffcc00','#ffffaa','#ffd700'][Math.floor(Math.random() * 5)],
      delay: 250 + Math.random() * 150,
      dur: 250 + Math.random() * 250,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-electric-flash" />
      {bolts.map((b, i) => (
        <div key={'eb'+i} className="anim-electric-bolt" style={{
          '--startX': b.startX + 'px', '--startY': b.startY + 'px', '--size': b.size + 'px',
          '--rotation': b.rotation + 'deg',
          animationDelay: b.delay + 'ms', animationDuration: b.dur + 'ms',
        }}>⚡</div>
      ))}
      {sparks.map((s, i) => (
        <div key={'es'+i} className="anim-explosion-particle" style={{
          '--dx': s.dx + 'px', '--dy': s.dy + 'px', '--size': s.size + 'px',
          '--color': s.color, animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Negated overlay — persistent small electricity sparks on the hero
// ★ v1047 (Als Befund 12.9.): DIE DAUER-ANZEIGE zeigte Blitze — das
// sah aus wie eine Betaeubung, obwohl die Karte VERSTUMMT ist. Der
// einmalige Einschlag ist seit v1046 ein Siegel; hier fehlte das
// Gegenstueck fuer die ganze Zeit, in der der Status anliegt.
// Jetzt: gedaempfte Siegelzeichen, die langsam auf- und abblenden,
// in demselben Violett wie `silence_seal`. Kein Gezucke.
function NegatedOverlay() {
  const zeichen = useMemo(() => Array.from({ length: ppFxN(7) }, () => ({
    x: 10 + Math.random() * 80,
    y: 10 + Math.random() * 80,
    size: 8 + Math.random() * 7,
    delay: Math.random() * 3,
    dur: 2.2 + Math.random() * 1.6,
  })), []);
  return (
    <div className="status-negated-overlay">
      {zeichen.map((z, i) => (
        <span key={i} className="negated-glyph" style={{
          left: z.x + '%', top: z.y + '%', fontSize: z.size,
          animationDelay: z.delay + 's', animationDuration: z.dur + 's',
        }}>🚫</span>
      ))}
    </div>
  );
}

// Flame strike — fire converging from all directions onto target
// Skeleton Demon's signature attack — black flames engulfing the
// target. Reuses flame_strike's radial-converge structure but with a
// dark-purple palette (CSS filter `brightness(0)` blackens the emoji
// silhouette and the drop-shadow filters paint the violet outer
// glow). `intensity` scales count + size + reach with the damage
// multiplier (50 dmg → intensity 1, 100 dmg → 2, 150 dmg → 3, …).
// Capped at 5 so absurd-multiplier hits still render legibly.
function BlackFlameStrikeEffect({ x, y, intensity = 1 }) {
  const k = Math.min(Math.max(intensity || 1, 1), 5);
  const flameCount = 14 + Math.round(k * 7);
  const sparkCount = 10 + Math.round(k * 4);
  const sizeMult   = 0.85 + k * 0.22;   // 1.07 → 1.95
  const reach      = 50 + k * 16;       // 66   → 130
  const flames = useMemo(() => Array.from({ length: flameCount }, () => {
    const angle = Math.random() * Math.PI * 2;
    const dist = 30 + Math.random() * reach;
    return {
      startX: Math.cos(angle) * dist,
      startY: Math.sin(angle) * dist,
      size: (10 + Math.random() * 14) * sizeMult,
      delay: Math.random() * 220,
      dur: 240 + Math.random() * 200,
      char: ['🔥','🔥','🔥','▲','✦'][Math.floor(Math.random() * 5)],
    };
  }), []);
  const sparks = useMemo(() => Array.from({ length: sparkCount }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = (15 + Math.random() * 30) * sizeMult;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 2 + Math.random() * 5 * sizeMult,
      // Deep-violet / black-purple shrapnel — matches the central
      // flash's palette so all colored bits stay in the same family.
      color: ['#1a0028','#2a0040','#3d0050','#440066','#1f0033'][Math.floor(Math.random() * 5)],
      delay: 320 + Math.random() * 160,
      dur: 320 + Math.random() * 260,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-black-flame-flash" style={{ '--bfScale': sizeMult }} />
      {flames.map((f, i) => (
        <div key={'bfl'+i} className="anim-black-flame-shard" style={{
          '--startX': f.startX + 'px', '--startY': f.startY + 'px', '--size': f.size + 'px',
          animationDelay: f.delay + 'ms', animationDuration: f.dur + 'ms',
        }}>{f.char}</div>
      ))}
      {sparks.map((s, i) => (
        <div key={'bfs'+i} className="anim-explosion-particle" style={{
          '--dx': s.dx + 'px', '--dy': s.dy + 'px', '--size': s.size + 'px',
          '--color': s.color, animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// ── Feuersaeule (Horned Demon, v602) ─────────────────────────────
// Als Vorgabe: „normal gefaerbtes (orange-rotes) Feuer, als eigene
// Animationsklasse, distinct von bestehenden Feuer-Animationen —
// eine FeuerSAEULE, die unter dem Ziel hervorschiesst und es einhuellt."
//
// Aufbau (Zeit 0-1000 ms, Schaden faellt bei ~450 ms):
//   1. Bodenriss-Glut unter der Karte (0-200 ms)
//   2. die Saeule schiesst von UNTEN hoch (transform-origin unten,
//      scaleY 0→1 in ~260 ms) und ueberragt die Karte oben deutlich
//   3. Flammenzungen (🔥) und Glutfunken steigen an den Raendern auf
//   4. Ausbrennen (700-1000 ms)
// `intensity` = Zahl der Demon Counter: mehr Zungen, breitere und
// hoehere Saeule (gedeckelt bei 5). `w`/`h` kommen von der Zielkarte,
// die Saeule ist also immer so breit wie das Ziel.
function DemonFirePillarEffect({ x, y, w = 80, h = 110, intensity = 1 }) {
  const k = Math.min(Math.max(intensity || 1, 1), 5);
  const width  = Math.max(48, w * (0.85 + k * 0.05));
  const height = h * (1.35 + k * 0.12);
  const tongues = useMemo(() => Array.from({ length: 10 + k * 4 }, () => ({
    xOff: (-0.5 + Math.random()) * width * 0.9,
    startY: h * 0.5 + Math.random() * 10,
    rise: 60 + Math.random() * height * 0.7,
    size: 12 + Math.random() * 12 + k * 1.5,
    delay: 120 + Math.random() * 380,
    dur: 380 + Math.random() * 320,
    sway: -14 + Math.random() * 28,
  })), []);
  const embers = useMemo(() => Array.from({ length: 12 + k * 3 }, () => ({
    xOff: (-0.5 + Math.random()) * width,
    rise: 80 + Math.random() * height,
    size: 2 + Math.random() * 4,
    color: ['#ffd23a', '#ff9a1f', '#ff6a00', '#ff3d00', '#ffe7a0'][Math.floor(Math.random() * 5)],
    delay: 200 + Math.random() * 450,
    dur: 450 + Math.random() * 350,
  })), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {/* Bodenglut: schmale Ellipse unter der Kartenunterkante */}
      <div className="anim-fire-pillar-ground" style={{ '--pw': width + 'px', '--ph': h + 'px' }} />
      {/* Die Saeule selbst — transform-origin unten, schiesst hoch */}
      <div className="anim-fire-pillar-column" style={{ '--pw': width + 'px', '--pheight': height + 'px', '--ph': h + 'px' }} />
      {/* Heller Kern */}
      <div className="anim-fire-pillar-core" style={{ '--pw': width + 'px', '--pheight': height + 'px', '--ph': h + 'px' }} />
      {tongues.map((t, i) => (
        <div key={'fpt'+i} className="anim-fire-pillar-tongue" style={{
          left: t.xOff + 'px', top: t.startY + 'px', fontSize: t.size + 'px',
          '--rise': t.rise + 'px', '--sway': t.sway + 'px',
          animationDelay: t.delay + 'ms', animationDuration: t.dur + 'ms',
        }}>🔥</div>
      ))}
      {embers.map((e, i) => (
        <div key={'fpe'+i} className="anim-fire-pillar-ember" style={{
          left: e.xOff + 'px', top: (h * 0.5) + 'px', width: e.size + 'px', height: e.size + 'px',
          background: e.color, '--rise': e.rise + 'px',
          animationDelay: e.delay + 'ms', animationDuration: e.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// ── Kavallerie-Sturm (Cavalry, v604) ─────────────────────────────
// Eine Reiterreihe (🐎) galoppiert von links durch die Zielkarte und
// hinaus, Staubwolken hinterher, kurzer Ruck des Ziels beim
// Durchbrechen. Klang `attack_ram` (ZONE_ANIM_SFX). Gespielt auf der
// HELDENkarte; der Schaden an seinen Support-Zonen folgt ueber aoeHit.
function CavalryChargeEffect({ x, y, w = 80, h = 110 }) {
  const span = Math.max(260, w * 3.2);
  const riders = useMemo(() => Array.from({ length: ppFxN(6) }, (_, i) => ({
    yOff: -h * 0.35 + (i % 3) * (h * 0.32) + (Math.random() - 0.5) * 8,
    delay: i * 55 + Math.random() * 40,
    dur: 520 + Math.random() * 120,
    size: 22 + Math.random() * 8,
  })), []);
  const dust = useMemo(() => Array.from({ length: ppFxN(22) }, () => ({
    xOff: -span * 0.5 + Math.random() * span,
    yOff: h * 0.15 + Math.random() * h * 0.35,
    size: 6 + Math.random() * 12,
    delay: 120 + Math.random() * 480,
    dur: 380 + Math.random() * 300,
    color: ['#c9a86a', '#b08d55', '#d9c08f', '#8f7040'][Math.floor(Math.random() * 4)],
  })), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {riders.map((r, i) => (
        <div key={'cvr'+i} className="anim-cavalry-rider" style={{
          top: r.yOff + 'px', fontSize: r.size + 'px', '--span': span + 'px',
          animationDelay: r.delay + 'ms', animationDuration: r.dur + 'ms',
        }}><span style={{ display: 'inline-block', transform: 'scaleX(-1)' }}>🐎</span></div>
      ))}
      {dust.map((d, i) => (
        <div key={'cvd'+i} className="anim-cavalry-dust" style={{
          left: d.xOff + 'px', top: d.yOff + 'px', width: d.size + 'px', height: d.size + 'px',
          background: d.color, animationDelay: d.delay + 'ms', animationDuration: d.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// ── Giftschaedel (Poisoned Meat, v615) ────────────────────────────
// Als Vorgabe: „Totenschaedel, die ueber der Creature kreisen und
// dabei nach und nach transparent werden." Fuenf Schaedel auf einer
// flachen Ellipse oberhalb der Karte, gestaffelt, mit gruenlichem
// Giftschein; ein schwacher Giftdunst darunter. Klang `poison`.
function PoisonSkullsEffect({ x, y, w = 80, h = 110 }) {
  const skulls = useMemo(() => Array.from({ length: 5 }, (_, i) => ({
    phase: (i / 5) * 360,
    delay: i * 90,
    size: 18 + (i % 2) * 6,
    dur: 1500 + (i % 3) * 120,
  })), []);
  const rx = Math.max(34, w * 0.55);
  const flat = 0.32; // Ellipse: Hoehe = 32 % der Breite (perspektivisch „von schraeg oben")
  return (
    <div style={{ position: 'fixed', left: x, top: y - h * 0.38, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-poison-skull-haze" style={{ '--hw': (rx * 2.4) + 'px' }} />
      {/* Flach gedrueckte Bahn: der Wrapper staucht den Kreis zur Ellipse,
          der Schaedel bekommt die Gegenstauchung + Gegenrotation, damit
          er aufrecht und unverzerrt bleibt. */}
      <div style={{ position: 'absolute', left: 0, top: 0, transform: `scaleY(${flat})` }}>
        {skulls.map((s, i) => (
          <div key={'psk'+i} className="anim-poison-skull-orbit" style={{
            '--rx': rx + 'px', '--phase': s.phase + 'deg',
            animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
          }}>
            <span className="anim-poison-skull" style={{
              fontSize: s.size + 'px', '--phase': s.phase + 'deg', '--unflat': (1 / flat),
              animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
            }}>💀</span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Blitzregen (Piercer of Heavens, v617) ──────────────────────────
// Als Vorgabe: „ein Regen aus Blitzen auf das Ziel, von denen jeder
// einen eigenen Impact-Sound haben soll". Acht gezackte Blitze fallen
// gestaffelt vom oberen Bildrand auf leicht versetzte Punkte der
// Zielkarte; jeder Einschlag: Blitz sichtbar, Aufschlagblitz UND ein
// eigener `elem_lightning` (leicht variierte Tonhoehe) — deshalb kein
// Eintrag in ZONE_ANIM_SFX, die Klaenge kommen aus der Komponente.
function LightningRainEffect({ x, y, w = 80, h = 110 }) {
  const bolts = useMemo(() => Array.from({ length: ppFxN(8) }, (_, i) => {
    const ox = (Math.random() - 0.5) * w * 0.9;
    const oy = (Math.random() - 0.5) * h * 0.7;
    // Zackenpfad von oben (y = -H) bis zum Einschlag (0,0), 6 Segmente
    const H = 900;
    const pts = [[ox + (Math.random() - 0.5) * 60, -H]];
    for (let k = 1; k <= 6; k++) {
      const t = k / 6;
      pts.push([ox + (1 - t) * (Math.random() - 0.5) * 70, -H + t * (H + oy)]);
    }
    pts[pts.length - 1] = [ox, oy];
    return { ox, oy, pts: pts.map(p => p.join(',')).join(' '), delay: 60 + i * 110 + Math.random() * 40, width: 2 + Math.random() * 2, rate: 0.85 + Math.random() * 0.4 };
  }), []);
  useEffect(() => {
    const timers = bolts.map(b => setTimeout(() => {
      // KEINE Kategorie und dedupe 0: die Kategorie 'effect' wuerde alle
      // Einschlaege innerhalb von 400 ms auf einen Klang zusammenfalten.
      if (window.playSFX) window.playSFX('elem_lightning', { rate: b.rate, volume: 0.75, dedupe: 0 });
    }, b.delay + 40));
    return () => timers.forEach(clearTimeout);
  }, []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <svg style={{ position: 'absolute', left: -600, top: -1000, overflow: 'visible' }} width="1200" height="1200" viewBox="-600 -1000 1200 1200" xmlns="http://www.w3.org/2000/svg">
        {bolts.map((b, i) => (
          <g key={'lrb'+i} className="anim-lightning-rain-bolt" style={{ animationDelay: b.delay + 'ms' }}>
            <polyline points={b.pts} fill="none" stroke="#7fd3ff" strokeWidth={b.width + 4} strokeLinejoin="round" strokeLinecap="round" opacity="0.45" />
            <polyline points={b.pts} fill="none" stroke="#ffffff" strokeWidth={b.width} strokeLinejoin="round" strokeLinecap="round" />
          </g>
        ))}
      </svg>
      {bolts.map((b, i) => (
        <div key={'lrf'+i} className="anim-lightning-rain-flash" style={{ left: b.ox + 'px', top: b.oy + 'px', animationDelay: (b.delay + 30) + 'ms' }} />
      ))}
    </div>
  );
}

// ── Nebelschleier (Chasing the Legend, v618) ───────────────────────
// Weisse Nebelschwaden quellen um die Karte auf, waehrend sie (per
// `play_cloak_vanish`) verblasst. Klang `elem_wind` tief.
// ── Kernexplosion (Core Explosion, v1334) ──────────────────────────
// Der Kern der gefallenen Creature platzt: dunkler Kern mit roten
// Rissen schwillt an, weiss-tuerkiser Blitz, zwei Druckwellen, zackige
// Entladungsbogen nach allen Seiten und Funken (Kartenbild als Vorlage).
// Klang aus der Komponente, zwei Schichten ohne Kategorie (Regel ⑤):
// schwerer Einschlag + Elektrizitaet. Keyframes in style.css (Regel ④).
function CoreExplosionEffect({ x, y, w = 80 }) {
  const r = Math.max(70, w * 1.5);
  const boegen = useMemo(() => Array.from({ length: ppFxN(10) }, (_, i) => {
    const winkel = (i / 10) * Math.PI * 2 + (Math.random() - 0.5) * 0.4;
    const laenge = r * (0.9 + Math.random() * 0.8);
    const punkte = [];
    const N = 6;
    for (let k = 0; k <= N; k++) {
      const t = k / N;
      const quer = (Math.random() - 0.5) * 22 * Math.sin(Math.PI * t);
      punkte.push(`${Math.cos(winkel) * laenge * t - Math.sin(winkel) * quer},${Math.sin(winkel) * laenge * t + Math.cos(winkel) * quer}`);
    }
    return { punkte: punkte.join(' '), verzug: 60 + Math.random() * 160 };
  }), [r]);
  const funken = useMemo(() => Array.from({ length: ppFxN(22) }, () => {
    const winkel = Math.random() * Math.PI * 2;
    const weite = r * (0.6 + Math.random() * 0.9);
    return {
      dx: Math.cos(winkel) * weite, dy: Math.sin(winkel) * weite,
      groesse: 4 + Math.random() * 6,
      farbe: ['#8ff4ff', '#ffffff', '#ff6fd8', '#5ad1ff'][Math.floor(Math.random() * 4)],
      verzug: 80 + Math.random() * 200,
    };
  }), [r]);
  useEffect(() => {
    const spiel = (name, opts, at) => setTimeout(() => { if (window.playSFX) window.playSFX(name, { ...opts, dedupe: 0 }); }, at);
    spiel('heavy_impact', { rate: 0.7, volume: 1 }, 60);
    spiel('elem_lightning', { rate: 0.9, volume: 0.9 }, 0);
  }, []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10205 }}>
      <div className="anim-core-kern" style={{ width: r * 0.7, height: r * 0.7, left: -r * 0.35, top: -r * 0.35 }} />
      <div className="anim-core-blitz" style={{ width: r * 2.2, height: r * 2.2, left: -r * 1.1, top: -r * 1.1 }} />
      <div className="anim-core-welle" style={{ width: r * 2, height: r * 2, left: -r, top: -r }} />
      <div className="anim-core-welle anim-core-welle-2" style={{ width: r * 2, height: r * 2, left: -r, top: -r }} />
      <svg className="anim-core-boegen" style={{ position: 'absolute', left: 0, top: 0, overflow: 'visible' }} width="1" height="1">
        {boegen.map((b, i) => (
          <polyline key={i} points={b.punkte} className="anim-core-bogen" style={{ animationDelay: b.verzug + 'ms' }} />
        ))}
      </svg>
      {funken.map((f, i) => (
        <div key={i} className="anim-core-funke" style={{
          width: f.groesse, height: f.groesse, left: -f.groesse / 2, top: -f.groesse / 2,
          background: f.farbe, boxShadow: `0 0 10px ${f.farbe}, 0 0 20px ${f.farbe}`,
          '--fdx': f.dx + 'px', '--fdy': f.dy + 'px', animationDelay: f.verzug + 'ms',
        }} />
      ))}
    </div>
  );
}

// ── Gedaechtnisloeschung (Memory Wipe, v1335) ─────────────────────
// Kartenbild als Vorlage: ein violetter Runenkreis mit Fadenkreuz legt
// sich ueber den Helden und zieht sich zusammen, in der Mitte pulsiert
// ein tuerkis-weisser Funke — dann loesen sich Erinnerungsfragmente
// (kleine Pixel-Splitter) und steigen verblassend auf. Klang aus der
// Komponente, zwei Schichten ohne Kategorie (Regel ⑤). Keyframes in
// style.css (Regel ④).
function MemoryWipeEffect({ x, y, w = 80 }) {
  const r = Math.max(46, w * 0.75);
  const splitter = useMemo(() => Array.from({ length: ppFxN(16) }, () => ({
    dx: (Math.random() - 0.5) * r * 1.6,
    dy: -(r * 0.6 + Math.random() * r * 1.1),
    sx: (Math.random() - 0.5) * r * 1.1,
    sy: (Math.random() - 0.5) * r * 0.9,
    groesse: 3 + Math.random() * 4,
    farbe: ['#b98cff', '#8a5cff', '#9ff3ff', '#ffffff'][Math.floor(Math.random() * 4)],
    verzug: 380 + Math.random() * 380,
  })), [r]);
  useEffect(() => {
    const spiel = (name, opts, at) => setTimeout(() => { if (window.playSFX) window.playSFX(name, { ...opts, dedupe: 0 }); }, at);
    spiel('elem_dark', { rate: 1.1, volume: 0.9 }, 0);
    spiel('reveal', { rate: 0.7, volume: 0.8 }, 380);
  }, []);
  const striche = [0, 90, 180, 270];
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10205 }}>
      <svg className="anim-mw-rune" width={r * 2} height={r * 2} viewBox={`${-r} ${-r} ${r * 2} ${r * 2}`}
        style={{ position: 'absolute', left: -r, top: -r, overflow: 'visible' }}>
        <circle r={r * 0.82} className="anim-mw-ring" />
        <circle r={r * 0.5} className="anim-mw-ring anim-mw-ring-innen" />
        {striche.map(g => {
          const a = g * Math.PI / 180;
          return <line key={g} className="anim-mw-strich"
            x1={Math.cos(a) * r * 0.58} y1={Math.sin(a) * r * 0.58}
            x2={Math.cos(a) * r * 1.02} y2={Math.sin(a) * r * 1.02} />;
        })}
      </svg>
      <div className="anim-mw-funke" style={{ width: r * 0.5, height: r * 0.5, left: -r * 0.25, top: -r * 0.25 }} />
      {splitter.map((s, i) => (
        <div key={i} className="anim-mw-splitter" style={{
          width: s.groesse, height: s.groesse, left: s.sx - s.groesse / 2, top: s.sy - s.groesse / 2,
          background: s.farbe, boxShadow: `0 0 6px ${s.farbe}`,
          '--mdx': s.dx + 'px', '--mdy': s.dy + 'px', animationDelay: s.verzug + 'ms',
        }} />
      ))}
    </div>
  );
}

// ── Wutausbruch (Furious Anger, v1336) ──────────────────────────────
// Kartenbild als Vorlage: das Manga-Wutzeichen — ein weisser, schwarz
// umrandeter Zackenstern mit zwei roten „!" — ploppt ueber dem Helden
// auf, federt und zittert; der Held selbst glueht rot, Dampfwoelkchen
// steigen auf. Das Feuer der Karte ist nur Stimmung: ein paar Flammen-
// zungen am Kartenfuss. Klang aus der Komponente, zwei Schichten ohne
// Kategorie (Regel ⑤). Keyframes in style.css (Regel ④).
function FuriousAngerEffect({ x, y, w = 80, h = 110 }) {
  const s = Math.max(40, w * 0.62);
  const zacken = useMemo(() => {
    const n = 11, pts = [];
    for (let i = 0; i < n * 2; i++) {
      const a = (i / (n * 2)) * Math.PI * 2 - Math.PI / 2;
      const r = i % 2 === 0 ? s : s * (0.52 + Math.random() * 0.12);
      pts.push(`${(Math.cos(a) * r).toFixed(1)},${(Math.sin(a) * r).toFixed(1)}`);
    }
    return pts.join(' ');
  }, [s]);
  const dampf = useMemo(() => Array.from({ length: ppFxN(6) }, (_, i) => ({
    dx: (i % 2 === 0 ? -1 : 1) * (w * 0.25 + Math.random() * w * 0.2),
    verzug: 250 + i * 110, groesse: 12 + Math.random() * 10,
  })), [w]);
  const flammen = useMemo(() => Array.from({ length: ppFxN(7) }, (_, i) => ({
    dx: (i / 6 - 0.5) * w * 1.1, hoehe: h * (0.25 + Math.random() * 0.25), verzug: Math.random() * 300,
  })), [w, h]);
  useEffect(() => {
    const spiel = (name, opts, at) => setTimeout(() => { if (window.playSFX) window.playSFX(name, { ...opts, dedupe: 0 }); }, at);
    spiel('critical_strike', { rate: 1.2, volume: 0.9 }, 0);
    spiel('elem_fire', { rate: 0.8, volume: 0.7 }, 120);
  }, []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10205 }}>
      <div className="anim-fa-glut" style={{ width: w * 1.3, height: h * 1.2, left: -w * 0.65, top: -h * 0.6 }} />
      {flammen.map((f, i) => (
        <div key={'f' + i} className="anim-fa-flamme" style={{
          left: f.dx - 7, top: h * 0.5 - f.hoehe, width: 14, height: f.hoehe, animationDelay: f.verzug + 'ms',
        }} />
      ))}
      {dampf.map((d, i) => (
        <div key={'d' + i} className="anim-fa-dampf" style={{
          left: d.dx - d.groesse / 2, top: -h * 0.35, width: d.groesse, height: d.groesse, animationDelay: d.verzug + 'ms',
        }} />
      ))}
      <svg className="anim-fa-zeichen" width={s * 2.4} height={s * 2.4} viewBox={`${-s * 1.2} ${-s * 1.2} ${s * 2.4} ${s * 2.4}`}
        style={{ position: 'absolute', left: -s * 1.2 + w * 0.15, top: -h * 0.55 - s * 1.2, overflow: 'visible' }}>
        <polygon points={zacken} fill="#ffffff" stroke="#111" strokeWidth="3" strokeLinejoin="miter" />
        <rect x={-s * 0.28} y={-s * 0.42} width={s * 0.16} height={s * 0.55} fill="#8b0d0d" />
        <rect x={-s * 0.28} y={s * 0.2} width={s * 0.16} height={s * 0.16} fill="#8b0d0d" />
        <rect x={s * 0.1} y={-s * 0.42} width={s * 0.16} height={s * 0.55} fill="#8b0d0d" />
        <rect x={s * 0.1} y={s * 0.2} width={s * 0.16} height={s * 0.16} fill="#8b0d0d" />
      </svg>
    </div>
  );
}

// ── Goldene Aura (Cheat Chair, v1341 — neu gebaut) ─────────────────
// Als Vorgabe: „eine goldene Aura, die den Hero umhuellt, wie bei einem
// Super-Saiyajin". Die CSS-Fassung aus v1340 war zu steif — und wurde
// obendrein nach 1 s abgeschnitten (Zonen-Animationen leben ohne
// `duration` nur 1000 ms). Jetzt ein kleines Partikelsystem auf einer
// Leinwand mit additiver Mischung:
//   • Flammenpartikel steigen rund um den Kartenrand auf und werden beim
//     Steigen zur Mitte gezogen — die typische, nach oben spitz
//     zulaufende Aura-Silhouette, die ueber der Karte zusammenschlaegt;
//   • weiches goldenes Gluehen hinter allem, das pulsiert, und ein
//     leuchtender Kartenrand;
//   • Auftakt: Lichtblitz und Druckring; zwischendurch blau-weisse
//     Entladungen am Kartenrand (Super-Saiyajin 2).
// Dauer 2,2 s (der Server gibt sie mit), Handy: weniger Partikel.
// Klang aus der Komponente, drei Schichten ohne Kategorie (Regel ⑤).
const SUPER_AURA_MS = 2200;
function SuperAuraEffect({ x, y, w = 80, h = 110 }) {
  const ref = useRef(null);
  const W = Math.round(w * 2.8), H = Math.round(h * 2.9);
  const cx = W / 2, cy = H * 0.6;
  useEffect(() => {
    const spiel = (name, opts, at) => setTimeout(() => { if (window.playSFX) window.playSFX(name, { ...opts, dedupe: 0 }); }, at);
    spiel('ascension', { rate: 1.0, volume: 1 }, 0);
    spiel('elem_wind', { rate: 0.65, volume: 0.55 }, 90);
    spiel('elem_lightning', { rate: 1.35, volume: 0.45 }, 520);

    const cv = ref.current;
    if (!cv) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    cv.width = W * dpr; cv.height = H * dpr;
    const ctx = cv.getContext('2d');
    ctx.scale(dpr, dpr);
    const k = h / 110;                                   // Massstab zur Kartengroesse
    const hw = w / 2, hh = h / 2;

    // Vorgerenderte Leuchtpunkte (weich, additiv) — drei Farbstufen.
    const sprite = (stops) => {
      const c = document.createElement('canvas'); c.width = c.height = 64;
      const g = c.getContext('2d');
      const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
      stops.forEach(([o, col]) => gr.addColorStop(o, col));
      g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
      return c;
    };
    const SP_KERN = sprite([[0, 'rgba(255,255,235,1)'], [0.35, 'rgba(255,240,150,.8)'], [1, 'rgba(255,200,40,0)']]);
    const SP_GOLD = sprite([[0, 'rgba(255,230,110,.95)'], [0.45, 'rgba(255,190,30,.55)'], [1, 'rgba(255,150,0,0)']]);
    const SP_ROT  = sprite([[0, 'rgba(255,190,60,.7)'], [0.5, 'rgba(255,120,10,.35)'], [1, 'rgba(255,80,0,0)']]);

    // Punkt auf dem (leicht vergroesserten) Kartenrand; Seiten und Boden
    // bekommen mehr Flammen als die Oberkante (dort schlaegt die Aura zusammen).
    const randPunkt = () => {
      const pad = 5 * k;
      const r = Math.random();
      if (r < 0.36) return { x: cx - hw - pad, y: cy - hh + Math.random() * h };
      if (r < 0.72) return { x: cx + hw + pad, y: cy - hh + Math.random() * h };
      if (r < 0.9)  return { x: cx - hw + Math.random() * w, y: cy + hh + pad };
      return { x: cx - hw + Math.random() * w, y: cy - hh - pad };
    };

    const teile = [];
    const rate = ppFxN(300);                             // Partikel je Sekunde
    let rest = 0;
    const entladungen = [];
    let naechsteEntladung = 380;
    const t0 = performance.now();
    let letzte = t0, raf = 0;

    const huelle = (t) => {
      if (t < 260) { const q = t / 260; return 1 - (1 - q) * (1 - q); }
      if (t < 1650) return 0.88 + 0.12 * Math.sin(t / 70);
      return Math.max(0, 1 - (t - 1650) / (SUPER_AURA_MS - 1650));
    };

    const schritt = (jetzt) => {
      const t = jetzt - t0;
      const dt = Math.min(0.05, (jetzt - letzte) / 1000);
      letzte = jetzt;
      const env = huelle(t);
      ctx.clearRect(0, 0, W, H);
      ctx.globalCompositeOperation = 'lighter';

      // Gluehen hinter allem (pulsierend, oben etwas hoeher gezogen).
      if (env > 0) {
        ctx.save();
        ctx.translate(cx, cy - hh * 0.25);
        ctx.scale(1, 1.45);
        const R = Math.max(w, h) * 0.95;
        const g = ctx.createRadialGradient(0, 0, R * 0.2, 0, 0, R);
        g.addColorStop(0, `rgba(255,225,90,${0.42 * env})`);
        g.addColorStop(0.55, `rgba(255,180,20,${0.22 * env})`);
        g.addColorStop(1, 'rgba(255,140,0,0)');
        ctx.fillStyle = g;
        ctx.beginPath(); ctx.arc(0, 0, R, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
      }

      // Auftakt: Blitz + Druckring.
      if (t < 520) {
        const q = t / 520;
        const R = Math.max(w, h) * (0.4 + q * 1.1);
        const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, R);
        g.addColorStop(0, `rgba(255,255,255,${0.9 * (1 - q)})`);
        g.addColorStop(0.5, `rgba(255,240,160,${0.5 * (1 - q)})`);
        g.addColorStop(1, 'rgba(255,210,60,0)');
        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = `rgba(255,236,150,${0.85 * (1 - q)})`;
        ctx.lineWidth = 4 * k * (1 - q) + 1;
        ctx.beginPath(); ctx.ellipse(cx, cy, hw * (1 + q * 1.6), hh * (1 + q * 1.2), 0, 0, Math.PI * 2); ctx.stroke();
      }

      // Neue Flammenpartikel.
      if (t < 1720) {
        rest += rate * dt * (0.4 + 0.6 * env);
        while (rest >= 1) {
          rest -= 1;
          const p = randPunkt();
          const leben = 0.42 + Math.random() * 0.4;
          teile.push({
            x: p.x, y: p.y,
            vx: (p.x - cx) / hw * 18 * k + (Math.random() - 0.5) * 20 * k,
            vy: -(150 + Math.random() * 160) * k,
            r: (8 + Math.random() * 12) * k,
            leben, alter: 0,
            phase: Math.random() * Math.PI * 2,
            art: Math.random(),
          });
        }
      }

      // Partikel bewegen und zeichnen: zur Mitte gezogen, je hoeher, desto staerker.
      for (let i = teile.length - 1; i >= 0; i--) {
        const q = teile[i];
        q.alter += dt;
        const f = q.alter / q.leben;
        if (f >= 1) { teile.splice(i, 1); continue; }
        const ueber = Math.max(0, (cy - hh) - q.y);          // Hoehe ueber der Oberkante
        q.vx += (-(q.x - cx) * (2.2 + ueber / (h * 0.25))) * dt;
        q.vy -= 60 * k * dt;
        q.x += (q.vx + Math.sin(q.phase + q.alter * 14) * 22 * k) * dt;
        q.y += q.vy * dt;
        const r = q.r * (1 - f * 0.75);
        const a = (f < 0.15 ? f / 0.15 : 1 - (f - 0.15) / 0.85) * env;
        const bild = f < 0.3 && q.art > 0.45 ? SP_KERN : (f < 0.7 ? SP_GOLD : SP_ROT);
        ctx.globalAlpha = Math.max(0, Math.min(1, a));
        ctx.drawImage(bild, q.x - r, q.y - r * 1.25, r * 2, r * 2.5);   // leicht in die Hoehe gezogen
      }
      ctx.globalAlpha = 1;

      // Leuchtender Kartenrand.
      if (env > 0) {
        ctx.save();
        ctx.shadowColor = 'rgba(255,215,60,1)';
        ctx.shadowBlur = 14 * k;
        ctx.strokeStyle = `rgba(255,236,140,${0.75 * env})`;
        ctx.lineWidth = 2.5 * k;
        const rr = 6 * k;
        ctx.beginPath();
        ctx.moveTo(cx - hw + rr, cy - hh); ctx.lineTo(cx + hw - rr, cy - hh);
        ctx.quadraticCurveTo(cx + hw, cy - hh, cx + hw, cy - hh + rr); ctx.lineTo(cx + hw, cy + hh - rr);
        ctx.quadraticCurveTo(cx + hw, cy + hh, cx + hw - rr, cy + hh); ctx.lineTo(cx - hw + rr, cy + hh);
        ctx.quadraticCurveTo(cx - hw, cy + hh, cx - hw, cy + hh - rr); ctx.lineTo(cx - hw, cy - hh + rr);
        ctx.quadraticCurveTo(cx - hw, cy - hh, cx - hw + rr, cy - hh);
        ctx.stroke();
        ctx.restore();
      }

      // Blau-weisse Entladungen am Rand.
      if (t >= naechsteEntladung && t < 1600) {
        naechsteEntladung = t + 170 + Math.random() * 230;
        const seite = Math.random() < 0.5 ? -1 : 1;
        let px = cx + seite * (hw + 4 * k), py = cy - hh + Math.random() * h * 0.7;
        const pts = [[px, py]];
        for (let j = 0; j < 5; j++) { px += seite * (Math.random() * 10 - 2) * k; py += (6 + Math.random() * 12) * k; pts.push([px + (Math.random() - 0.5) * 10 * k, py]); }
        entladungen.push({ pts, bis: t + 110 });
      }
      for (let i = entladungen.length - 1; i >= 0; i--) {
        const e = entladungen[i];
        if (t > e.bis) { entladungen.splice(i, 1); continue; }
        ctx.save();
        ctx.shadowColor = '#7fdcff'; ctx.shadowBlur = 10 * k;
        ctx.strokeStyle = 'rgba(235,250,255,.95)'; ctx.lineWidth = 1.8 * k; ctx.lineJoin = 'round';
        ctx.beginPath(); e.pts.forEach(([a, b], j) => (j ? ctx.lineTo(a, b) : ctx.moveTo(a, b))); ctx.stroke();
        ctx.restore();
      }

      if (t < SUPER_AURA_MS) raf = requestAnimationFrame(schritt);
      else ctx.clearRect(0, 0, W, H);
    };
    raf = requestAnimationFrame(schritt);
    return () => cancelAnimationFrame(raf);
  }, []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10205 }}>
      <canvas ref={ref} style={{ position: 'absolute', left: -cx, top: -cy, width: W, height: H }} />
    </div>
  );
}

function MistVeilEffect({ x, y, w = 80, h = 110 }) {
  const wisps = useMemo(() => Array.from({ length: ppFxN(14) }, () => ({
    xOff: (Math.random() - 0.5) * w * 1.4,
    yOff: (Math.random() - 0.5) * h * 1.2,
    size: 30 + Math.random() * 40,
    drift: (Math.random() - 0.5) * 40,
    rise: -10 - Math.random() * 25,
    delay: Math.random() * 500,
    dur: 900 + Math.random() * 600,
  })), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10099 }}>
      {wisps.map((m, i) => (
        <div key={'mv'+i} className="anim-mist-wisp" style={{
          left: m.xOff + 'px', top: m.yOff + 'px', width: m.size + 'px', height: (m.size * 0.6) + 'px',
          '--drift': m.drift + 'px', '--rise': m.rise + 'px',
          animationDelay: m.delay + 'ms', animationDuration: m.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// ── Meteor (Meteor Crash, v623) ────────────────────────────────────
// Ein gluehender Felsbrocken faellt von SCHRAEG OBEN RECHTS ins Bild,
// zieht einen Feuerschweif hinter sich her und schlaegt auf dem Ziel
// ein: Aufschlagblitz, Erdbrocken und Glut nach allen Seiten. Mit
// `intensity` (300er-Fall) groesser und mehr Truemmer. Klang
// `heavy_impact` beim Aufschlag (ZONE_ANIM_SFX, ~520 ms).
function MeteorCrashEffect({ x, y, w = 80, intensity = 1 }) {
  const k = Math.min(Math.max(intensity || 1, 1), 3);
  const size = 34 + k * 10;
  const startX = Math.max(320, window.innerWidth - x + 60);   // von rechts ausserhalb des Bildes
  const startY = -(y + 80);                                     // von oben ausserhalb des Bildes
  // v624: Schweif exakt entgegen der Flugrichtung — Winkel vom Ziel
  // zurueck zum Startpunkt (vorher fest -38°, was je nach Ziel schief
  // aussah).
  const tailAngle = Math.atan2(startY, startX) * 180 / Math.PI;
  // v625: der KNALL kommt komplett aus der Komponente. Grund: Klaenge
  // aus ZONE_ANIM_SFX laufen in der Kategorie 'effect' und werden dort
  // innerhalb von 400 ms auf EINEN Klang zusammengefaltet — der
  // Spell-Cast-Cue schluckte den Einschlag. Hier: ohne Kategorie,
  // dedupe 0, drei Ebenen gestaffelt: tiefer schwerer Einschlag,
  // Feuerstoss und ein zweiter Impact als Nachhall.
  useEffect(() => {
    const play = (name, opts, at) => setTimeout(() => { if (window.playSFX) window.playSFX(name, { ...opts, dedupe: 0 }); }, at);
    const ts = [
      play('heavy_impact', { rate: 0.55, volume: 1 }, 505),
      play('elem_fire', { rate: 0.6, volume: 1 }, 520),
      play('critical_strike', { rate: 0.7, volume: 0.9 }, 540),
      play('heavy_impact', { rate: 0.8, volume: 0.6 }, 700),
    ];
    return () => ts.forEach(clearTimeout);
  }, []);
  const debris = useMemo(() => Array.from({ length: 22 + k * 8 }, () => {
    const a = Math.PI + Math.random() * Math.PI;               // nach oben faechernd
    const sp = 40 + Math.random() * (70 + k * 20);
    return { dx: Math.cos(a) * sp, dy: Math.sin(a) * sp * 0.8, size: 4 + Math.random() * 7,
      color: ['#6b4a2a', '#8a5a30', '#ff8a1f', '#ffd25a', '#3a2412', '#ff4d00'][Math.floor(Math.random() * 6)],
      delay: 520 + Math.random() * 80, dur: 420 + Math.random() * 320 };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-meteor-rock" style={{ '--sx': startX + 'px', '--sy': startY + 'px', '--size': size + 'px', '--tail': tailAngle + 'deg' }}>
        <div className="anim-meteor-tail" />
        <div className="anim-meteor-core" />
      </div>
      {/* v624: grosser Einschlag — Blitz, Druckwelle, Bodenriss-Glut */}
      <div className="anim-meteor-flash" style={{ '--fw': (w * (2.2 + k * 0.5)) + 'px' }} />
      <div className="anim-meteor-shockwave" style={{ '--fw': (w * (3 + k * 0.8)) + 'px' }} />
      <div className="anim-meteor-shockwave anim-meteor-shockwave--late" style={{ '--fw': (w * (2.2 + k * 0.6)) + 'px' }} />
      <div className="anim-meteor-crater" style={{ '--fw': (w * (1.6 + k * 0.2)) + 'px' }} />
      {debris.map((d, i) => (
        <div key={'mtd'+i} className="anim-explosion-particle" style={{
          '--dx': d.dx + 'px', '--dy': d.dy + 'px', '--size': d.size + 'px', '--color': d.color,
          animationDelay: d.delay + 'ms', animationDuration: d.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

function FlameStrikeEffect({ x, y }) {
  const flames = useMemo(() => Array.from({ length: ppFxN(18) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const dist = 55 + Math.random() * 45;
    return {
      startX: Math.cos(angle) * dist,
      startY: Math.sin(angle) * dist,
      size: 10 + Math.random() * 12,
      delay: Math.random() * 180,
      dur: 200 + Math.random() * 150,
      char: ['🔥','🔥','🔥','✦','·'][Math.floor(Math.random() * 5)],
    };
  }), []);
  const sparks = useMemo(() => Array.from({ length: ppFxN(12) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 15 + Math.random() * 30;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 2 + Math.random() * 5,
      color: ['#ff4400','#ff8800','#ffcc00','#ff2200','#ffaa00'][Math.floor(Math.random() * 5)],
      delay: 300 + Math.random() * 150,
      dur: 300 + Math.random() * 250,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-flame-flash" />
      {flames.map((f, i) => (
        <div key={'fl'+i} className="anim-flame-shard" style={{
          '--startX': f.startX + 'px', '--startY': f.startY + 'px', '--size': f.size + 'px',
          animationDelay: f.delay + 'ms', animationDuration: f.dur + 'ms',
        }}>{f.char}</div>
      ))}
      {sparks.map((s, i) => (
        <div key={'fs'+i} className="anim-explosion-particle" style={{
          '--dx': s.dx + 'px', '--dy': s.dy + 'px', '--size': s.size + 'px',
          '--color': s.color, animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Hand ambiance — an always-on atmospheric layer for the player's OWN hand:
//   • BLOOM: soft player-coloured light rising from the bottom edge of the
//     hand strip, screen-blended over its dark background and gently
//     pulsing. Painted first in DOM order so it sits behind the cards.
//   • PIXEL PARTICLES: sparse pixel motes drifting slowly upward off the
//     hand, tinted the player's colour (plus the odd white sparkle). Kept
//     small + low-opacity so they read as ambient dust, never clutter, and
//     float just above the cards (z-index) so they're actually visible.
// Both layers are pointer-events:none and respect prefers-reduced-motion.
// The colour comes in as the player's chosen colour.
function HandAmbiance({ color }) {
  const motes = useMemo(() => {
    const N = 80;   // doubled from 40 — denser pixel rain over the hand
    const arr = [];
    for (let i = 0; i < N; i++) {
      const dur = 3 + Math.random() * 4;                 // 3–7s drift (snappier)
      arr.push({
        top:   Math.random() * 100,
        left:  Math.random() * 100,
        size:  2 + Math.floor(Math.random() * 3),        // 2–4px pixel squares
        dur,
        delay: -Math.random() * dur,                     // mid-cycle stagger
        dx:    (Math.random() * 2 - 1) * 26,             // -26..26px horizontal drift
        dy:    -(24 + Math.random() * 90),               // rise far enough to leave the hand
        max:   0.22 + Math.random() * 0.3,               // subtle peak opacity
        // Mostly the player's colour; ~30% white for a sparkle.
        color: Math.random() < 0.3 ? '#ffffff' : 'var(--amb-me)',
      });
    }
    return arr;
  }, []);
  return (
    <div className="hand-ambiance" aria-hidden="true"
      style={{ '--amb-me': color || '#00f0ff' }}>
      <div className="hand-bloom" />
      <div className="hand-particles">
        {motes.map((p, i) => (
          <span key={i} className="hand-mote" style={{
            top: p.top + '%', left: p.left + '%',
            '--p-size': p.size + 'px',
            '--p-color': p.color,
            '--p-dur': p.dur + 's',
            '--p-delay': p.delay + 's',
            '--p-dx': p.dx + 'px',
            '--p-dy': p.dy + 'px',
            '--p-max': p.max,
          }} />
        ))}
      </div>
    </div>
  );
}

// Battlefield ambiance — always-on pixel motes drifting upward across the
// whole battlefield background, mirroring the visual language of
// HandAmbiance (small pixel squares, slow rise, subtle opacity) so hand
// and board read as one continuous atmosphere. Differences vs the hand:
//   • BACKGROUND layer: mounted as the FIRST child of .board-center with
//     z-index 0, so every zone / card / area overlay paints on top — the
//     motes stay strictly behind the play field.
//   • OWNERSHIP TINT: motes spawning in the bottom half are tinted the
//     local player's colour, top-half motes the opponent's colour, plus
//     ~25% white sparkles — the ambiance subtly mirrors side ownership.
//   • Dimmer + slower than the hand layer so it never competes with
//     cards for attention.
// pointer-events: none, respects prefers-reduced-motion (see .board-mote).
function BoardAmbiance({ colorMe, colorOpp }) {
  const motes = useMemo(() => {
    const N = 56;
    const arr = [];
    for (let i = 0; i < N; i++) {
      const dur = 4 + Math.random() * 5;                 // 4–9s — calmer than the hand
      const top = Math.random() * 100;
      arr.push({
        top,
        left: Math.random() * 100,
        size: 2 + Math.floor(Math.random() * 3),         // 2–4px pixel squares
        dur,
        delay: -Math.random() * dur,                     // mid-cycle stagger
        dx:   (Math.random() * 2 - 1) * 34,              // -34..34px horizontal drift
        dy:   -(40 + Math.random() * 130),               // long rise across the field
        max:  0.14 + Math.random() * 0.22,               // dim — background layer
        color: Math.random() < 0.25 ? '#ffffff'
             : (top > 50 ? 'var(--amb-board-me)' : 'var(--amb-board-opp)'),
      });
    }
    return arr;
  }, []);
  return (
    <div className="board-ambiance" aria-hidden="true"
      style={{ '--amb-board-me': colorMe || '#00f0ff', '--amb-board-opp': colorOpp || '#ff5577' }}>
      {motes.map((p, i) => (
        <span key={i} className="board-mote" style={{
          top: p.top + '%', left: p.left + '%',
          '--p-size': p.size + 'px',
          '--p-color': p.color,
          '--p-dur': p.dur + 's',
          '--p-delay': p.delay + 's',
          '--p-dx': p.dx + 'px',
          '--p-dy': p.dy + 'px',
          '--p-max': p.max,
        }} />
      ))}
    </div>
  );
}


/**
 * Die Koerner des „Pocket Sand"-Projektils (v1059). EINMAL gewuerfelt
 * und als Modul-Konstante gehalten: bei jedem Render neu zu streuen
 * liesse den Haufen im Flug flackern.
 */
// ★★ v1148 (Al 17.9.: „deutlich mehr Particles und kleiner — eine
// wirkliche Sanddusche"). Aus 22 Koernern zu 3–9 px werden 90 zu 1–3 px,
// dicht in einer leicht gestreckten Wolke. Ein Teil davon RIESELT im Flug
// nach hinten unten ab (`streu`) — das ist die Spur, die vorher ein
// grosser Leuchtfleck vortaeuschte.
const SAND_FARBEN = ['#f3dfa6', '#e2c07a', '#c9995a', '#a8783f'];
const sandZufall = (start) => {
  let t = start >>> 0;
  return () => { t = (t * 1664525 + 1013904223) >>> 0; return t / 4294967296; };
};
const SAND_KOERNER = (() => {
  const r = sandZufall(1059);
  return Array.from({ length: ppFxN(90) }, (_, i) => {
    const winkel = i * 2.399 + r() * 0.5;               // goldener Winkel + Rauschen
    const radius = Math.sqrt(r()) * 20;                 // dichter Kern, lockerer Rand
    return {
      x: Math.cos(winkel) * radius * 1.25,
      y: Math.sin(winkel) * radius * 0.7,
      g: 1 + Math.round(r() * 20) / 10,                 // 1.0 … 3.0 px
      farbe: SAND_FARBEN[Math.floor(r() * SAND_FARBEN.length)],
      verzug: Math.round(r() * 300),
      streu: i % 3 === 0,
      dx: -(8 + r() * 22), dy: 6 + r() * 18,
    };
  });
})();

/**
 * ★★ v1149 — „Trunk Sand" als SANDSTRAHL (Al 17.9.: „ein richtiger
 * Strahl aus Sand, der auf das Ziel geschossen wird — vgl. Sandwirbel
 * aus Pokemon").
 *
 * Kein einzelnes Projektil mehr, das eine Wolke traegt, sondern ein
 * STROM: ueber ~70 % der Laufzeit werden laufend Koerner vom Werfer
 * abgeschossen, jedes fliegt einzeln zum Ziel. An der Duese eng, am Ziel
 * gefaechert — ein Kegel. Dazu Schlieren (lange, duenne Striche entlang
 * der Flugrichtung) fuer die Geschwindigkeit und ein blasser Staubkanal
 * zwischen beiden Punkten.
 *
 * Gerendert statt des normalen Projektil-Wrappers, wenn
 * `projectileShape === 'sandStream'`; Start, Ziel und Dauer kommen aus
 * dem gewoehnlichen `play_projectile_animation`.
 */
/**
 * ★★ v1175 — „Memory Blast": BLAST AUS NEGATIVER ENERGIE vom Wirker zum
 * Ziel (Al 17.9.). Wie `SandStrahl` (v1149) eine eigene Projektilform
 * (`projectileShape: 'darkBlast'`), nur eben ein einzelner, dicker
 * Energiestoss statt eines Stroms: Kopf mit Wirbelring, gestreckter
 * Schweif, Ranken aus Dunkelenergie und Funken. `p.power` (0…1, aus der
 * Zahl der Karten in der gegnerischen Ablage) skaliert Dicke, Laenge,
 * Rankenzahl und Leuchtkraft — mehr Schaden, groesserer Blast.
 */
function DunkelBlastStrahl({ p }) {
  const dx = p.tgtX - p.srcX, dy = p.tgtY - p.srcY;
  const laenge = Math.max(1, Math.hypot(dx, dy));
  const winkel = Math.atan2(dy, dx) * 180 / Math.PI;
  const wucht = Math.max(0, Math.min(1, typeof p.power === 'number' ? p.power : 0.5));
  const dauer = p.dur || 900;
  const kopf = 26 + wucht * 62;                     // Durchmesser
  const schweif = kopf * (2.2 + wucht * 2.6);
  const ranken = useMemo(() => {
    const r = [];
    const anzahl = Math.round(6 + wucht * 14);
    for (let i = 0; i < anzahl; i++) {
      r.push({
        seite: i % 2 ? 1 : -1,
        ab: (i / anzahl) * 0.8 + 0.1,
        l: kopf * (0.5 + ((i * 37) % 60) / 100),
        b: 2 + ((i * 17) % 4),
        verzug: (i % 5) * 60,
      });
    }
    return r;
  }, [p.id]);
  const funken = useMemo(() => Array.from({ length: Math.round(8 + wucht * 18) }, (_, i) => ({
    ab: ((i * 29) % 90) / 100,
    quer: (((i * 53) % 100) / 100 - 0.5) * kopf * 1.6,
    g: 2 + ((i * 13) % 4),
    verzug: (i % 7) * 55,
  })), [p.id]);
  return (
    <div className="dunkel-blast" aria-hidden="true">
      <div className="db-flug" style={{
        left: p.srcX, top: p.srcY,
        '--ddx': dx + 'px', '--ddy': dy + 'px',
        animationDuration: dauer + 'ms',
      }}>
        <div className="db-koerper" style={{ transform: `rotate(${winkel}deg)` }}>
          <span className="db-schweif" style={{ width: schweif, height: kopf * 0.62 }} />
          <span className="db-kopf" style={{ width: kopf, height: kopf }} />
          <span className="db-wirbel" style={{ width: kopf * 1.5, height: kopf * 1.5 }} />
          {ranken.map((k, i) => (
            <span key={'dr' + i} className="db-ranke" style={{
              left: -k.ab * schweif, width: k.l, height: k.b,
              transform: `translateY(${k.seite * kopf * 0.42}px) rotate(${k.seite * 18}deg)`,
              animationDelay: k.verzug + 'ms',
            }} />
          ))}
          {funken.map((f, i) => (
            <span key={'df' + i} className="db-funke" style={{
              left: -f.ab * schweif, top: f.quer,
              width: f.g, height: f.g, animationDelay: f.verzug + 'ms',
            }} />
          ))}
        </div>
      </div>
      <div className="db-spur" style={{
        left: p.srcX, top: p.srcY, width: laenge,
        height: Math.max(4, kopf * 0.3),
        transform: `rotate(${winkel}deg)`,
        animationDuration: dauer + 300 + 'ms',
      }} />
    </div>
  );
}

function SandStrahl({ p }) {
  const dx = p.tgtX - p.srcX, dy = p.tgtY - p.srcY;
  const laenge = Math.max(1, Math.hypot(dx, dy));
  const ux = dx / laenge, uy = dy / laenge;       // Flugrichtung
  const nx = -uy, ny = ux;                         // Senkrechte
  const dauer = p.dur || 950;
  const strom = Math.round(dauer * 0.7);
  const teile = useMemo(() => {
    const r = sandZufall(Math.round(p.srcX * 7 + p.tgtY * 13));
    const gauss = () => (r() + r() + r()) / 3 - 0.5;   // Glocke um 0
    const koerner = Array.from({ length: ppFxN(280) }, () => {
      const start = gauss() * 10, ende = gauss() * 64;
      const flug = Math.round(240 + r() * 150);
      return {
        x: p.srcX + nx * start + ux * r() * 14, y: p.srcY + ny * start + uy * r() * 14,
        dx: dx + nx * (ende - start), dy: dy + ny * (ende - start),
        g: 1 + Math.round(r() * 25) / 10,
        farbe: SAND_FARBEN[Math.floor(r() * SAND_FARBEN.length)],
        verzug: Math.round(r() * strom), flug,
      };
    });
    const schlieren = Array.from({ length: ppFxN(34) }, () => {
      const start = gauss() * 8, ende = gauss() * 44;
      return {
        x: p.srcX + nx * start, y: p.srcY + ny * start,
        dx: dx + nx * (ende - start), dy: dy + ny * (ende - start),
        l: 8 + r() * 14, verzug: Math.round(r() * strom), flug: Math.round(200 + r() * 90),
      };
    });
    return { koerner, schlieren };
  }, [p.id]);
  const winkel = Math.atan2(dy, dx) * 180 / Math.PI;
  return (
    <div className="sand-strahl" aria-hidden="true">
      <div className="sand-strahl-kanal" style={{
        left: p.srcX, top: p.srcY, width: laenge, transform: `rotate(${winkel}deg)`,
        animation: `sandKanal ${dauer}ms ease-out forwards`,
      }} />
      {teile.schlieren.map((k, i) => (
        <i key={'sl' + i} className="sand-schliere" style={{
          left: k.x, top: k.y, width: k.l,
          '--sdx': k.dx + 'px', '--sdy': k.dy + 'px', '--sw': winkel + 'deg',
          animation: `sandStrahlFlug ${k.flug}ms linear ${k.verzug}ms forwards`,
        }} />
      ))}
      {teile.koerner.map((k, i) => (
        <i key={'sk' + i} className="sand-strahl-korn" style={{
          left: k.x, top: k.y, width: k.g, height: k.g, background: k.farbe,
          '--sdx': k.dx + 'px', '--sdy': k.dy + 'px', '--sw': '0deg',
          animation: `sandStrahlFlug ${k.flug}ms linear ${k.verzug}ms forwards`,
        }} />
      ))}
    </div>
  );
}


// Gathering Storm — dark-red storm clouds drifting across the
// battlefield with red lightning bolts arcing inside and between them.
// Renders while ANY Gathering Storm card is attached in either player's
// support zone (it's an Attachment Spell, not an Area, so we walk
// support zones rather than areaZones).
//
// The overlay is composed of three layers:
//   1. Faint blood-red sky tint over the board so the clouds read as
//      "ominous storm front" rather than just "purple smudges".
//   2. A pool of crimson cloud sprites animating horizontally across
//      the battlefield at varied heights / speeds. Each cloud is a
//      handful of stacked elliptical blurs in deep-red gradients.
//   3. Lightning bursts that fire on randomised intervals — each is an
//      SVG polyline with a couple of branching forks, drawn in bright
//      red with a hot-pink core stroke for the glow.
//
// The lightning timing is driven by a single lightweight effect that
// rotates which "bolt slot" is currently flashing, keeping the React
// state churn cheap regardless of how many bolts the user sees.
function GatheringStormOverlay() {
  // Heavy, fast-moving cloud cover. Bigger sprites, more of them,
  // shorter loop durations — the storm reads as gale-force wind
  // ripping clouds across the battlefield. The slight reverse-flow
  // current (~25% of clouds going against the prevailing wind) adds
  // chaos without breaking the "wind direction" feel.
  const clouds = useMemo(() => Array.from({ length: ppFxN(22) }, () => ({
    y:        -8 + Math.random() * 116,             // Wider vertical spread
    scale:    1.4 + Math.random() * 1.5,            // Much bigger (was 0.7–1.7)
    delay:    -Math.random() * 14,                  // Spread starts across the cycle
    dur:      8 + Math.random() * 7,                // Way faster (was 24–46s)
    opacity:  0.6 + Math.random() * 0.3,
    // Mostly forward, some against — strong prevailing wind with the
    // occasional updraft cross-current.
    reverse:  Math.random() < 0.25,
  })), []);

  // 6 lightning slots: each slot owns a randomised path; a rotating
  // index makes one slot "hot" at a time, restarting its CSS animation
  // by toggling a `key`. This keeps the lightning visually unpredictable
  // without re-mounting the whole overlay.
  const bolts = useMemo(() => Array.from({ length: ppFxN(6) }, () => {
    // Bolts typically jag from one cloud strata down to another (not
    // floor-to-ceiling). x1/x2 are within the central battlefield band;
    // y1/y2 keep the bolt within the cloud strata.
    const x1 = 12 + Math.random() * 76;
    const y1 = 8  + Math.random() * 30;
    const x2 = x1 + (-25 + Math.random() * 50);
    const y2 = 35 + Math.random() * 50;
    // 3-segment zig-zag with a random fork off the midpoint.
    const midX = (x1 + x2) / 2 + (-8 + Math.random() * 16);
    const midY = (y1 + y2) / 2 + (-5 + Math.random() * 10);
    const forkX = midX + (-12 + Math.random() * 24);
    const forkY = midY + (4 + Math.random() * 14);
    return {
      main: `M ${x1} ${y1} L ${midX} ${midY} L ${x2} ${y2}`,
      fork: `M ${midX} ${midY} L ${forkX} ${forkY}`,
      // Per-bolt jitter for variety — 0.45–0.85s flash duration.
      dur:  450 + Math.random() * 400,
    };
  }), []);
  const [activeBolt, setActiveBolt] = useState(-1);
  const [boltSerial, setBoltSerial] = useState(0); // re-key trigger
  useEffect(() => {
    let cancelled = false;
    const fire = () => {
      if (cancelled) return;
      const idx = Math.floor(Math.random() * bolts.length);
      setActiveBolt(idx);
      setBoltSerial(s => s + 1);
      // Per-strike audio cue — distant thunder. Volume kept very low
      // so a long Gathering Storm session doesn't overwhelm the rest
      // of the soundscape.
      if (window.playSFX) {
        window.playSFX('elem_lightning', { volume: 0.12, dedupe: 250, category: 'effect' });
      }
      // The selected bolt visually disappears after its CSS animation;
      // schedule the NEXT bolt 400–1100ms later to keep the strikes
      // feeling stochastic.
      const gap = 380 + Math.random() * 750;
      setTimeout(fire, gap);
    };
    const initial = setTimeout(fire, 250 + Math.random() * 600);
    return () => { cancelled = true; clearTimeout(initial); };
  }, [bolts.length]);

  return (
    <div className="gathering-storm-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      overflow: 'hidden',
    }}>
      {/* Layer 1: blood-red atmospheric tint. Soft radial so the
          centre of the battlefield feels "thicker" with storm. */}
      <div style={{
        position: 'absolute', inset: 0,
        background:
          'radial-gradient(ellipse at 50% 50%, rgba(80,8,12,0.32) 0%, rgba(50,4,8,0.22) 55%, rgba(20,2,4,0.18) 100%)',
        mixBlendMode: 'multiply',
      }} />
      {/* Layer 2: drifting crimson cloud sprites. The keyframe drives
          `left` from off-screen left (-25%) to off-screen right (125%)
          so each cloud actually traverses the entire battlefield —
          the previous percentage-based `transform: translate(...)`
          implementation only swept the cloud's own width and parked
          everything near the left edge. */}
      <div style={{ position: 'absolute', inset: 0 }}>
        {clouds.map((c, i) => (
          <div key={'gsc' + i} style={{
            position: 'absolute',
            top: c.y + '%',
            opacity: c.opacity,
            '--gscScale': c.scale,
            animation: `gatheringStormCloud${c.reverse ? 'Rev' : ''} ${c.dur}s linear ${c.delay}s infinite`,
            filter: 'drop-shadow(0 4px 18px rgba(120,12,16,0.5))',
          }}>
            {/* Stacked ellipses make a single cloud sprite. */}
            <div style={{
              position: 'absolute', left: -65, top: -18,
              width: 130, height: 36, borderRadius: '50%',
              background: 'radial-gradient(circle, rgba(105,12,18,0.92) 0%, rgba(75,8,14,0.7) 55%, rgba(30,2,6,0) 95%)',
              filter: 'blur(2px)',
            }} />
            <div style={{
              position: 'absolute', left: -32, top: -32,
              width: 78, height: 36, borderRadius: '50%',
              background: 'radial-gradient(circle, rgba(125,18,24,0.88) 0%, rgba(85,10,16,0.6) 60%, rgba(30,2,6,0) 95%)',
              filter: 'blur(2px)',
            }} />
            <div style={{
              position: 'absolute', left: 5, top: -26,
              width: 65, height: 30, borderRadius: '50%',
              background: 'radial-gradient(circle, rgba(95,10,16,0.85) 0%, rgba(60,6,12,0.55) 60%, rgba(20,1,4,0) 95%)',
              filter: 'blur(2px)',
            }} />
            {/* A crimson "underbelly" smear hints at active rain inside
                the cloud. */}
            <div style={{
              position: 'absolute', left: -45, top: 4,
              width: 95, height: 14, borderRadius: '50%',
              background: 'radial-gradient(ellipse, rgba(60,4,8,0.7) 0%, rgba(30,2,4,0) 80%)',
              filter: 'blur(4px)',
            }} />
          </div>
        ))}
      </div>
      {/* Layer 3: lightning bolts. We render an SVG with all bolts laid
          out, but only the `activeBolt` is visible at any moment via
          opacity. Re-keying the visible <g> on `boltSerial` restarts
          the strike-flash animation. */}
      <svg
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}
      >
        <defs>
          <filter id="gatheringStormGlow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="1.2" />
          </filter>
        </defs>
        {bolts.map((b, i) => activeBolt === i ? (
          <g
            key={'gsb' + i + '-' + boltSerial}
            style={{
              animation: `gatheringStormBolt ${b.dur}ms ease-out forwards`,
            }}
          >
            {/* Outer red glow */}
            <path d={b.main} stroke="#ff1830" strokeWidth="1.4"
                  fill="none" strokeLinecap="round"
                  filter="url(#gatheringStormGlow)" opacity="0.9" />
            <path d={b.fork} stroke="#ff1830" strokeWidth="1.0"
                  fill="none" strokeLinecap="round"
                  filter="url(#gatheringStormGlow)" opacity="0.85" />
            {/* Inner bright core */}
            <path d={b.main} stroke="#ffd0d8" strokeWidth="0.55"
                  fill="none" strokeLinecap="round" />
            <path d={b.fork} stroke="#ffd0d8" strokeWidth="0.4"
                  fill="none" strokeLinecap="round" />
          </g>
        ) : null)}
      </svg>
      <style>{`
        @keyframes gatheringStormCloud {
          0%   { left: -25%;  transform: translateY(-50%) scale(var(--gscScale, 1)); }
          100% { left: 125%;  transform: translateY(-50%) scale(var(--gscScale, 1)); }
        }
        @keyframes gatheringStormCloudRev {
          0%   { left: 125%;  transform: translateY(-50%) scale(var(--gscScale, 1)); }
          100% { left: -25%;  transform: translateY(-50%) scale(var(--gscScale, 1)); }
        }
        @keyframes gatheringStormBolt {
          0%   { opacity: 0; }
          12%  { opacity: 1; }
          25%  { opacity: 0.7; }
          40%  { opacity: 1; }
          100% { opacity: 0; }
        }
      `}</style>
    </div>
  );
}


// Tempeste rain — permanent rain background painted while at least one
// Prophecy of Tempeste is attached. Stormy slate-blue drops with a brief
// lightning flicker every few seconds. Lighter on the atmospheric tint
// than Acid Rain since Tempeste isn't supposed to be a hostile area
// effect — it's the host's chosen burden, ambient and ominous.
function TempesteRainOverlay() {
  const drops = useMemo(() => Array.from({ length: ppFxN(130) }, () => ({
    left: Math.random() * 100,
    delay: -Math.random() * 1.4,
    dur: 0.45 + Math.random() * 0.55,
    w: 1 + Math.random() * 1.4,
    h: 16 + Math.random() * 26,
    opacity: 0.4 + Math.random() * 0.5,
  })), []);
  const splashes = useMemo(() => Array.from({ length: ppFxN(18) }, () => ({
    left: Math.random() * 100,
    top: 60 + Math.random() * 36,
    delay: -Math.random() * 1.4,
    dur: 0.5 + Math.random() * 0.4,
    size: 5 + Math.random() * 9,
  })), []);
  // Sporadic lightning flickers behind the rain — re-keyed via interval.
  const [flickerSerial, setFlickerSerial] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const fire = () => {
      if (cancelled) return;
      setFlickerSerial(s => s + 1);
      setTimeout(fire, 3500 + Math.random() * 4500);
    };
    const initial = setTimeout(fire, 1200 + Math.random() * 2000);
    return () => { cancelled = true; clearTimeout(initial); };
  }, []);
  return (
    <div className="tempeste-rain-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 178,
      overflow: 'hidden',
      background: 'linear-gradient(180deg, rgba(20,30,55,0.18) 0%, rgba(10,20,40,0.30) 100%)',
    }}>
      {/* Background lightning flicker — full-overlay desaturated flash. */}
      <div key={'tflk' + flickerSerial} style={{
        position: 'absolute', inset: 0,
        background: 'radial-gradient(ellipse at 50% 30%, rgba(220,230,255,0.45) 0%, rgba(160,180,220,0.18) 35%, transparent 70%)',
        opacity: 0,
        animation: 'tempesteFlicker 700ms ease-out forwards',
      }} />
      {drops.map((d, i) => (
        <span key={'td'+i} style={{
          position: 'absolute',
          left: d.left + '%', top: '-10%',
          width: d.w + 'px', height: d.h + 'px',
          background: 'linear-gradient(180deg, rgba(80,110,160,0) 0%, rgba(120,150,200,' + d.opacity + ') 30%, rgba(170,200,235,' + d.opacity + ') 70%, rgba(220,235,255,' + d.opacity + ') 100%)',
          boxShadow: '0 0 3px rgba(150,180,220,' + (d.opacity * 0.5) + ')',
          borderRadius: d.w + 'px',
          animation: 'tempesteRainDrop ' + d.dur + 's linear ' + d.delay + 's infinite',
        }} />
      ))}
      {splashes.map((s, i) => (
        <span key={'ts'+i} style={{
          position: 'absolute',
          left: s.left + '%', top: s.top + '%',
          width: s.size + 'px', height: (s.size * 0.45) + 'px',
          border: '1.5px solid rgba(190,215,245,0.7)',
          borderTop: 'transparent',
          borderRadius: '50%',
          animation: 'tempesteRainSplash ' + s.dur + 's ease-out ' + s.delay + 's infinite',
          opacity: 0,
        }} />
      ))}
      <style>{`
        @keyframes tempesteRainDrop {
          0%   { transform: translateY(0) translateX(0); }
          100% { transform: translateY(115vh) translateX(-6px); }
        }
        @keyframes tempesteRainSplash {
          0%   { opacity: 0; transform: scale(0.3); }
          35%  { opacity: 1; transform: scale(1); }
          100% { opacity: 0; transform: scale(1.6); }
        }
        @keyframes tempesteFlicker {
          0%   { opacity: 0; }
          15%  { opacity: 0.85; }
          30%  { opacity: 0.4;  }
          45%  { opacity: 0.95; }
          100% { opacity: 0; }
        }
      `}</style>
    </div>
  );
}


/**
 * ═══ AREA-STAPEL (v1050, Als Vorgabe 14.9.) ═══════════════════════════
 *
 * Seit „Spatial Crevice" kann eine Seite mehrere Areas gleichzeitig
 * kontrollieren. Die Standard-Stapel-Darstellung (nur die oberste Karte
 * plus Stueckzahl) verschweigt die anderen — hier liegen deshalb ALLE
 * offen, in Y versetzt.
 *
 * ★ REIHENFOLGE (Als Ruling 14.9.): die NEUESTE Area liegt vorne und
 * unten — dieselbe Richtung wie der Ability-Stapel. DOM-Reihenfolge
 * entscheidet, kein z-index: der letzte Eintrag wird zuletzt gezeichnet
 * und deckt damit die aelteren, die nur mit ihrem oberen Streifen
 * herausschauen.
 *
 * ★ TOOLTIP UND KLICK GEHOEREN DER KARTE, NICHT DER ZONE. Beides faellt
 * durch normales Hit-Testing von allein richtig aus: unter dem Cursor
 * gewinnt, was dort ganz oben liegt. Eine teilverdeckte Area reagiert
 * also nur auf ihrem freiliegenden Streifen — und genau deshalb ist der
 * Versatz hier ein Vielfaches der 5 px des Ability-Stapels
 * (`--area-stack-offset`): man muss eine untere Area gezielt treffen
 * koennen, um sie zu aktivieren.
 *
 * `stopPropagation` auf dem Karten-Klick haelt die Aktivierung von der
 * Zielwahl der Zone getrennt — die Zone bleibt fuer Potion-Ziele
 * zustaendig, die Karte fuer ihre eigene Aktivierung.
 */
function AreaStack({ cards, entries, onActivate, effectLocked, charge, targeting }) {
  return (
    <div className="board-area-stack">
      {cards.map((name, i) => {
        const eintrag = (entries || []).find(e => e.areaName === name);
        const aktivierbar = !effectLocked && !!eintrag?.canActivate;
        // ★ ZIELWAHL JE KARTE (v1054, Als Befund 14.9.: „The Yeeting
        // trifft immer die oberste Area statt der gewaehlten").
        // Die Ziel-ID traegt den Stapelplatz und entsteht hier aus
        // demselben Index, den die Engine benutzt — `gs.areaZones` ist
        // auf beiden Seiten dieselbe Namensliste.
        const zielId = targeting ? `area-${targeting.owner}-${i}` : null;
        const waehlbar = !!zielId && !!targeting?.validIds?.has(zielId);
        const gewaehlt = !!zielId && !!targeting?.selectedIds?.has(zielId);
        const klick = waehlbar
          ? (e) => { e.stopPropagation(); targeting.onToggle(zielId); }
          : (aktivierbar ? (e) => { e.stopPropagation(); onActivate(name); } : undefined);
        return (
          <div key={name + ':' + i}
            className={'board-area-stack-card'
              + (aktivierbar && !waehlbar ? ' area-stack-activatable' : '')
              + (waehlbar ? ' potion-target-valid' : '')
              + (gewaehlt ? ' potion-target-selected' : '')}
            style={{ top: `calc(var(--area-stack-offset) * ${i})`,
              cursor: (waehlbar || aktivierbar) ? 'pointer' : undefined }}
            data-area-stack-idx={i}
            onClick={klick}>
            <BoardCard cardName={name} />
          </div>
        );
      })}
      {/* Ladungen einer „up to X times per turn"-Area (The Bonegrinder).
          ★ Sass frueher im `children`-Slot von BoardZone — und der wird
          NUR gerendert, solange die Zone LEER ist. Das Abzeichen war
          damit nie zu sehen, weil es eine Area voraussetzt. Jetzt haengt
          es am Stapel selbst. */}
      {charge ? (
        <div className={'zone-charge-badge' + (charge.remaining === 0 ? ' zone-charge-empty' : '')}
          onMouseEnter={e => showGameTooltip(e, `Noch ${charge.remaining} von ${charge.max} Einsätzen in dieser Runde.`)}
          onMouseLeave={hideGameTooltip}
        >{charge.remaining}</div>
      ) : null}
    </div>
  );
}


// ── Thebinxan War Counselor ─────────────────────────────────────────
//  Der GEGNER sagt einen Kartentyp an; der Spieler sieht diese Abfrage
//  nicht und braucht die Ansage deshalb gross in der Bildmitte, in der
//  Farbe des angesagten Typs. Faehrt heran, haelt kurz, blendet aus.
const TypeDeclarationOverlay = React.memo(function TypeDeclarationOverlay({ decl, onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 2100);
    return () => clearTimeout(t);
  }, [decl.id, onDone]);
  return (
    <div style={{
      position: 'fixed', inset: 0, pointerEvents: 'none',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      zIndex: 21000,
    }}>
      <div style={{
        textAlign: 'center',
        animation: 'tdEnter 2100ms cubic-bezier(.2,1.3,.4,1) forwards',
      }}>
        <div style={{
          fontSize: 15, letterSpacing: '3px', textTransform: 'uppercase',
          color: '#d8d8e4', textShadow: '0 2px 6px rgba(0,0,0,.9)', marginBottom: 6,
        }}>
          {decl.declaredBy} declares
        </div>
        <div style={{
          fontFamily: '"Orbitron", "Rajdhani", sans-serif',
          fontSize: 54, fontWeight: 900, letterSpacing: '2px',
          color: decl.color,
          textShadow: `0 0 18px ${decl.color}, 0 0 42px ${decl.color}88,`
            + ' 3px 3px 0 #000, -3px 3px 0 #000, 3px -3px 0 #000, -3px -3px 0 #000',
          padding: '10px 34px',
          border: `3px solid ${decl.color}`,
          borderRadius: 10,
          background: 'rgba(8,8,16,.82)',
          boxShadow: `0 0 30px ${decl.color}66, inset 0 0 24px ${decl.color}22`,
        }}>
          {decl.label}
        </div>
      </div>
      <style>{`
        @keyframes tdEnter {
          0%   { opacity: 0; transform: scale(.55); }
          14%  { opacity: 1; transform: scale(1.06); }
          22%  { transform: scale(1); }
          80%  { opacity: 1; transform: scale(1); }
          100% { opacity: 0; transform: scale(1.12); }
        }
      `}</style>
    </div>
  );
});


// Burned overlay — persistent small flame particles on the hero
function BurnedOverlay({ ticking }) {
  const flames = useMemo(() => Array.from({ length: ppFxN(10) }, () => ({
    x: 8 + Math.random() * 84,
    y: 15 + Math.random() * 70,
    size: 8 + Math.random() * 6,
    delay: Math.random() * 2,
    dur: 0.6 + Math.random() * 0.6,
  })), []);
  return (
    <div className={'status-burned-overlay' + (ticking ? ' burn-ticking' : '')}>
      {flames.map((f, i) => (
        <span key={i} className="burned-particle" style={{
          left: f.x + '%', top: f.y + '%', fontSize: f.size,
          animationDelay: f.delay + 's', animationDuration: f.dur + 's',
        }}>🔥</span>
      ))}
    </div>
  );
}

