// ═══ GENERIC GAME TOOLTIP ═══
// Global tooltip system — renders at top level, escapes overflow:hidden.
// Game tooltip, StatusBadges, BuffColumn — use shared versions from app-shared.jsx
const showGameTooltip = window.showGameTooltip;
const hideGameTooltip = window.hideGameTooltip;
const GameTooltip = window.GameTooltip;
const StatusBadges = window.StatusBadges;
const BuffColumn = window.BuffColumn;
// HeroArtCrop lives in app-screens.jsx (the Singleplayer opponent-picker
// uses it) — borrowed here to render CPU / avatar-less player portraits
// next to the hand in-game using the same cropped hero art.
const HeroArtCrop = window.HeroArtCrop;

// Status badges — small icons showing active negative statuses at a glance
// StatusBadges and BuffColumn — now defined in app-shared.jsx

// Wind swirl — gentle wind particles spiraling around target
function WindEffect({ x, y }) {
  const particles = useMemo(() => Array.from({ length: ppFxN(14) }, (_, i) => {
    const angle = (i / 14) * Math.PI * 2;
    const radius = 20 + Math.random() * 30;
    return {
      startAngle: angle,
      radius,
      size: 6 + Math.random() * 8,
      delay: i * 40 + Math.random() * 60,
      dur: 500 + Math.random() * 300,
      char: ['~','≈','∿','⌇','·'][Math.floor(Math.random() * 5)],
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-wind-flash" />
      {particles.map((p, i) => (
        <div key={'wp'+i} className="anim-wind-particle" style={{
          '--startAngle': p.startAngle + 'rad', '--radius': p.radius + 'px', '--size': p.size + 'px',
          animationDelay: p.delay + 'ms', animationDuration: p.dur + 'ms',
        }}>{p.char}</div>
      ))}
    </div>
  );
}

// Shadow summon effect — dark tendrils rising from below
function ShadowSummonEffect({ x, y }) {
  const tendrils = useMemo(() => Array.from({ length: ppFxN(16) }, () => {
    const xOff = -30 + Math.random() * 60;
    return {
      xOff,
      size: 6 + Math.random() * 10,
      delay: Math.random() * 200,
      dur: 400 + Math.random() * 400,
      char: ['▓','░','▒','◆','●'][Math.floor(Math.random() * 5)],
    };
  }), []);
  const wisps = useMemo(() => Array.from({ length: ppFxN(10) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 10 + Math.random() * 25;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 2 + Math.random() * 4,
      color: ['#6633aa','#442288','#553399','#221144','#7744bb'][Math.floor(Math.random() * 5)],
      delay: 300 + Math.random() * 200,
      dur: 300 + Math.random() * 300,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-shadow-flash" />
      {tendrils.map((t, i) => (
        <div key={'st'+i} className="anim-shadow-tendril" style={{
          '--xOff': t.xOff + 'px', '--size': t.size + 'px',
          animationDelay: t.delay + 'ms', animationDuration: t.dur + 'ms',
        }}>{t.char}</div>
      ))}
      {wisps.map((w, i) => (
        <div key={'sw'+i} className="anim-explosion-particle" style={{
          '--dx': w.dx + 'px', '--dy': w.dy + 'px', '--size': w.size + 'px',
          '--color': w.color, animationDelay: w.delay + 'ms', animationDuration: w.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Gold sparkle — particles burst from the gold counter
// ── DOOM COUNTER (v1421, Als Vorgabe 25.9.) ───────────────────────────
// Ein Doom Counter kommt auf die Doom Clock: ueber der Karte in der
// Area-Zone springt ein Pixel-Totenschaedel mit rot gluehenden Augen
// hoch, daneben ein „+1", beides steigt und verblasst. Licht von oben
// rechts (Als Regel). Klang: `doom_tick` ueber ZONE_ANIM_SFX.
const DOOM_SCHAEDEL = [
  '.#######.',
  '#########',
  '##oo#oo##',
  '##oo#oo##',
  '#########',
  '.###.###.',
  '..#####..',
  '..#.#.#..',
];
function DoomCounterEffect({ x, y, h }) {
  const px = 5;
  const rects = [];
  DOOM_SCHAEDEL.forEach((row, yy) => [...row].forEach((ch, xx) => {
    if (ch === '.') return;
    // helle Seite rechts oben, Schatten links unten
    const c = ch === 'o' ? '#ff2a22' : (xx >= 6 || yy <= 1 ? '#f4ecde' : (xx <= 1 || yy >= 6 ? '#b8ab9c' : '#e2d7c6'));
    rects.push(<rect key={xx + '-' + yy} x={xx} y={yy} width="1" height="1" fill={c} />);
  }));
  const oben = y - (h || 60) / 2 - 8;
  return (
    <div className="anim-doom-counter" style={{ position: 'fixed', left: x, top: oben, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-doom-counter-inhalt">
        <svg width={9 * px} height={8 * px} viewBox="0 0 9 8" shapeRendering="crispEdges"
          style={{ filter: 'drop-shadow(0 0 1px #2a0404) drop-shadow(0 0 1px #2a0404) drop-shadow(0 0 6px rgba(255,30,20,.6))' }}>
          {rects}
        </svg>
        <span className="anim-doom-counter-plus">+1</span>
      </div>
    </div>
  );
}

function GoldSparkleEffect({ x, y }) {
  const sparkles = useMemo(() => Array.from({ length: ppFxN(12) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 12 + Math.random() * 25;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 3 + Math.random() * 5,
      color: ['#ffd700','#ffcc00','#ffee55','#fff','#ffaa00'][Math.floor(Math.random() * 5)],
      delay: Math.random() * 150,
      dur: 400 + Math.random() * 400,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-gold-flash" />
      {sparkles.map((s, i) => (
        <div key={'gs'+i} className="anim-explosion-particle" style={{
          '--dx': s.dx + 'px', '--dy': s.dy + 'px', '--size': s.size + 'px',
          '--color': s.color, animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Spider summon flourish — fires when a Spider Creature is summoned
// from hand via the Spider archetype's surprise-cost path (Box /
// Brain / Crimson Skull / Diamond). Renders a curtain of cobweb
// strands descending from above the destination, four spider corner
// webs flashing in, and a handful of tiny spiders that pop out and
// crawl away on short looping paths. Pure SVG + CSS keyframes; no
// per-frame JS. Anchored to the Hero column via the standard
// `play_zone_animation` plumbing.
function SpiderSummonEffect({ x, y }) {
  // Eight spiders bursting outward in a fan.
  const spiders = useMemo(() => Array.from({ length: ppFxN(8) }, (_, i) => {
    const angle = (i / 8) * Math.PI * 2 + (Math.random() - 0.5) * 0.4;
    const dist = 36 + Math.random() * 28;
    return {
      dx: Math.cos(angle) * dist, dy: Math.sin(angle) * dist,
      size: 9 + Math.random() * 4,
      delay: Math.random() * 220,
      dur: 900 + Math.random() * 300,
      rotStart: -25 + Math.random() * 50,
      rotEnd: -45 + Math.random() * 90,
    };
  }), []);
  // Vertical silk strands draping from above the slot.
  const strands = useMemo(() => Array.from({ length: ppFxN(7) }, (_, i) => ({
    xOff: -36 + i * 12 + (Math.random() - 0.5) * 4,
    len: 50 + Math.random() * 30,
    delay: Math.random() * 200,
    dur: 700 + Math.random() * 250,
  })), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {/* Central web burst — concentric arcs flashing outward */}
      <svg viewBox="-60 -60 120 120" width={140} height={140} style={{
        position: 'absolute', transform: 'translate(-50%, -50%)',
        animation: 'spiderSummonWebBurst 1.1s ease-out forwards',
      }}>
        {/* Radial spokes */}
        {Array.from({ length: ppFxN(12) }).map((_, i) => {
          const a = (i / 12) * Math.PI * 2;
          return (
            <line key={'sp' + i}
              x1={0} y1={0}
              x2={Math.cos(a) * 56} y2={Math.sin(a) * 56}
              stroke="rgba(240,240,255,0.85)"
              strokeWidth={0.8}
              strokeLinecap="round"
            />
          );
        })}
        {/* Concentric arcs */}
        {[18, 30, 42, 54].map((r, i) => (
          <circle key={'arc' + i}
            cx={0} cy={0} r={r}
            fill="none"
            stroke="rgba(220,225,235,0.7)"
            strokeWidth={0.6}
            strokeDasharray="3 5"
          />
        ))}
      </svg>
      {/* Silk strands hanging from above */}
      {strands.map((s, i) => (
        <div key={'st' + i} style={{
          position: 'absolute',
          left: s.xOff, top: -70,
          width: 1.4, height: s.len,
          background: 'linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(240,240,255,0.7) 30%, rgba(240,240,255,0.85) 100%)',
          transformOrigin: 'top center',
          animation: `spiderSummonStrand ${s.dur}ms ease-out ${s.delay}ms forwards`,
          filter: 'drop-shadow(0 0 2px rgba(180,200,255,0.5))',
        }} />
      ))}
      {/* Burst spiders crawling outward */}
      {spiders.map((s, i) => (
        <div key={'sps' + i} style={{
          position: 'absolute', left: 0, top: 0,
          width: 0, height: 0,
          '--dx': s.dx + 'px', '--dy': s.dy + 'px',
          '--rotStart': s.rotStart + 'deg',
          '--rotEnd': s.rotEnd + 'deg',
          animation: `spiderSummonCrawl ${s.dur}ms ease-out ${s.delay}ms forwards`,
        }}>
          <svg viewBox="-20 -20 40 40" width={s.size * 2} height={s.size * 2}
            style={{
              position: 'absolute', left: 0, top: 0,
              transform: 'translate(-50%, -50%)',
              filter: 'drop-shadow(0 1px 1px rgba(0,0,0,0.5))',
            }}>
            {[-50, -25, 25, 50].map((angle, li) => {
              const a = (angle * Math.PI) / 180;
              const x1 = Math.cos(a) * 4, y1 = Math.sin(a) * 4;
              const x2 = Math.cos(a) * 14, y2 = Math.sin(a) * 14;
              const kneeAngle = a - 0.35;
              const kx = Math.cos(kneeAngle) * 9, ky = Math.sin(kneeAngle) * 9;
              return (
                <g key={'leg' + li}>
                  <polyline points={`${-x1},${y1} ${-kx},${ky} ${-x2},${y2}`}
                    fill="none" stroke="rgba(20,15,25,0.95)" strokeWidth={1.4} strokeLinecap="round" />
                  <polyline points={`${x1},${y1} ${kx},${ky} ${x2},${y2}`}
                    fill="none" stroke="rgba(20,15,25,0.95)" strokeWidth={1.4} strokeLinecap="round" />
                </g>
              );
            })}
            <ellipse cx={0} cy={0} rx={5.5} ry={4}
              fill="rgba(20,15,25,1)" stroke="rgba(45,30,50,1)" strokeWidth={0.6} />
            <circle cx={-1.6} cy={-1.2} r={0.7} fill="rgba(220,60,60,0.95)" />
            <circle cx={1.6} cy={-1.2} r={0.7} fill="rgba(220,60,60,0.95)" />
          </svg>
        </div>
      ))}
      <style>{`
        @keyframes spiderSummonWebBurst {
          0%   { opacity: 0; transform: translate(-50%, -50%) scale(0.3) rotate(0deg); }
          40%  { opacity: 1; transform: translate(-50%, -50%) scale(1.1) rotate(35deg); }
          100% { opacity: 0; transform: translate(-50%, -50%) scale(1.5) rotate(70deg); }
        }
        @keyframes spiderSummonStrand {
          0%   { opacity: 0; transform: scaleY(0); }
          40%  { opacity: 1; transform: scaleY(1); }
          100% { opacity: 0; transform: scaleY(1); }
        }
        @keyframes spiderSummonCrawl {
          0%   { transform: translate(0, 0) rotate(var(--rotStart)); opacity: 0; }
          25%  { opacity: 1; }
          100% { transform: translate(var(--dx), var(--dy)) rotate(var(--rotEnd)); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

