// Cosmic Summon — a black-and-purple portal tears open in the summon
// slot: void expands from the centre, star-sparkles converge inward
// from the rim, a lilac core flashes white, then everything collapses
// back to let the freshly-placed creature render. Pure dark-theme, no
// fire/ice colour families so it reads as "pulled from the depths of
// space" rather than any existing elemental strike.
function CosmicSummonEffect({ x, y }) {
  const sparkles = useMemo(() => Array.from({ length: ppFxN(18) }, () => {
    const angle = Math.random() * Math.PI * 2;
    // Start somewhere between 70–130px from centre; each sparkle
    // converges all the way to the middle at peak.
    const startDist = 70 + Math.random() * 60;
    return {
      startX: Math.cos(angle) * startDist,
      startY: Math.sin(angle) * startDist,
      size: 4 + Math.random() * 6,
      delay: Math.random() * 220,
      dur: 420 + Math.random() * 260,
    };
  }), []);
  const dust = useMemo(() => Array.from({ length: ppFxN(12) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 20 + Math.random() * 50;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 3 + Math.random() * 5,
      color: ['#b488ff','#8a4bff','#d0a8ff','#ffffff','#6a2dcf'][Math.floor(Math.random() * 5)],
      delay: 350 + Math.random() * 150,
      dur: 400 + Math.random() * 300,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {/* Void portal — black core with purple nebula halo. Grows then
          collapses. */}
      <div className="anim-cosmic-void" />
      {/* Ring flash — a quick purple/white halo at peak expansion. */}
      <div className="anim-cosmic-ring" />
      {/* Converging star sparkles: each starts offset, shrinks to centre. */}
      {sparkles.map((s, i) => (
        <div key={'cs' + i} className="anim-cosmic-star" style={{
          '--cstartX': s.startX + 'px', '--cstartY': s.startY + 'px',
          '--csize': s.size + 'px',
          animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
      {/* Outward dust burst at the peak — uses the shared explosion
          particle keyframes (CSS var-driven). */}
      {dust.map((d, i) => (
        <div key={'cd' + i} className="anim-explosion-particle" style={{
          '--dx': d.dx + 'px', '--dy': d.dy + 'px', '--size': d.size + 'px',
          '--color': d.color,
          animationDelay: d.delay + 'ms', animationDuration: d.dur + 'ms',
        }} />
      ))}
      <style>{`
        @keyframes cosmic-void-pulse {
          0%   { opacity: 0;   transform: translate(-50%, -50%) scale(0.15); }
          35%  { opacity: 0.95; transform: translate(-50%, -50%) scale(1.0); }
          65%  { opacity: 0.85; transform: translate(-50%, -50%) scale(1.15); }
          100% { opacity: 0;   transform: translate(-50%, -50%) scale(0.4); }
        }
        @keyframes cosmic-ring-expand {
          0%   { opacity: 0;   transform: translate(-50%, -50%) scale(0.3); }
          30%  { opacity: 0.9; transform: translate(-50%, -50%) scale(0.95); }
          60%  { opacity: 0.5; transform: translate(-50%, -50%) scale(1.35); }
          100% { opacity: 0;   transform: translate(-50%, -50%) scale(1.75); }
        }
        @keyframes cosmic-star-converge {
          0%   { opacity: 0; transform: translate(calc(-50% + var(--cstartX)), calc(-50% + var(--cstartY))) scale(0.6); }
          25%  { opacity: 1; }
          100% { opacity: 0; transform: translate(-50%, -50%) scale(0.15); }
        }
        .anim-cosmic-void {
          position: absolute; left: 0; top: 0;
          width: 140px; height: 140px;
          border-radius: 50%;
          background:
            radial-gradient(circle at 50% 50%,
              #000 0%,
              rgba(40, 8, 80, 0.95) 30%,
              rgba(120, 40, 220, 0.55) 60%,
              rgba(80, 24, 180, 0.0) 100%);
          box-shadow:
            0 0 40px rgba(140, 60, 255, 0.75),
            inset 0 0 30px rgba(20, 0, 50, 0.9);
          transform: translate(-50%, -50%) scale(0.1);
          animation: cosmic-void-pulse 900ms ease-out forwards;
          filter: blur(0.5px);
        }
        .anim-cosmic-ring {
          position: absolute; left: 0; top: 0;
          width: 100px; height: 100px;
          border-radius: 50%;
          border: 3px solid rgba(220, 180, 255, 0.9);
          box-shadow:
            0 0 20px rgba(180, 100, 255, 0.9),
            inset 0 0 14px rgba(255, 255, 255, 0.65);
          transform: translate(-50%, -50%) scale(0.3);
          animation: cosmic-ring-expand 700ms ease-out forwards;
          animation-delay: 120ms;
        }
        .anim-cosmic-star {
          position: absolute; left: 0; top: 0;
          width: var(--csize); height: var(--csize);
          border-radius: 50%;
          background: radial-gradient(circle, #fff 0%, rgba(220, 200, 255, 0.95) 45%, rgba(180, 140, 255, 0) 100%);
          box-shadow:
            0 0 10px rgba(255, 255, 255, 0.95),
            0 0 20px rgba(180, 120, 255, 0.75);
          transform: translate(calc(-50% + var(--cstartX)), calc(-50% + var(--cstartY))) scale(0.6);
          animation: cosmic-star-converge ease-in forwards;
        }
      `}</style>
    </div>
  );
}

// ═══════════════════════════════════════════
//  BOMBLEBEE ARCHETYPE ANIMATIONS
//  Seven explosion variants — each Bomblebee
//  card and Burning Fuse / Bomblebee Cluster
//  get their own visual identity. Inline styles
//  + scoped <style> tags so no new global CSS.
// ═══════════════════════════════════════════

// 1. bomblebee_blast — Bomblebee's single-target 150 dmg.
//    Sharp single burst; yellow/black wasp-stripe palette;
//    tight cluster of shrapnel with a bright central flash.
function BomblebeeBlastEffect({ x, y }) {
  const particles = useMemo(() => Array.from({ length: ppFxN(26) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 30 + Math.random() * 60;
    return {
      dx: Math.cos(angle) * speed,
      dy: Math.sin(angle) * speed,
      size: 3 + Math.random() * 7,
      color: ['#ffcc00', '#ffaa00', '#ff8800', '#222', '#000', '#fff8aa'][Math.floor(Math.random() * 6)],
      delay: Math.random() * 60,
      dur: 380 + Math.random() * 320,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div style={{
        position: 'absolute', width: 90, height: 90, left: -45, top: -45,
        borderRadius: '50%',
        background: 'radial-gradient(circle, rgba(255,240,160,0.95) 0%, rgba(255,180,0,0.6) 35%, rgba(120,60,0,0.4) 70%, transparent 100%)',
        animation: 'bb-blast-flash 480ms ease-out forwards',
      }} />
      {particles.map((p, i) => (
        <div key={i} style={{
          position: 'absolute',
          left: -p.size / 2 + 'px', top: -p.size / 2 + 'px',
          width: p.size + 'px', height: p.size + 'px',
          borderRadius: '50%',
          background: p.color,
          boxShadow: `0 0 5px ${p.color}`,
          opacity: 0,
          animation: `bb-blast-particle ${p.dur}ms ease-out ${p.delay}ms forwards`,
          '--bdx': p.dx + 'px', '--bdy': p.dy + 'px',
        }} />
      ))}
      <style>{`
        @keyframes bb-blast-flash {
          0%   { transform: scale(0.25); opacity: 1; }
          40%  { transform: scale(1.7);  opacity: 0.9; }
          100% { transform: scale(2.2);  opacity: 0; }
        }
        @keyframes bb-blast-particle {
          0%   { transform: translate(0, 0) scale(1.3); opacity: 1; }
          22%  { opacity: 1; }
          100% { transform: translate(var(--bdx), var(--bdy)) scale(0); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

// 2. bomblebee_carpet — Carpet Bomblebee's AOE 80 to all opp Heroes.
//    Cascading row of small bursts walking horizontally; smoky orange.
//    Each hero zone receives its own animation, but the visual reads
//    as a strafing run because of the staggered start.
function BomblebeeCarpetEffect({ x, y, w, h }) {
  const cw = w || 110;
  const bursts = useMemo(() => Array.from({ length: ppFxN(7) }, (_, i) => ({
    offsetX: -cw * 0.45 + (i / 6) * cw * 0.9 + (Math.random() - 0.5) * 8,
    offsetY: -20 + Math.random() * 40,
    size: 14 + Math.random() * 12,
    delay: i * 60 + Math.random() * 30,
    dur: 380 + Math.random() * 200,
    hue: 18 + Math.random() * 22, // Orange band
  })), [cw]);
  const smoke = useMemo(() => Array.from({ length: ppFxN(10) }, () => ({
    offsetX: -cw * 0.35 + Math.random() * cw * 0.7,
    offsetY: -10 + Math.random() * 30,
    size: 18 + Math.random() * 14,
    delay: 200 + Math.random() * 300,
    dur: 700 + Math.random() * 300,
  })), [cw]);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {bursts.map((b, i) => (
        <div key={'cb' + i} style={{
          position: 'absolute',
          left: b.offsetX + 'px', top: b.offsetY + 'px',
          width: b.size + 'px', height: b.size + 'px',
          marginLeft: -b.size / 2, marginTop: -b.size / 2,
          borderRadius: '50%',
          background: `radial-gradient(circle, hsl(${b.hue}, 100%, 70%) 0%, hsl(${b.hue}, 100%, 45%) 45%, rgba(50,15,0,0.6) 90%, transparent 100%)`,
          boxShadow: `0 0 12px hsl(${b.hue}, 100%, 55%)`,
          opacity: 0,
          animation: `bb-carpet-burst ${b.dur}ms ease-out ${b.delay}ms forwards`,
        }} />
      ))}
      {smoke.map((s, i) => (
        <div key={'cs' + i} style={{
          position: 'absolute',
          left: s.offsetX + 'px', top: s.offsetY + 'px',
          width: s.size + 'px', height: s.size + 'px',
          marginLeft: -s.size / 2, marginTop: -s.size / 2,
          borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(80,60,50,0.65) 0%, rgba(40,30,25,0.35) 60%, transparent 100%)',
          opacity: 0,
          animation: `bb-carpet-smoke ${s.dur}ms ease-out ${s.delay}ms forwards`,
        }} />
      ))}
      <style>{`
        @keyframes bb-carpet-burst {
          0%   { opacity: 0;   transform: scale(0.25); }
          35%  { opacity: 1;   transform: scale(1.15); }
          100% { opacity: 0;   transform: scale(1.6); }
        }
        @keyframes bb-carpet-smoke {
          0%   { opacity: 0;   transform: scale(0.6) translateY(0); }
          40%  { opacity: 0.7; transform: scale(1.1) translateY(-6px); }
          100% { opacity: 0;   transform: scale(1.6) translateY(-22px); }
        }
      `}</style>
    </div>
  );
}

// 3. bomblebee_dive — Dive Bomblebee's "send to bottom of deck" payload.
//    Diagonal streak from upper-right (the Bomblebee diving in) +
//    impact poof at the target zone. White / pale-blue palette so it
//    reads distinct from the orange explosions.
function BomblebeeDiveEffect({ x, y }) {
  const sparks = useMemo(() => Array.from({ length: ppFxN(14) }, () => {
    const angle = Math.PI * (0.7 + Math.random() * 0.6); // bottom-left arc
    const speed = 18 + Math.random() * 32;
    return {
      dx: Math.cos(angle) * speed,
      dy: Math.sin(angle) * speed,
      size: 3 + Math.random() * 5,
      color: ['#ffffff', '#ddeeff', '#aaccff', '#88aadd'][Math.floor(Math.random() * 4)],
      delay: 220 + Math.random() * 80,
      dur: 360 + Math.random() * 200,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {/* Streak — long thin trail descending from upper-right */}
      <div style={{
        position: 'absolute',
        left: 60, top: -90, width: 6, height: 140,
        background: 'linear-gradient(180deg, transparent 0%, rgba(255,255,255,0.95) 60%, rgba(160,200,255,0.85) 100%)',
        borderRadius: '50%',
        transform: 'rotate(35deg)',
        transformOrigin: '50% 100%',
        opacity: 0,
        boxShadow: '0 0 10px rgba(180,220,255,0.7)',
        animation: 'bb-dive-streak 280ms ease-in forwards',
      }} />
      {/* Impact poof — short, soft white burst at landing point */}
      <div style={{
        position: 'absolute',
        width: 70, height: 70, left: -35, top: -35,
        borderRadius: '50%',
        background: 'radial-gradient(circle, rgba(255,255,255,0.95) 0%, rgba(180,210,255,0.6) 50%, transparent 100%)',
        opacity: 0,
        animation: 'bb-dive-poof 500ms ease-out 230ms forwards',
      }} />
      {sparks.map((s, i) => (
        <div key={'ds' + i} style={{
          position: 'absolute',
          left: -s.size / 2 + 'px', top: -s.size / 2 + 'px',
          width: s.size + 'px', height: s.size + 'px',
          borderRadius: '50%',
          background: s.color,
          boxShadow: `0 0 6px ${s.color}`,
          opacity: 0,
          animation: `bb-dive-spark ${s.dur}ms ease-out ${s.delay}ms forwards`,
          '--ddx': s.dx + 'px', '--ddy': s.dy + 'px',
        }} />
      ))}
      <style>{`
        @keyframes bb-dive-streak {
          0%   { opacity: 0; transform: rotate(35deg) translateY(-40px) scaleY(0.6); }
          40%  { opacity: 1; transform: rotate(35deg) translateY(0)    scaleY(1); }
          100% { opacity: 0; transform: rotate(35deg) translateY(20px) scaleY(0.8); }
        }
        @keyframes bb-dive-poof {
          0%   { opacity: 0;   transform: scale(0.3); }
          30%  { opacity: 0.9; transform: scale(1.2); }
          100% { opacity: 0;   transform: scale(1.7); }
        }
        @keyframes bb-dive-spark {
          0%   { transform: translate(0, 0) scale(1); opacity: 1; }
          100% { transform: translate(var(--ddx), var(--ddy)) scale(0); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

// 4. bomblebee_tick — Time Bomblebee gaining a Bomb Counter.
//    Small slow ticking spark with a fuse-glow ring; deliberately
//    UNDER-stated so it doesn't read as a damage event. Yellow-orange
//    pulse, no shrapnel.
function BomblebeeTickEffect({ x, y }) {
  const sparks = useMemo(() => Array.from({ length: ppFxN(6) }, (_, i) => ({
    angle: (i / 6) * Math.PI * 2,
    delay: i * 70 + Math.random() * 40,
  })), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div style={{
        position: 'absolute',
        width: 28, height: 28, left: -14, top: -14,
        borderRadius: '50%',
        border: '2px solid rgba(255,200,80,0.85)',
        boxShadow: '0 0 10px rgba(255,180,60,0.7), inset 0 0 6px rgba(255,220,120,0.6)',
        opacity: 0,
        animation: 'bb-tick-ring 700ms ease-out forwards',
      }} />
      {sparks.map((s, i) => (
        <div key={'tk' + i} style={{
          position: 'absolute',
          left: -3 + 'px', top: -3 + 'px',
          width: 6, height: 6,
          borderRadius: '50%',
          background: '#ffe066',
          boxShadow: '0 0 6px #ffaa22',
          opacity: 0,
          animation: `bb-tick-spark 600ms ease-out ${s.delay}ms forwards`,
          '--tdx': Math.cos(s.angle) * 22 + 'px',
          '--tdy': Math.sin(s.angle) * 22 + 'px',
        }} />
      ))}
      <style>{`
        @keyframes bb-tick-ring {
          0%   { opacity: 0;   transform: scale(0.5); }
          40%  { opacity: 0.9; transform: scale(1.3); }
          100% { opacity: 0;   transform: scale(1.7); }
        }
        @keyframes bb-tick-spark {
          0%   { transform: translate(0, 0) scale(0.6); opacity: 1; }
          100% { transform: translate(var(--tdx), var(--tdy)) scale(0); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

// 5. bomblebee_detonate — Time Bomblebee releasing all Bomb Counters.
//    Heavy compound explosion with multiple staggered shockwaves and
//    bright white core. The biggest of the bunch — reads as the
//    "stored energy unleashed" payoff visual.
function BomblebeeDetonateEffect({ x, y }) {
  const particles = useMemo(() => Array.from({ length: ppFxN(38) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 35 + Math.random() * 75;
    return {
      dx: Math.cos(angle) * speed,
      dy: Math.sin(angle) * speed,
      size: 4 + Math.random() * 9,
      color: ['#fff', '#ffeecc', '#ffaa22', '#ff5500', '#ffcc00', '#882200'][Math.floor(Math.random() * 6)],
      delay: Math.random() * 120,
      dur: 500 + Math.random() * 500,
    };
  }), []);
  const shockwaves = [0, 130, 250]; // Three staggered waves
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {shockwaves.map((delay, i) => (
        <div key={'sw' + i} style={{
          position: 'absolute',
          width: 110, height: 110, left: -55, top: -55,
          borderRadius: '50%',
          border: `${4 - i}px solid rgba(255,180,80,${0.85 - i * 0.2})`,
          boxShadow: '0 0 14px rgba(255,140,40,0.8)',
          opacity: 0,
          animation: `bb-deto-wave 700ms ease-out ${delay}ms forwards`,
        }} />
      ))}
      <div style={{
        position: 'absolute',
        width: 80, height: 80, left: -40, top: -40,
        borderRadius: '50%',
        background: 'radial-gradient(circle, rgba(255,255,240,1) 0%, rgba(255,180,60,0.85) 30%, rgba(180,40,0,0.5) 70%, transparent 100%)',
        animation: 'bb-deto-core 600ms ease-out forwards',
      }} />
      {particles.map((p, i) => (
        <div key={'dp' + i} style={{
          position: 'absolute',
          left: -p.size / 2 + 'px', top: -p.size / 2 + 'px',
          width: p.size + 'px', height: p.size + 'px',
          borderRadius: '50%',
          background: p.color,
          boxShadow: `0 0 7px ${p.color}`,
          opacity: 0,
          animation: `bb-deto-particle ${p.dur}ms ease-out ${p.delay}ms forwards`,
          '--ddx': p.dx + 'px', '--ddy': p.dy + 'px',
        }} />
      ))}
      <style>{`
        @keyframes bb-deto-wave {
          0%   { opacity: 0;   transform: scale(0.3); }
          30%  { opacity: 1;   transform: scale(1.2); }
          100% { opacity: 0;   transform: scale(2.4); }
        }
        @keyframes bb-deto-core {
          0%   { transform: scale(0.4); opacity: 1; }
          50%  { transform: scale(1.6); opacity: 0.8; }
          100% { transform: scale(2.0); opacity: 0; }
        }
        @keyframes bb-deto-particle {
          0%   { transform: translate(0, 0) scale(1.4); opacity: 1; }
          25%  { opacity: 1; }
          100% { transform: translate(var(--ddx), var(--ddy)) scale(0); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

// 6. bomblebee_cluster — Bomblebee Cluster's chained re-summon flash.
//    Three rapid-fire bursts in sequence with varying sizes. Yellow /
//    black palette to match the Bomblebee theme; reads as "chain
//    reaction kicking off" rather than damage.
function BomblebeeClusterEffect({ x, y }) {
  const bursts = useMemo(() => [
    { offsetX: -28, offsetY: -10, size: 32, delay: 0,   hue: 50 },
    { offsetX: 28,  offsetY: -22, size: 38, delay: 120, hue: 38 },
    { offsetX: 0,   offsetY: 22,  size: 44, delay: 250, hue: 30 },
  ], []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {bursts.map((b, i) => (
        <div key={'cl' + i} style={{
          position: 'absolute',
          left: b.offsetX + 'px', top: b.offsetY + 'px',
          width: b.size + 'px', height: b.size + 'px',
          marginLeft: -b.size / 2, marginTop: -b.size / 2,
          borderRadius: '50%',
          background: `radial-gradient(circle, hsl(${b.hue},100%,75%) 0%, hsl(${b.hue},100%,50%) 40%, rgba(40,20,0,0.6) 85%, transparent 100%)`,
          boxShadow: `0 0 14px hsl(${b.hue},100%,55%)`,
          opacity: 0,
          animation: `bb-cluster-pop 520ms ease-out ${b.delay}ms forwards`,
        }} />
      ))}
      {/* Trailing wasp-stripe specks */}
      {Array.from({ length: ppFxN(14) }).map((_, i) => {
        const angle = Math.random() * Math.PI * 2;
        const dist = 25 + Math.random() * 35;
        const dx = Math.cos(angle) * dist;
        const dy = Math.sin(angle) * dist;
        const isBlack = i % 3 === 0;
        return (
          <div key={'cs' + i} style={{
            position: 'absolute',
            left: -3, top: -3, width: 6, height: 6,
            borderRadius: '50%',
            background: isBlack ? '#1a1100' : '#ffd040',
            boxShadow: isBlack ? '0 0 3px #000' : '0 0 6px #ffaa20',
            opacity: 0,
            animation: `bb-cluster-speck 700ms ease-out ${100 + i * 25}ms forwards`,
            '--cdx': dx + 'px', '--cdy': dy + 'px',
          }} />
        );
      })}
      <style>{`
        @keyframes bb-cluster-pop {
          0%   { opacity: 0;   transform: scale(0.3); }
          40%  { opacity: 1;   transform: scale(1.2); }
          100% { opacity: 0;   transform: scale(1.8); }
        }
        @keyframes bb-cluster-speck {
          0%   { transform: translate(0, 0) scale(1); opacity: 1; }
          100% { transform: translate(var(--cdx), var(--cdy)) scale(0); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

// 7. bomblebee_fuse — Burning Fuse's lit-fuse trail.
//    A horizontal sparkly fuse line racing across the target zone left-
//    to-right, then a final flash. Reads as "the wick has been lit" —
//    the precursor visual to the Bomblebees re-firing right after.
function BomblebeeFuseEffect({ x, y, w }) {
  const cw = w || 110;
  const sparkles = useMemo(() => Array.from({ length: ppFxN(18) }, (_, i) => ({
    leftPct: (i / 17) * 100,
    delay: i * 18 + Math.random() * 30,
    dur: 320 + Math.random() * 180,
    size: 3 + Math.random() * 4,
  })), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {/* Fuse wire track */}
      <div style={{
        position: 'absolute',
        left: -cw * 0.45 + 'px', top: -2 + 'px',
        width: cw * 0.9 + 'px', height: 4 + 'px',
        background: 'linear-gradient(90deg, rgba(120,80,40,0.6) 0%, rgba(180,140,80,0.85) 50%, rgba(120,80,40,0.6) 100%)',
        borderRadius: 2,
        opacity: 0.85,
      }} />
      {/* Travelling spark cluster — moves left to right */}
      <div style={{
        position: 'absolute',
        left: -cw * 0.45 + 'px', top: -10 + 'px',
        width: 18, height: 18,
        borderRadius: '50%',
        background: 'radial-gradient(circle, #ffeecc 0%, #ff8800 50%, transparent 90%)',
        boxShadow: '0 0 14px #ff7700, 0 0 28px #ff5500',
        opacity: 0,
        animation: `bb-fuse-travel 700ms cubic-bezier(0.4, 0, 0.6, 1) forwards`,
        '--fW': (cw * 0.9) + 'px',
      }} />
      {/* Stationary sparkles along the track */}
      {sparkles.map((s, i) => (
        <div key={'fs' + i} style={{
          position: 'absolute',
          left: `calc(${-cw * 0.45 + (s.leftPct / 100) * cw * 0.9}px - 2px)`,
          top: -2 + 'px',
          width: s.size + 'px', height: s.size + 'px',
          borderRadius: '50%',
          background: '#ffcc44',
          boxShadow: '0 0 5px #ff9900',
          opacity: 0,
          animation: `bb-fuse-spark ${s.dur}ms ease-out ${s.delay}ms forwards`,
        }} />
      ))}
      {/* Final flash at the end of the fuse */}
      <div style={{
        position: 'absolute',
        width: 50, height: 50,
        left: cw * 0.45 - 25 + 'px', top: -25 + 'px',
        borderRadius: '50%',
        background: 'radial-gradient(circle, rgba(255,255,200,1) 0%, rgba(255,160,40,0.7) 50%, transparent 100%)',
        opacity: 0,
        animation: 'bb-fuse-pop 400ms ease-out 600ms forwards',
      }} />
      <style>{`
        @keyframes bb-fuse-travel {
          0%   { opacity: 0; transform: translateX(0); }
          15%  { opacity: 1; }
          100% { opacity: 1; transform: translateX(var(--fW)); }
        }
        @keyframes bb-fuse-spark {
          0%   { opacity: 0;   transform: scale(0.4); }
          50%  { opacity: 1;   transform: scale(1.4); }
          100% { opacity: 0;   transform: scale(0.8); }
        }
        @keyframes bb-fuse-pop {
          0%   { opacity: 0;   transform: scale(0.3); }
          40%  { opacity: 1;   transform: scale(1.4); }
          100% { opacity: 0;   transform: scale(2.0); }
        }
      `}</style>
    </div>
  );
}

// Guardian Beast Gou: white protective bubble engulfing the target.
// Three rings + a single rim-circling highlight. The component
// receives the slot's anchor coordinates from `GameAnimationRenderer`;
// inner CSS positions everything relative to that anchor so the
// bubble auto-centers regardless of slot size.
// ── Bleed (v714) ─────────────────────────────────────────────────
// Blood splatter — bursting droplets flung outward plus a few heavy
// drops that arc and drip. Used ON TOP of whatever attack animation
// already played (Devlin's hits) and as the Bleed-damage pulse.
function BloodSplatterEffect({ x, y }) {
  const drops = useMemo(() => Array.from({ length: ppFxN(26) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 22 + Math.random() * 54;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed - 10,
      size: 3 + Math.random() * 8,
      delay: Math.random() * 90,
      dur: 380 + Math.random() * 320,
      color: ['#b3001b', '#d40f2b', '#8a0014', '#e0324c', '#6e000f'][Math.floor(Math.random() * 5)],
      stretch: 1 + Math.random() * 1.6,
      rot: angle * 180 / Math.PI,
    };
  }), []);
  const smears = useMemo(() => Array.from({ length: 5 }, () => ({
    ox: (Math.random() - 0.5) * 36, oy: (Math.random() - 0.5) * 30,
    w: 14 + Math.random() * 22, h: 10 + Math.random() * 16,
    rot: Math.random() * 360, delay: 40 + Math.random() * 120,
  })), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-blood-burst" />
      {smears.map((m, i) => (
        <div key={'sm' + i} className="anim-blood-smear" style={{
          left: m.ox, top: m.oy, width: m.w, height: m.h,
          transform: `translate(-50%, -50%) rotate(${m.rot}deg)`, animationDelay: m.delay + 'ms',
        }} />
      ))}
      {drops.map((d, i) => (
        <div key={'bd' + i} className="anim-blood-drop" style={{
          '--bdx': d.dx + 'px', '--bdy': d.dy + 'px', '--bgy': (d.dy + 34) + 'px',
          width: d.size, height: d.size * d.stretch, background: d.color,
          transform: `rotate(${d.rot}deg)`,
          animationDelay: d.delay + 'ms', animationDuration: d.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Bloody cut — a jagged, glistening gash torn open across the card:
// dark wound line, wet red inner edge, tissue flaps, then heavy drips
// running off the lower lip. Doctor Fester / Ghoul Guard.
function BloodyCutEffect({ x, y }) {
  const drips = useMemo(() => Array.from({ length: ppFxN(6) }, (_, i) => ({
    ox: -34 + i * 14 + (Math.random() - 0.5) * 8,
    len: 14 + Math.random() * 22,
    delay: 260 + Math.random() * 260,
    dur: 520 + Math.random() * 300,
  })), []);
  const spurts = useMemo(() => Array.from({ length: ppFxN(10) }, () => {
    const angle = -Math.PI / 2 + (Math.random() - 0.5) * 1.6;
    const speed = 18 + Math.random() * 30;
    return { dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed, size: 3 + Math.random() * 5,
      delay: 120 + Math.random() * 120, dur: 380 + Math.random() * 220 };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-cut-flash" />
      <svg className="anim-cut-svg" viewBox="-60 -30 120 60" width="120" height="60">
        {/* Wundlippen (Gewebe) */}
        <path className="anim-cut-flesh" d="M-46,-2 L-30,-8 L-14,-3 L2,-9 L18,-2 L34,-7 L46,0 L34,9 L18,4 L2,11 L-14,5 L-30,10 Z" />
        {/* nasse Innenkante */}
        <path className="anim-cut-wet" d="M-44,0 L-30,-5 L-14,-1 L2,-6 L18,0 L34,-4 L44,1 L34,6 L18,2 L2,8 L-14,3 L-30,7 Z" />
        {/* dunkler Schnitt */}
        <path className="anim-cut-line" d="M-46,0 L-30,-4 L-14,0 L2,-5 L18,1 L34,-3 L46,1" />
      </svg>
      {spurts.map((d, i) => (
        <div key={'cs' + i} className="anim-blood-drop" style={{
          '--bdx': d.dx + 'px', '--bdy': d.dy + 'px', '--bgy': (d.dy + 30) + 'px',
          width: d.size, height: d.size * 1.6, background: '#c1121f',
          animationDelay: d.delay + 'ms', animationDuration: d.dur + 'ms',
        }} />
      ))}
      {drips.map((d, i) => (
        <div key={'cd' + i} className="anim-cut-drip" style={{
          left: d.ox, height: d.len, animationDelay: d.delay + 'ms', animationDuration: d.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

function ShieldBubbleEffect({ x, y }) {
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-shield-bubble-core" />
      <div className="anim-shield-bubble-rim" />
      <div className="anim-shield-bubble-glint" />
    </div>
  );
}

// Guardian Beast Ji: massive cyan-white shock that stuns the target.
// Bigger and bluer than the standard `electric_strike` (which is
// yellow and tuned for damage hits). Layered visuals: a wide cyan
// flash, two giant zigzag bolts crashing down vertically, a halo
// of inward-converging arc bolts, and a burst of crackling sparks.
function StunStrikeEffect({ x, y }) {
  const bolts = useMemo(() => Array.from({ length: ppFxN(22) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const dist = 70 + Math.random() * 60;
    return {
      startX: Math.cos(angle) * dist,
      startY: Math.sin(angle) * dist,
      size: 14 + Math.random() * 14,
      delay: Math.random() * 250,
      dur: 200 + Math.random() * 200,
      rotation: (angle * 180 / Math.PI) + 180,
    };
  }), []);
  const sparks = useMemo(() => Array.from({ length: ppFxN(22) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 18 + Math.random() * 38;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 3 + Math.random() * 6,
      color: ['#7ddcff','#aef','#fff','#9be8ff','#cff'][Math.floor(Math.random() * 5)],
      delay: 280 + Math.random() * 200,
      dur: 300 + Math.random() * 300,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-stun-flash" />
      <div className="anim-stun-megabolt anim-stun-megabolt-1">⚡</div>
      <div className="anim-stun-megabolt anim-stun-megabolt-2">⚡</div>
      {bolts.map((b, i) => (
        <div key={'sb'+i} className="anim-stun-bolt" style={{
          '--startX': b.startX + 'px', '--startY': b.startY + 'px', '--size': b.size + 'px',
          '--rotation': b.rotation + 'deg',
          animationDelay: b.delay + 'ms', animationDuration: b.dur + 'ms',
        }}>⚡</div>
      ))}
      {sparks.map((s, i) => (
        <div key={'ss'+i} className="anim-explosion-particle" style={{
          '--dx': s.dx + 'px', '--dy': s.dy + 'px', '--size': s.size + 'px',
          '--color': s.color, animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Guardian Beast Niu: golden power-up. A warm gold flash bursts
// outward, a halo ring expands around the hero, an upward shaft of
// light rises behind them, and sparkles + small stars twinkle as
// they spiral out. Tuned to feel like a buff "landing" rather than
// an attack — warm, celebratory, ~700ms total.
function NiuPowerUpEffect({ x, y }) {
  const sparkles = useMemo(() => Array.from({ length: ppFxN(18) }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 22 + Math.random() * 38;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed - 8,
      size: 4 + Math.random() * 6,
      color: ['#ffd700','#fff4a3','#ffe455','#fff','#ffb84a'][Math.floor(Math.random() * 5)],
      delay: Math.random() * 200,
      dur: 400 + Math.random() * 350,
    };
  }), []);
  const stars = useMemo(() => Array.from({ length: ppFxN(8) }, (_, i) => {
    const angle = (i / 8) * Math.PI * 2 + Math.random() * 0.4;
    const dist = 40 + Math.random() * 25;
    return {
      x: Math.cos(angle) * dist,
      y: Math.sin(angle) * dist - 10,
      size: 14 + Math.random() * 8,
      delay: 60 + Math.random() * 220,
      dur: 500 + Math.random() * 250,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-niu-shaft" />
      <div className="anim-niu-flash" />
      <div className="anim-niu-halo" />
      {stars.map((s, i) => (
        <div key={'nis'+i} className="anim-niu-star" style={{
          '--tx': s.x + 'px', '--ty': s.y + 'px',
          fontSize: s.size + 'px',
          animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }}>★</div>
      ))}
      {sparkles.map((s, i) => (
        <div key={'nip'+i} className="anim-explosion-particle" style={{
          '--dx': s.dx + 'px', '--dy': s.dy + 'px', '--size': s.size + 'px',
          '--color': s.color, animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
          boxShadow: `0 0 8px ${s.color}, 0 0 4px #fff`,
        }} />
      ))}
    </div>
  );
}

// Guardian Beast She: two large snake fangs lunging down from above
// the target, snapping shut on impact, then withdrawing. Tuned to
// fire SIMULTANEOUSLY across every selected target — the card
// broadcasts all snake_bite events in one frame, then waits a
