    // Flug (240-320 ms), 40 ms versetzt, mit seitlichem Zittern um die
    // Fluglinie, damit es ein Strahl und keine Perlenkette wird.
    const onWeaponBarrage = ({ sourceOwner, sourceHeroIdx, targetOwner, targetHeroIdx, targetZoneSlot, count }) => {
      const srcLabel = sourceOwner === myIdx ? 'me' : 'opp';
      const tgtLabel = targetOwner === myIdx ? 'me' : 'opp';
      const srcEl = document.querySelector(`[data-hero-zone][data-hero-owner="${srcLabel}"][data-hero-idx="${sourceHeroIdx}"]`);
      const tgtEl = (targetZoneSlot != null && targetZoneSlot >= 0)
        ? document.querySelector(`[data-support-zone][data-support-owner="${tgtLabel}"][data-support-hero="${targetHeroIdx}"][data-support-slot="${targetZoneSlot}"]`)
        : document.querySelector(`[data-hero-zone][data-hero-owner="${tgtLabel}"][data-hero-idx="${targetHeroIdx}"]`);
      if (!srcEl || !tgtEl) return;
      const sr = srcEl.getBoundingClientRect();
      const tr = tgtEl.getBoundingClientRect();
      const sxPx = sr.left + sr.width / 2, syPx = sr.top + sr.height / 2;
      const txPx = tr.left + tr.width / 2, tyPx = tr.top + tr.height / 2;
      const baseAngle = Math.atan2(tyPx - syPx, txPx - sxPx) * 180 / Math.PI;
      // Senkrechte zur Fluglinie fuer das Zittern
      const len = Math.hypot(txPx - sxPx, tyPx - syPx) || 1;
      const nx = -(tyPx - syPx) / len, ny = (txPx - sxPx) / len;
      const WEAPONS = ['🗡️', '⚔️', '🪓', '🔱', '🗡️', '🪓', '⚔️', '🔱'];
      // Grundausrichtung der Glyphen (Twemoji/Noto/Segoe stimmen hier
      // ueberein): 🗡️ Spitze nach UNTEN-LINKS (Bildschirm 135°), 🔱 Spitze
      // nach OBEN (−90°), 🪓 Blatt nach OBEN-RECHTS (−45°), ⚔️ symmetrisch
      // — eine Klinge zeigt nach oben-rechts (−45°). Der Offset dreht die
      // Spitze auf 0° (Ost); danach zeigt sie mit `baseAngle` aufs Ziel.
      const FACING = { '🗡️': -135, '⚔️': 45, '🪓': 45, '🔱': 90 };
      const n = Math.max(10, Math.min(20, count || 14));
      const STEP = 40;
      for (let i = 0; i < n; i++) {
        setTimeout(() => {
          const emoji = WEAPONS[(i * 5 + Math.floor(Math.random() * 3)) % WEAPONS.length];
          const size = 18 + Math.floor(Math.random() * 22);         // 18..40 px
          const jitter = (Math.random() - 0.5) * 34;                 // ± 17 px quer
          const dur = 240 + Math.floor(Math.random() * 80);
          const id = Date.now() + Math.random();
          setProjectileAnims(prev => [...prev, {
            id, emoji,
            trailClass: null,
            emojiStyle: { fontSize: `${size}px` },
            projectileClass: null,   // Emoji-Projektil (ein Klassen-Projektil wuerde das Emoji verstecken)
            projectileShape: null,
            noTrail: false,
            srcX: sxPx + nx * jitter * 0.4, srcY: syPx + ny * jitter * 0.4,
            tgtX: txPx + nx * jitter, tgtY: tyPx + ny * jitter,
            angle: baseAngle + (FACING[emoji] || 0) + (Math.random() - 0.5) * 8,
            dur,
          }]);
          setTimeout(() => setProjectileAnims(prev => prev.filter(a => a.id !== id)), dur + 120);
          if (window.playSFX && i % 3 === 0) window.playSFX('slash', { category: 'effect', rate: 1.2 + Math.random() * 0.5, dedupe: 30 });
        }, i * STEP);
      }
    };
    socket.on('play_weapon_barrage', onWeaponBarrage);
    const onButterflyCloud = ({ sourceOwner, sourceHeroIdx, targets }) => {
      const srcLabel = sourceOwner === myIdx ? 'me' : 'opp';
      const srcEl = document.querySelector(`[data-hero-zone][data-hero-owner="${srcLabel}"][data-hero-idx="${sourceHeroIdx}"]`);
      if (!srcEl) return;
      const sr = srcEl.getBoundingClientRect();
      const srcX = sr.left + sr.width / 2;
      const srcY = sr.top + sr.height / 2;

      // Resolve target element positions
      const tgtPositions = [];
      for (const t of (targets || [])) {
        const tLabel = t.owner === myIdx ? 'me' : 'opp';
        let el;
        if (t.type === 'creature' && t.zoneSlot != null) {
          el = document.querySelector(`[data-support-zone][data-support-owner="${tLabel}"][data-support-hero="${t.heroIdx}"][data-support-slot="${t.zoneSlot}"]`);
        } else {
          el = document.querySelector(`[data-hero-zone][data-hero-owner="${tLabel}"][data-hero-idx="${t.heroIdx}"]`);
        }
        if (el) {
          const r = el.getBoundingClientRect();
          tgtPositions.push({ x: r.left + r.width / 2, y: r.top + r.height / 2, el });
        }
      }
      if (tgtPositions.length === 0) return;

      // ★ v1302 (Als Befund 23.9.: „Butterfly Cloud hat noch keinen
      // Sound"). Eigenes Socket-Ereignis, keine Zonen-Animation — der
      // Klang steht deshalb hier und nicht in ZONE_ANIM_SFX. Drei Momente
      // wie im Bild: der Schwarm hebt ab (heller Luftzug), einzelne Falter
      // glitzern im Flug (hoch gestimmte Glocken), bei 900 ms der goldene
      // Aufprall. Alle Lagen ohne Sammelkategorie (CARD_API ⑤) und mit
      // eigenem Dedupe, damit eine zweite Wolke im selben Zug nicht
      // doppelt klingt.
      if (window.playSFX) {
        window.playSFX('elem_wind', { rate: 1.35, volume: 0.7, category: null, dedupe: 300 });
        [60, 220, 420].forEach((ms, i) => window.playSFX('ping', {
          rate: [1.9, 2.25, 2.0][i], volume: 0.35, delay: ms, category: null, dedupe: 0,
        }));
        window.playSFX('buff', { rate: 1.15, volume: 0.8, delay: 900, category: null, dedupe: 300 });
      }

      // Inject keyframes once
      if (!document.getElementById('butterfly-cloud-keyframes')) {
        const style = document.createElement('style');
        style.id = 'butterfly-cloud-keyframes';
        style.textContent = `
          @keyframes butterflyFly {
            0% { transform: translate(0,0) scale(0.3) rotate(0deg); opacity: 0; }
            15% { opacity: 1; transform: translate(calc(var(--bfDx)*0.15 + var(--bfWobble1)), calc(var(--bfDy)*0.15 + var(--bfWobble2))) scale(0.8) rotate(var(--bfSpin1)); }
            50% { transform: translate(calc(var(--bfDx)*0.5 + var(--bfWobble2)*1.5), calc(var(--bfDy)*0.5 + var(--bfWobble1)*-1)) scale(1) rotate(var(--bfSpin2)); }
            85% { opacity: 1; transform: translate(calc(var(--bfDx)*0.85 + var(--bfWobble1)*-0.5), calc(var(--bfDy)*0.85 + var(--bfWobble2)*0.5)) scale(0.9) rotate(var(--bfSpin3)); }
            100% { transform: translate(var(--bfDx), var(--bfDy)) scale(0.4) rotate(var(--bfSpin4)); opacity: 0; }
          }
          @keyframes butterflyBurst {
            0% { transform: scale(0); opacity: 0.9; }
            50% { transform: scale(1.5); opacity: 0.7; }
            100% { transform: scale(2.5); opacity: 0; }
          }
        `;
        document.head.appendChild(style);
      }

      // Spawn butterflies from source to each target
      const totalButterflies = Math.min(120, tgtPositions.length * 30);
      const perTarget = Math.floor(totalButterflies / tgtPositions.length);
      const butterflyChars = ['🦋'];
      const colors = ['#ffd700','#ffec80','#fff4cc','#f0c040','#ffe066'];

      for (let ti = 0; ti < tgtPositions.length; ti++) {
        const tgt = tgtPositions[ti];
        const dx = tgt.x - srcX;
        const dy = tgt.y - srcY;

        for (let i = 0; i < perTarget; i++) {
          const bf = document.createElement('div');
          const delay = Math.random() * 500;
          const dur = 700 + Math.random() * 500;
          const wobble1 = -30 + Math.random() * 60;
          const wobble2 = -25 + Math.random() * 50;
          const spin1 = -40 + Math.random() * 80;
          const spin2 = -60 + Math.random() * 120;
          const spin3 = -30 + Math.random() * 60;
          const spin4 = Math.random() * 360;
          const size = 10 + Math.random() * 10;
          const color = colors[Math.floor(Math.random() * colors.length)];

          bf.textContent = butterflyChars[0];
          bf.style.cssText = `
            position:fixed; left:${srcX}px; top:${srcY}px; z-index:10200; pointer-events:none;
            font-size:${size}px; filter:drop-shadow(0 0 4px ${color}) drop-shadow(0 0 8px rgba(255,215,0,0.5));
            --bfDx:${dx + (-15 + Math.random()*30)}px; --bfDy:${dy + (-15 + Math.random()*30)}px;
            --bfWobble1:${wobble1}px; --bfWobble2:${wobble2}px;
            --bfSpin1:${spin1}deg; --bfSpin2:${spin2}deg; --bfSpin3:${spin3}deg; --bfSpin4:${spin4}deg;
            animation: butterflyFly ${dur}ms ease-in-out ${delay}ms forwards;
            opacity: 0;
          `;
          document.body.appendChild(bf);
          setTimeout(() => bf.remove(), delay + dur + 100);
        }

        // Golden burst at target on impact
        setTimeout(() => {
          const burst = document.createElement('div');
          burst.style.cssText = `
            position:fixed; left:${tgt.x - 40}px; top:${tgt.y - 40}px; width:80px; height:80px;
            z-index:10201; pointer-events:none; border-radius:50%;
            background: radial-gradient(circle, rgba(255,215,0,0.9) 0%, rgba(255,236,128,0.5) 40%, transparent 70%);
            animation: butterflyBurst 500ms ease-out forwards;
          `;
          document.body.appendChild(burst);
          setTimeout(() => burst.remove(), 600);
        }, 900);
      }
    };
    socket.on('butterfly_cloud_animation', onButterflyCloud);
    const onSmugCoinSave = ({ owner, heroIdx }) => {
      const ownerLabel = owner === myIdx ? 'me' : 'opp';
      const heroEl = document.querySelector(`[data-hero-zone][data-hero-owner="${ownerLabel}"][data-hero-idx="${heroIdx}"]`);
      if (!heroEl) return;
      const hr = heroEl.getBoundingClientRect();
      const cx = hr.left + hr.width / 2;
      const cy = hr.top + hr.height / 2;

      // Inject keyframes once
      if (!document.getElementById('smug-coin-keyframes')) {
        const style = document.createElement('style');
        style.id = 'smug-coin-keyframes';
        style.textContent = `
          @keyframes smugCoinFall {
            0% { transform: translateY(var(--scStartY)) rotate(var(--scRot1)) scale(0.6); opacity: 0; }
            10% { opacity: 1; }
            70% { opacity: 1; transform: translateY(var(--scMidY)) rotate(var(--scRot2)) scale(1); }
            100% { transform: translateY(var(--scEndY)) rotate(var(--scRot3)) scale(0.8); opacity: 0; }
          }
          @keyframes smugCoinFlash {
            0% { transform: scale(0); opacity: 0.9; }
            40% { transform: scale(1.8); opacity: 0.6; }
            100% { transform: scale(3); opacity: 0; }
          }
        `;
        document.head.appendChild(style);
      }

      // Golden flash on hero
      const flash = document.createElement('div');
      flash.style.cssText = `
        position:fixed; left:${cx - 50}px; top:${cy - 50}px; width:100px; height:100px;
        z-index:10201; pointer-events:none; border-radius:50%;
        background: radial-gradient(circle, rgba(255,200,50,0.95) 0%, rgba(255,170,0,0.5) 40%, transparent 70%);
        animation: smugCoinFlash 600ms ease-out forwards;
      `;
      document.body.appendChild(flash);
      setTimeout(() => flash.remove(), 700);

      // Rain ~100 sc.png coins from above onto the hero
      const coinCount = 100;
      for (let i = 0; i < coinCount; i++) {
        const coin = document.createElement('img');
        coin.src = '/data/sc.png';
        const size = 16 + Math.random() * 16;
        const xOff = -70 + Math.random() * 140;
        const startY = -120 - Math.random() * 200;
        const midY = -10 + Math.random() * 20;
        const endY = 30 + Math.random() * 40;
        const rot1 = Math.random() * 360;
        const rot2 = rot1 + (-180 + Math.random() * 360);
        const rot3 = rot2 + (-90 + Math.random() * 180);
        const delay = Math.random() * 800;
        const dur = 600 + Math.random() * 500;

        coin.style.cssText = `
          position:fixed; left:${cx + xOff - size/2}px; top:${cy - size/2}px;
          width:${size}px; height:${size}px; z-index:10200; pointer-events:none;
          object-fit:contain;
          filter: drop-shadow(0 0 3px rgba(255,200,50,0.8)) drop-shadow(0 0 6px rgba(255,170,0,0.4));
          --scStartY:${startY}px; --scMidY:${midY}px; --scEndY:${endY}px;
          --scRot1:${rot1}deg; --scRot2:${rot2}deg; --scRot3:${rot3}deg;
          animation: smugCoinFall ${dur}ms ease-in ${delay}ms forwards;
          opacity: 0;
        `;
        document.body.appendChild(coin);
        setTimeout(() => coin.remove(), delay + dur + 100);
      }
    };
    socket.on('smug_coin_save', onSmugCoinSave);
    const onDivineRainStart = ({ turn }) => {
      if (window._playAnimations === false) return;
      // Remove any existing rain overlay
      const existing = document.getElementById('divine-rain-overlay');
      if (existing) existing.remove();

      // Inject keyframes once
      if (!document.getElementById('divine-rain-keyframes')) {
        const style = document.createElement('style');
        style.id = 'divine-rain-keyframes';
        style.textContent = `
          @keyframes rainDrop {
            0% { transform: translateY(-20px) translateX(0); opacity: 0; }
            10% { opacity: 1; }
            90% { opacity: 0.7; }
            100% { transform: translateY(110vh) translateX(-30px); opacity: 0; }
          }
          @keyframes rainFlash {
            0% { opacity: 0; }
            5% { opacity: 0.15; }
            10% { opacity: 0; }
            100% { opacity: 0; }
          }
        `;
        document.head.appendChild(style);
      }

      const overlay = document.createElement('div');
      overlay.id = 'divine-rain-overlay';
      overlay.dataset.rainTurn = turn;
      overlay.style.cssText = `
        position:fixed; top:0; left:0; width:100vw; height:100vh;
        z-index:9500; pointer-events:none; overflow:hidden;
      `;

      // Flash on start
      const flash = document.createElement('div');
      flash.style.cssText = `
        position:absolute; top:0; left:0; width:100%; height:100%;
        background: rgba(100,150,255,0.15);
        animation: rainFlash 2s ease-out forwards;
      `;
      overlay.appendChild(flash);

      // Spawn rain drops in waves
      const dropCount = 200;
      for (let i = 0; i < dropCount; i++) {
        const drop = document.createElement('div');
        const x = Math.random() * 110 - 5;
        const dur = 0.5 + Math.random() * 0.6;
        const delay = Math.random() * 2;
        const width = 1 + Math.random() * 1.5;
        const height = 12 + Math.random() * 18;
        const opacity = 0.15 + Math.random() * 0.35;

        drop.style.cssText = `
          position:absolute; left:${x}%; top:-20px;
          width:${width}px; height:${height}px;
          background: linear-gradient(to bottom, rgba(140,180,255,0), rgba(140,180,255,${opacity}), rgba(180,210,255,${opacity * 0.5}));
          border-radius: 0 0 2px 2px;
          animation: rainDrop ${dur}s linear ${delay}s infinite;
          transform: rotate(-5deg);
        `;
        overlay.appendChild(drop);
      }

      document.body.appendChild(overlay);
    };
    // ── „Iceage" — der Blizzard (v1012, Als Vorgabe 12.9.) ─────────
    // Ein GEWALTIGER, kurzer Wettereinbruch ueber dem ganzen Bild:
    // weisser Schleier, 220 schraeg jagende Schneestreifen, Frost, der
    // von allen vier Raendern hereinwaechst, und ein Kaelteblitz zum
    // Einschlag. Bauform wie der Divine-Rain-Vorhang (direkt ins DOM,
    // nicht als React-Komponente) — nur zeitlich begrenzt: nach 2,6 s
    // raeumt er sich selbst ab, es gibt kein Gegenstueck zum Abschalten.
    const onIceageBlizzard = () => {
      if (window._playAnimations === false) return;
      const alt = document.getElementById('iceage-overlay');
      if (alt) alt.remove();
      if (!document.getElementById('iceage-keyframes')) {
        const style = document.createElement('style');
        style.id = 'iceage-keyframes';
        style.textContent = `
          @keyframes iceageFlake {
            0%   { transform: translate(0, -12vh) rotate(-18deg); opacity: 0; }
            10%  { opacity: 1; }
            100% { transform: translate(-24vw, 118vh) rotate(-18deg); opacity: 0; }
          }
          @keyframes iceageVeil {
            0%   { opacity: 0; }
            18%  { opacity: .85; }
            70%  { opacity: .55; }
            100% { opacity: 0; }
          }
          @keyframes iceageFlash {
            0%   { opacity: 0; }
            6%   { opacity: .55; }
            22%  { opacity: 0; }
            100% { opacity: 0; }
          }
          @keyframes iceageFrost {
            0%   { opacity: 0; transform: scale(1.25); }
            25%  { opacity: 1; transform: scale(1); }
            75%  { opacity: .9; transform: scale(1); }
            100% { opacity: 0; transform: scale(1.05); }
          }
        `;
        document.head.appendChild(style);
      }
      const overlay = document.createElement('div');
      overlay.id = 'iceage-overlay';
      overlay.style.cssText = `
        position:fixed; top:0; left:0; width:100vw; height:100vh;
        z-index:9600; pointer-events:none; overflow:hidden;
      `;
      // Schleier
      const veil = document.createElement('div');
      veil.style.cssText = `
        position:absolute; inset:0;
        background: linear-gradient(180deg, rgba(200,235,255,.5) 0%, rgba(150,205,245,.32) 45%, rgba(120,180,230,.42) 100%);
        animation: iceageVeil 2600ms ease-out forwards;
      `;
      overlay.appendChild(veil);
      // Frost von den Raendern
      const frost = document.createElement('div');
      frost.style.cssText = `
        position:absolute; inset:0;
        background:
          radial-gradient(ellipse at 50% 50%, transparent 38%, rgba(225,245,255,.75) 82%),
          repeating-linear-gradient(115deg, rgba(255,255,255,.16) 0 3px, transparent 3px 9px);
        animation: iceageFrost 2600ms ease-out forwards;
      `;
      overlay.appendChild(frost);
      // Kaelteblitz
      const flash = document.createElement('div');
      flash.style.cssText = `
        position:absolute; inset:0; background: rgba(235,250,255,.95);
        animation: iceageFlash 2600ms ease-out forwards;
      `;
      overlay.appendChild(flash);
      // Schneestreifen
      for (let i = 0; i < 220; i++) {
        const f = document.createElement('div');
        const x = Math.random() * 125 - 5;
        const dur = 0.5 + Math.random() * 0.7;
        const delay = Math.random() * 1.5;
        const laenge = 10 + Math.random() * 26;
        const breite = 1 + Math.random() * 2.5;
        const deck = 0.25 + Math.random() * 0.6;
        f.style.cssText = `
          position:absolute; left:${x}%; top:0;
          width:${breite}px; height:${laenge}px; border-radius:${breite}px;
          background: linear-gradient(to bottom, rgba(255,255,255,0), rgba(240,252,255,${deck}));
          animation: iceageFlake ${dur}s linear ${delay}s infinite;
        `;
        overlay.appendChild(f);
      }
      document.body.appendChild(overlay);
      if (window.playSFX) {
        window.playSFX('elem_ice', { category: null, volume: 1.0 });
        window.playSFX('elem_wind', { category: null, delay: 180, volume: .9, dedupe: 0 });
      }
      setTimeout(() => { overlay.style.transition = 'opacity 320ms'; overlay.style.opacity = '0'; }, 2300);
      setTimeout(() => overlay.remove(), 2700);
    };
    socket.on('iceage_blizzard', onIceageBlizzard);

    // ★ v1318 — COLD-HEARTED YUKI-ONNA: eisige Winde ueber dem GEGNER-Feld
    // (Als Vorgabe 23.9.: „ein Blizzard, der das Gegner-Feld einhuellt und
    // an Heftigkeit mit der Anzahl Hearts of Ice skaliert"). Stufe 1–4:
    //   • mehr und schnellere Schneestreifen, flacherer Windwinkel,
    //   • Boeen (breite weisse Windbaender) ab Stufe 2, mehr je Stufe,
    //   • dichterer Schleier und Reif von den Raendern,
    //   • ab Stufe 3 ruettelt das Feld, ab 4 ein Kaelteblitz.
    // Eingegrenzt auf die Bretthaelfte des Ziels: das Rechteck um dessen
    // Helden-, Support-, Ability- und Surprise-Zonen (+ Rand).
    const onYukiBlizzard = ({ targetIdx, intensity }) => {
      if (window._playAnimations === false) return;
      const stufe = Math.max(1, Math.min(4, intensity || 1));
      const seite = targetIdx === myIdx ? 'me' : 'opp';
      const els = document.querySelectorAll(
        `[data-hero-owner="${seite}"], [data-support-owner="${seite}"], [data-ability-owner="${seite}"], [data-surprise-owner="${seite}"]`);
      let l = Infinity, t = Infinity, r = -Infinity, b = -Infinity;
      els.forEach(el => { const q = el.getBoundingClientRect(); if (!q.width) return; l = Math.min(l, q.left); t = Math.min(t, q.top); r = Math.max(r, q.right); b = Math.max(b, q.bottom); });
      if (!isFinite(l)) { l = 0; r = window.innerWidth; t = seite === 'opp' ? 0 : window.innerHeight / 2; b = seite === 'opp' ? window.innerHeight / 2 : window.innerHeight; }
      const rand = 40;
      l -= rand; t -= rand; r += rand; b += rand;
      const dauer = 1700 + 450 * stufe;
      if (!document.getElementById('yuki-blizzard-keyframes')) {
        const st = document.createElement('style');
        st.id = 'yuki-blizzard-keyframes';
        st.textContent = `
          @keyframes yukiStreak { 0% { transform: translate(0,0) rotate(var(--w)); opacity: 0; } 12% { opacity: 1; } 100% { transform: translate(var(--dx), var(--dy)) rotate(var(--w)); opacity: 0; } }
          @keyframes yukiFlake { 0% { transform: translate(0,0); opacity: 0; } 15% { opacity: .95; } 100% { transform: translate(var(--dx), var(--dy)); opacity: 0; } }
          @keyframes yukiGust { 0% { transform: translateX(-60%) skewX(-18deg); opacity: 0; } 20% { opacity: var(--o); } 80% { opacity: var(--o); } 100% { transform: translateX(160%) skewX(-18deg); opacity: 0; } }
          @keyframes yukiVeil { 0% { opacity: 0; } 20% { opacity: var(--o); } 75% { opacity: calc(var(--o) * .8); } 100% { opacity: 0; } }
          @keyframes yukiShake { 0%,100% { transform: translate(0,0); } 20% { transform: translate(-3px,1px); } 40% { transform: translate(3px,-2px); } 60% { transform: translate(-2px,2px); } 80% { transform: translate(2px,-1px); } }
          @keyframes yukiFlash { 0% { opacity: 0; } 8% { opacity: .6; } 25% { opacity: 0; } 100% { opacity: 0; } }
        `;
        document.head.appendChild(st);
      }
      const box = document.createElement('div');
      box.className = 'yuki-blizzard';
      box.style.cssText = `position:fixed;left:${l}px;top:${t}px;width:${r - l}px;height:${b - t}px;z-index:9600;pointer-events:none;overflow:hidden;border-radius:18px;`
        + (stufe >= 3 ? `animation:yukiShake ${160 - stufe * 20}ms linear ${Math.round(dauer * 0.15)}ms ${Math.round(dauer * 0.5 / (160 - stufe * 20))};` : '');
      const w = r - l, h = b - t;
      // Schleier + Reif von den Raendern
      const veil = document.createElement('div');
      veil.style.cssText = `position:absolute;inset:0;--o:${0.25 + stufe * 0.14};`
        + `background:radial-gradient(ellipse at 50% 50%, rgba(170,215,245,.35) 0%, rgba(200,235,255,.55) 60%, rgba(235,250,255,.85) 100%);`
        + `animation:yukiVeil ${dauer}ms ease-out forwards;`;
      box.appendChild(veil);
      // Schneestreifen: Wind von links, flacher und schneller je Stufe
      const winkel = 40 + stufe * 9;           // Grad gegen die Senkrechte — je heftiger, desto waagerechter
      const rad = winkel * Math.PI / 180;
      const weg = Math.max(w, h) * 1.5;
      for (let i = 0; i < 70 + stufe * 55; i++) {
        const f = document.createElement('div');
        const dur = (0.75 - stufe * 0.11) + Math.random() * 0.35;
        const len = 14 + Math.random() * (16 + stufe * 10);
        const br = 1 + Math.random() * 2;
        f.style.cssText = `position:absolute;left:${Math.random() * 130 - 45}%;top:${Math.random() * 110 - 25}%;width:${br}px;height:${len}px;border-radius:${br}px;`
          + `background:linear-gradient(to bottom, rgba(255,255,255,0), rgba(245,252,255,${0.4 + Math.random() * 0.5}));`
          + `--w:${-winkel}deg;--dx:${Math.round(Math.sin(rad) * weg)}px;--dy:${Math.round(Math.cos(rad) * weg)}px;`
          + `animation:yukiStreak ${dur}s linear ${Math.random() * dauer * 0.6 / 1000}s ${Math.ceil(dauer / 1000 / dur)};opacity:0;`;
        box.appendChild(f);
      }
      // Wirbelnde Flocken
      for (let i = 0; i < 20 + stufe * 18; i++) {
        const s = 2 + Math.random() * 4;
        const f = document.createElement('div');
        f.style.cssText = `position:absolute;left:${Math.random() * 100 - 10}%;top:${Math.random() * 100}%;width:${s}px;height:${s}px;border-radius:50%;background:rgba(255,255,255,.95);box-shadow:0 0 4px rgba(210,240,255,.9);`
          + `--dx:${Math.round(w * (0.35 + stufe * 0.15) * (0.6 + Math.random()))}px;--dy:${Math.round((Math.random() - 0.3) * h * 0.5)}px;`
          + `animation:yukiFlake ${1.1 - stufe * 0.12 + Math.random() * 0.5}s ease-in ${Math.random() * dauer * 0.55 / 1000}s 2;opacity:0;`;
        box.appendChild(f);
      }
      // Boeen
      for (let i = 0; i < (stufe - 1) * 2; i++) {
        const g = document.createElement('div');
        g.style.cssText = `position:absolute;left:0;top:${8 + Math.random() * 78}%;width:60%;height:${10 + Math.random() * 18}%;`
          + `background:linear-gradient(90deg, rgba(255,255,255,0), rgba(235,248,255,.55), rgba(255,255,255,0));filter:blur(6px);--o:${0.45 + stufe * 0.1};`
          + `animation:yukiGust ${900 - stufe * 90}ms ease-in-out ${Math.round(150 + Math.random() * dauer * 0.55)}ms 1 both;`;
        box.appendChild(g);
      }
      if (stufe >= 4) {
        const flash = document.createElement('div');
        flash.style.cssText = `position:absolute;inset:0;background:rgba(240,252,255,.95);animation:yukiFlash ${dauer}ms ease-out forwards;`;
        box.appendChild(flash);
      }
      document.body.appendChild(box);
      if (window.playSFX) {
        window.playSFX('elem_wind', { rate: 0.8 + stufe * 0.05, volume: 0.45 + stufe * 0.12, category: null, dedupe: 0 });
        if (stufe >= 2) window.playSFX('elem_wind', { rate: 1.15, volume: 0.35 + stufe * 0.08, delay: 280, category: null, dedupe: 0 });
        if (stufe >= 3) window.playSFX('elem_wind', { rate: 0.65, volume: 0.5, delay: 620, category: null, dedupe: 0 });
        window.playSFX('elem_ice', { rate: 1.1 - stufe * 0.05, volume: 0.5 + stufe * 0.1, delay: 380, category: null, dedupe: 0 });
      }
      setTimeout(() => box.remove(), dauer + 200);
    };
    socket.on('yuki_blizzard', onYukiBlizzard);

